@Test
public void TestBinaryPredicates() throws AnalysisException {
    for (String operator : new String[] { "<=>", "IS DISTINCT FROM", "IS NOT DISTINCT FROM", "<", ">", ">=", "<=", "!=", "=", "<>" }) {
        // Operator can compare numeric values (literals, casts, and columns), even ones of
        // different types.
        List<String> numericValues = new ArrayList<String>(Arrays.asList("0", "1", "1.1", "-7", "-7.7", "1.2e99", "false", "1234567890123456789012345678901234567890", "tinyint_col", "smallint_col", "int_col", "bigint_col", "float_col", "double_col"));
        String[] numericTypes = new String[] { "TINYINT", "SMALLINT", "INT", "BIGINT", "FLOAT", "DOUBLE", "DECIMAL" };
        for (String numericType : numericTypes) {
            numericValues.add("cast(NULL as " + numericType + ")");
        }
        for (String lhs : numericValues) {
            for (String rhs : numericValues) {
                AnalyzesOk("select * from functional.alltypes where " + lhs + " " + operator + " " + rhs);
            }
        }
        // Operator can compare identical non-numeric types
        for (String operand : new String[] { "bool_col", "string_col", "timestamp_col", "NULL" }) {
            AnalyzesOk("select * from functional.alltypes where " + operand + " " + operator + " " + operand);
            AnalyzesOk("select * from functional.alltypes where " + operand + " " + operator + " NULL");
            AnalyzesOk("select * from functional.alltypes where NULL " + operator + " " + operand);
        }
        // Operator can compare date columns
        AnalyzesOk("select * from functional.date_tbl where date_col " + operator + " date_col");
        AnalyzesOk("select * from functional.date_tbl where date_col " + operator + " NULL");
        AnalyzesOk("select * from functional.date_tbl where NULL " + operator + " date_col");
        // Operator can compare date column and timestamp column
        AnalyzesOk("select * from functional.date_tbl, functional.alltypes where date_col " + operator + " timestamp_col");
        AnalyzesOk("select * from functional.date_tbl, functional.alltypes where " + "timestamp_col " + operator + " date_col");
        // Operator can compare date column and string literals. This works beacuse the
        // string literal is implicitly converted to date.
        AnalyzesOk("select * from functional.date_tbl where date_col " + operator + " '1993-01-21'");
        // Operator can compare string column and literals
        AnalyzesOk("select * from functional.alltypes where string_col " + operator + " 'hi'");
        // Operator can compare timestamp column and literals
        AnalyzesOk("select * from functional.alltypes where timestamp_col " + operator + " '1993-01-21 02:00:00'");
        // Operator can compare bool column and literals
        AnalyzesOk("select * from functional.alltypes where bool_col " + operator + " true");
        // Operator can compare binary columns and literals.
        AnalyzesOk("select * from functional.binary_tbl where binary_col " + operator + " cast('hi' as binary)");
        // Decimal types of different precisions and scales are comparable
        String[] decimalColumns = new String[] { "d1", "d2", "d3", "d4", "d5", "NULL" };
        for (String operand1 : decimalColumns) {
            for (String operand2 : decimalColumns) {
                AnalyzesOk("select * from functional.decimal_tbl where " + operand1 + " " + operator + " " + operand2);
            }
        }
        // IMPALA-7260: Check that when a numerical type gets implicitly cast to decimal,
        // we do not get an error when the type of the decimal operand is not able to fit
        // all of the digits of the non-deicmal operand.
        AnalyzesOk("select cast(1 as decimal(38,37)) " + operator + " cast(2 as bigint)");
        AnalyzesOk("select cast(1 as bigint) " + operator + " cast(2 as decimal(38,37))");
        AnalyzesOk("select cast(1 as decimal(38,1)) " + operator + " cast(2 as bigint)");
        AnalyzesOk("select cast(1 as decimal(38,37)) " + operator + " cast(2 as tinyint)");
        AnalyzesOk("select cast(1 as decimal(38,37)) " + operator + " cast(2 as double)");
        // Chars of different length are comparable
        for (int i = 1; i < 16; ++i) {
            AnalyzesOk("select cast('hi' as char(" + i + ")) " + operator + " 'hi'");
            AnalyzesOk("select cast('hi' as char(" + i + ")) " + operator + " NULL");
            for (int j = 1; j < 16; ++j) {
                AnalyzesOk("select cast('hi' as char(" + i + ")) " + operator + " cast('hi' as char(" + j + "))");
            }
        }
        // Binary operators do not operate on expression with incompatible types
        for (String numeric_type : new String[] { "BOOLEAN", "TINYINT", "SMALLINT", "INT", "BIGINT", "FLOAT", "DOUBLE", "DECIMAL(9,0)" }) {
            for (String string_type : new String[] { "STRING", "BINARY", "TIMESTAMP", "DATE" }) {
                AnalysisError("select cast(NULL as " + numeric_type + ") " + operator + " cast(NULL as " + string_type + ")", "operands of type " + numeric_type + " and " + string_type + " are not comparable:");
                AnalysisError("select cast(NULL as " + string_type + ") " + operator + " cast(NULL as " + numeric_type + ")", "operands of type " + string_type + " and " + numeric_type + " are not comparable:");
            }
        }
    }
    // invalid casts
    AnalysisError("select * from functional.alltypes where bool_col = '15'", "operands of type BOOLEAN and STRING are not comparable: bool_col = '15'");
    // Complex types are not comparable.
    AnalysisError("select 1 from functional.allcomplextypes where int_array_col = 1", "operands of type ARRAY<INT> and TINYINT are not comparable: int_array_col = 1");
    AnalysisError("select 1 from functional.allcomplextypes where int_map_col = 1", "operands of type MAP<STRING,INT> and TINYINT are not comparable: " + "int_map_col = 1");
    AnalysisError("select 1 from functional_orc_def.complextypes_structs where " + "tiny_struct = true", "operands of type STRUCT<b:BOOLEAN> and BOOLEAN are not comparable: " + "tiny_struct = TRUE");
    // Complex types are not comparable even if identical.
    // TODO: Reconsider this behavior. Such a comparison should ideally work,
    // but may require complex-typed SlotRefs and BE functions able to accept
    // complex-typed parameters.
    AnalysisError("select 1 from functional.allcomplextypes " + "where int_map_col = int_map_col", "operands of type MAP<STRING,INT> and MAP<STRING,INT> are not comparable: " + "int_map_col = int_map_col");
    AnalysisError("select * from functional.date_tbl where date_col = 15", "operands of type DATE and TINYINT are not comparable: date_col = 15");
    // TODO: Enable once datetime is implemented.
    // AnalysisError("select * from functional.alltypes where datetime_col = 1.0",
    // "operands are not comparable: datetime_col = 1.0");
}

@Test
public void TestDecimalCasts() throws AnalysisException {
    AnalyzesOk("select cast(1.1 as boolean)");
    AnalyzesOk("select cast(1.1 as timestamp)");
    AnalysisError("select cast(1.1 as date)", "Invalid type cast of 1.1 from DECIMAL(2,1) to DATE");
    AnalysisError("select cast(true as decimal)", "Invalid type cast of TRUE from BOOLEAN to DECIMAL(9,0)");
    AnalysisError("select cast(cast(1 as timestamp) as decimal)", "Invalid type cast of CAST(1 AS TIMESTAMP) from TIMESTAMP to DECIMAL(9,0)");
    AnalysisError("select cast(date '1970-01-01' as decimal)", "Invalid type cast of DATE '1970-01-01' from DATE to DECIMAL(9,0)");
    AnalysisError("select cast(cast(\"1.1\" as binary) as decimal)", "Invalid type cast of CAST('1.1' AS BINARY) from BINARY to DECIMAL(9,0)");
    for (Type type : Type.getSupportedTypes()) {
        if (type.isNull() || type.isDecimal() || type.isBoolean() || type.isDateOrTimeType() || type.getPrimitiveType() == PrimitiveType.VARCHAR || type.getPrimitiveType() == PrimitiveType.CHAR || type.getPrimitiveType() == PrimitiveType.BINARY) {
            continue;
        }
        AnalyzesOk("select cast(1.1 as " + type + ")");
        AnalyzesOk("select cast(cast(1 as " + type + ") as decimal)");
    }
    // Casts to all other decimals are supported.
    for (int precision = 1; precision <= ScalarType.MAX_PRECISION; ++precision) {
        for (int scale = 0; scale < precision; ++scale) {
            Type t = ScalarType.createDecimalType(precision, scale);
            AnalyzesOk("select cast(1.1 as " + t.toSql() + ")");
            AnalyzesOk("select cast(cast(1 as " + t.toSql() + ") as decimal)");
        }
    }
    AnalysisError("select cast(1 as decimal(0, 1))", "Decimal precision must be > 0: 0");
    // IMPALA-2264: decimal is implicitly cast to lower-precision integer in edge cases.
    checkDecimalReturnType("select CAST(999 AS DECIMAL(3,0))", ScalarType.createDecimalType(3, 0));
    AnalysisError("insert into functional.alltypesinsert (tinyint_col, year, month) " + "values(CAST(999 AS DECIMAL(3,0)), 1, 1)", "Possible loss of precision for target table 'functional.alltypesinsert'.\n" + "Expression 'CAST(999 AS DECIMAL(3,0))' (type: DECIMAL(3,0)) would need to be " + "cast to TINYINT for column 'tinyint_col'");
}

@Test
public void TestStringCasts() throws AnalysisException {
    // No implicit cast from STRING to numeric and boolean
    AnalysisError("select * from functional.alltypes where tinyint_col = '1'", "operands of type TINYINT and STRING are not comparable: tinyint_col = '1'");
    AnalysisError("select * from functional.alltypes where bool_col = '0'", "operands of type BOOLEAN and STRING are not comparable: bool_col = '0'");
    // No explicit cast from STRING to boolean.
    AnalysisError("select cast('false' as boolean) from functional.alltypes", "Invalid type cast of 'false' from STRING to BOOLEAN");
    AnalyzesOk("select * from functional.alltypes where " + "tinyint_col = cast('0.5' as float)");
    AnalyzesOk("select * from functional.alltypes where " + "smallint_col = cast('0.5' as float)");
    AnalyzesOk("select * from functional.alltypes where int_col = cast('0.5' as float)");
    AnalyzesOk("select * from functional.alltypes where " + "bigint_col = cast('0.5' as float)");
    AnalyzesOk("select 1.0 = cast('" + Double.toString(Double.MIN_VALUE) + "' as double)");
    AnalyzesOk("select 1.0 = cast('-" + Double.toString(Double.MIN_VALUE) + "' as double)");
    AnalyzesOk("select 1.0 = cast('" + Double.toString(Double.MAX_VALUE) + "' as double)");
    AnalyzesOk("select 1.0 = cast('-" + Double.toString(Double.MAX_VALUE) + "' as double)");
    // Test chains of minus. Note that "--" is the a comment symbol.
    AnalyzesOk("select * from functional.alltypes where " + "tinyint_col = cast('-1' as tinyint)");
    AnalyzesOk("select * from functional.alltypes where " + "tinyint_col = cast('- -1' as tinyint)");
    AnalyzesOk("select * from functional.alltypes where " + "tinyint_col = cast('- - -1' as tinyint)");
    AnalyzesOk("select * from functional.alltypes where " + "tinyint_col = cast('- - - -1' as tinyint)");
    // Test correct casting to compatible type on bitwise ops.
    AnalyzesOk("select 1 | cast('" + Byte.toString(Byte.MIN_VALUE) + "' as int)");
    AnalyzesOk("select 1 | cast('" + Byte.toString(Byte.MAX_VALUE) + "' as int)");
    AnalyzesOk("select 1 | cast('" + Short.toString(Short.MIN_VALUE) + "' as int)");
    AnalyzesOk("select 1 | cast('" + Short.toString(Short.MAX_VALUE) + "' as int)");
    AnalyzesOk("select 1 | cast('" + Integer.toString(Integer.MIN_VALUE) + "' as int)");
    AnalyzesOk("select 1 | cast('" + Integer.toString(Integer.MAX_VALUE) + "' as int)");
    // We need to add 1 to MIN_VALUE because there are no negative integer literals.
    // The reason is that whether a minus belongs to an
    // arithmetic expr or a literal must be decided by the parser, not the lexer.
    AnalyzesOk("select 1 | cast('" + Long.toString(Long.MIN_VALUE + 1) + "' as bigint)");
    AnalyzesOk("select 1 | cast('" + Long.toString(Long.MAX_VALUE) + "' as bigint)");
    // Cast to numeric never overflow
    AnalyzesOk("select * from functional.alltypes where tinyint_col = " + "cast('" + Long.toString(Long.MIN_VALUE) + "1' as tinyint)");
    AnalyzesOk("select * from functional.alltypes where tinyint_col = " + "cast('" + Long.toString(Long.MAX_VALUE) + "1' as tinyint)");
    AnalyzesOk("select * from functional.alltypes where tinyint_col = " + "cast('" + Double.toString(Double.MAX_VALUE) + "1' as tinyint)");
    // Java converts a float underflow to 0.0.
    // Since there is no easy, reliable way to detect underflow,
    // we don't consider it an error.
