@Test
public void TestExprChildLimit() {
    // Test IN predicate.
    StringBuilder inPredStr = new StringBuilder("select 1 IN(");
    for (int i = 0; i < Expr.EXPR_CHILDREN_LIMIT - 1; ++i) {
        inPredStr.append(i);
        if (i + 1 != Expr.EXPR_CHILDREN_LIMIT - 1)
            inPredStr.append(", ");
    }
    AnalyzesOk(inPredStr.toString() + ")");
    inPredStr.append(", " + 1234);
    AnalysisError(inPredStr.toString() + ")", String.format("Exceeded the maximum number of child expressions (%d).\n" + "Expression has %s children", Expr.EXPR_CHILDREN_LIMIT, Expr.EXPR_CHILDREN_LIMIT + 1));
    // Test CASE expr.
    StringBuilder caseExprStr = new StringBuilder("select case");
    for (int i = 0; i < Expr.EXPR_CHILDREN_LIMIT / 2; ++i) {
        caseExprStr.append(" when true then 1");
    }
    AnalyzesOk(caseExprStr.toString() + " end");
    caseExprStr.append(" when true then 1");
    AnalysisError(caseExprStr.toString() + " end", String.format("Exceeded the maximum number of child expressions (%d).\n" + "Expression has %s children", Expr.EXPR_CHILDREN_LIMIT, Expr.EXPR_CHILDREN_LIMIT + 2));
}

