@Test
public void TestCreateExternalKuduTable() {
    final String kuduMasters = catalog_.getDefaultKuduMasterHosts();
    AnalyzesOk("create external table t stored as kudu " + "tblproperties('kudu.table_name'='t')");
    // Use all allowed optional table props.
    AnalyzesOk(String.format("create external table t stored as kudu tblproperties (" + "'kudu.table_name'='tab', 'kudu.master_addresses' = '%s', " + "'storage_handler'='org.apache.hadoop.hive.kudu.KuduStorageHandler')", kuduMasters));
    // Kudu table should be specified using the STORED AS KUDU syntax.
    AnalysisError("create external table t tblproperties (" + "'storage_handler'='com.cloudera.kudu.hive.KuduStorageHandler'," + "'kudu.table_name'='t')", CreateTableStmt.KUDU_STORAGE_HANDLER_ERROR_MESSAGE);
    AnalysisError("create external table t tblproperties (" + "'storage_handler'='org.apache.hadoop.hive.kudu.KuduStorageHandler'," + "'kudu.table_name'='t')", CreateTableStmt.KUDU_STORAGE_HANDLER_ERROR_MESSAGE);
    // Columns should not be specified in an external Kudu table
    AnalysisError("create external table t (x int) stored as kudu " + "tblproperties('kudu.table_name'='t')", "Columns cannot be specified with an external Kudu table.");
    // Primary keys cannot be specified in an external Kudu table
    AnalysisError("create external table t (x int primary key) stored as kudu " + "tblproperties('kudu.table_name'='t')", "Primary keys cannot be specified " + "for an external Kudu table");
    // Invalid syntax for specifying a Kudu table
    AnalysisError("create external table t (x int) stored as parquet tblproperties (" + "'storage_handler'='com.cloudera.kudu.hive.KuduStorageHandler'," + "'kudu.table_name'='t')", CreateTableStmt.KUDU_STORAGE_HANDLER_ERROR_MESSAGE);
    AnalysisError("create external table t (x int) stored as parquet tblproperties (" + "'storage_handler'='org.apache.hadoop.hive.kudu.KuduStorageHandler'," + "'kudu.table_name'='t')", CreateTableStmt.KUDU_STORAGE_HANDLER_ERROR_MESSAGE);
    AnalysisError("create external table t stored as kudu tblproperties (" + "'storage_handler'='foo', 'kudu.table_name'='t')", "Invalid storage handler specified for Kudu table: foo");
    // Cannot specify the number of replicas for external Kudu tables
    AnalysisError("create external table tab (x int) stored as kudu " + "tblproperties ('kudu.num_tablet_replicas' = '1', " + "'kudu.table_name'='tab')", "Table property 'kudu.num_tablet_replicas' cannot be used with an external " + "Kudu table.");
    // Don't allow caching
    AnalysisError("create external table t stored as kudu cached in 'testPool' " + "tblproperties('kudu.table_name'='t')", "A Kudu table cannot be cached in HDFS.");
    // LOCATION cannot be used for a Kudu table
    AnalysisError("create external table t stored as kudu " + "location '/test-warehouse' tblproperties('kudu.table_name'='t')", "LOCATION cannot be specified for a Kudu table.");
    // External table is not allowed to set table property 'kudu.table_id'.
    AnalysisError("create external table t stored as kudu tblproperties " + "('kudu.table_name'='t', 'kudu.table_id'='123456')", String.format("Table property %s should not be specified when creating " + "a Kudu table.", KuduTable.KEY_TABLE_ID));
    // External table is not allowed to set table property 'kudu.table_name'
    AnalysisError("create external table t stored as kudu tblproperties " + "('external.table.purge'='true', 'kudu.table_name'='t')", "Not allowed to set 'kudu.table_name' manually for synchronized Kudu tables");
    // trying to create the legacy external table syntax with external.table.purge
    // property should error out
    AnalysisError("create external table t stored as kudu tblproperties " + "('external.table.purge'='true')", "A primary key is required for a Kudu table.");
}

@Test
public void TestAlterKuduTable() {
    // ALTER TABLE ADD/DROP range partitions
    String[] addDrop = { "add if not exists", "add", "drop if exists", "drop" };
    for (String kw : addDrop) {
        AnalyzesOk(String.format("alter table functional_kudu.testtbl %s range " + "partition 10 <= values < 20", kw));
        AnalyzesOk(String.format("alter table functional_kudu.testtbl %s range " + "partition value = 30", kw));
