/**
 * We distinguish between three classes of unsupported types:
 * 1. Complex types, e.g., map
 *    For tables with such types we prevent loading the table metadata.
 * 2. Primitive types
 *    For tables with unsupported primitive types (e.g. datetime)
 *    we can run queries as long as the unsupported columns are not referenced.
 *    We fail analysis if a query references an unsupported primitive column.
 * 3. Partition-column types
 *    We do not support table partitioning on timestamp columns
 */
@Test
public void TestUnsupportedTypes() {
    // With DATE and BINARY support Impala can now handle the same scalar types as Hive.
    // There is still some gap in supported types for partition columns.
    // Unsupported partition-column type.
    AnalysisError("select * from functional.unsupported_timestamp_partition", "Failed to load metadata for table: " + "'functional.unsupported_timestamp_partition'");
    AnalysisError("select * from functional.unsupported_binary_partition", "Failed to load metadata for table: 'functional.unsupported_binary_partition'");
    // Try with hbase
    AnalyzesOk("describe functional_hbase.allcomplextypes");
    // Returning complex types with BINARY in select list is not yet implemented
    // (IMPALA-11491). Note that this is also problematic in Hive (HIVE-26454).
    AnalysisError("select binary_item_col from functional_parquet.binary_in_complex_types", "Binary type inside collection types is not supported (IMPALA-11491).");
    AnalysisError("select binary_member_col from functional_parquet.binary_in_complex_types", "Struct containing a BINARY type is not allowed in the select list " + "(IMPALA-11491).");
    AnalysisError("select binary_key_col from functional_parquet.binary_in_complex_types", "Binary type inside collection types is not supported (IMPALA-11491).");
    AnalysisError("select binary_value_col from functional_parquet.binary_in_complex_types", "Binary type inside collection types is not supported (IMPALA-11491).");
    for (ScalarType t : Type.getUnsupportedTypes()) {
        // Create/Alter table.
        AnalysisError(String.format("create table new_table (new_col %s)", t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        AnalysisError(String.format("create table new_table (new_col int) PARTITIONED BY (p_col %s)", t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        AnalysisError(String.format("alter table functional.alltypes add columns (new_col %s)", t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        AnalysisError(String.format("alter table functional.alltypes change column int_col new_col %s", t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        // UDFs.
        final String udfSuffix = " LOCATION '/test-warehouse/libTestUdfs.so' " + "SYMBOL='_Z8IdentityPN10impala_udf15FunctionContextERKNS_10BooleanValE'";
        AnalysisError(String.format("create function foo(VARCHAR(5)) RETURNS %s" + udfSuffix, t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        AnalysisError(String.format("create function foo(%s) RETURNS int" + udfSuffix, t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        // UDAs.
        final String udaSuffix = " LOCATION '/test-warehouse/libTestUdas.so' " + "UPDATE_FN='AggUpdate'";
        AnalysisError(String.format("create aggregate function foo(string, double) " + "RETURNS %s" + udaSuffix, t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        AnalysisError(String.format("create aggregate function foo(%s, double) " + "RETURNS int" + udaSuffix, t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
        // Cast,
        AnalysisError(String.format("select cast('abc' as %s)", t.toSql()), String.format("Unsupported data type: %s", t.toSql()));
    }
}

