@Test
public void TestResetMetadata() {
    BiConsumer<ParseNode, ResetMetadataStmt.Action> assertAction = (parseNode, action) -> {
        Preconditions.checkArgument(parseNode instanceof ResetMetadataStmt);
        assertEquals(action, ((ResetMetadataStmt) parseNode).getAction());
    };
    assertAction.accept(AnalyzesOk("invalidate metadata"), ResetMetadataStmt.Action.INVALIDATE_METADATA_ALL);
    assertAction.accept(AnalyzesOk("invalidate metadata functional.alltypessmall"), ResetMetadataStmt.Action.INVALIDATE_METADATA_TABLE);
    assertAction.accept(AnalyzesOk("invalidate metadata functional.alltypes_view"), ResetMetadataStmt.Action.INVALIDATE_METADATA_TABLE);
    assertAction.accept(AnalyzesOk("invalidate metadata functional.bad_serde"), ResetMetadataStmt.Action.INVALIDATE_METADATA_TABLE);
    assertAction.accept(AnalyzesOk("refresh functional.alltypessmall"), ResetMetadataStmt.Action.REFRESH_TABLE);
    assertAction.accept(AnalyzesOk("refresh functional.alltypes_view"), ResetMetadataStmt.Action.REFRESH_TABLE);
    assertAction.accept(AnalyzesOk("refresh functional.bad_serde"), ResetMetadataStmt.Action.REFRESH_TABLE);
    assertAction.accept(AnalyzesOk("refresh functional.alltypessmall partition (year=2009, month=1)"), ResetMetadataStmt.Action.REFRESH_PARTITION);
    assertAction.accept(AnalyzesOk("refresh functional.alltypessmall partition (year=2009, month=NULL)"), ResetMetadataStmt.Action.REFRESH_PARTITION);
    assertAction.accept(AnalyzesOk("refresh authorization", createAnalysisCtx(createAuthorizationFactory())), ResetMetadataStmt.Action.REFRESH_AUTHORIZATION);
    // invalidate metadata <table name> checks the Hive Metastore for table existence
