@Test
public void TestStar() throws AnalysisException {
    AnalyzesOk("select * from functional.AllTypes");
    AnalyzesOk("select functional.alltypes.* from functional.AllTypes");
    // different db
    AnalyzesOk("select functional_seq.alltypes.* from functional_seq.alltypes");
    // two tables w/ identical names from different dbs
    AnalyzesOk("select functional.alltypes.*, functional_seq.alltypes.* " + "from functional.alltypes, functional_seq.alltypes");
    AnalyzesOk("select * from functional.alltypes, functional_seq.alltypes");
    // expand '*' on a struct-typed column
    AnalyzesOk("select int_struct_col.* from functional.allcomplextypes");
    AnalyzesOk("select a.int_struct_col.* from functional.allcomplextypes a");
    AnalyzesOk("select allcomplextypes.int_struct_col.* from functional.allcomplextypes");
    AnalyzesOk("select functional.allcomplextypes.int_struct_col.* " + "from functional.allcomplextypes");
    // '*' without from clause has no meaning.
    AnalysisError("select *", "'*' expression in select list requires FROM clause.");
    AnalysisError("select 1, *, 2+4", "'*' expression in select list requires FROM clause.");
    AnalysisError("select a.*", "Could not resolve star expression: 'a.*'");
    // invalid star expansions
    AnalysisError("select functional.* from functional.alltypes", "Could not resolve star expression: 'functional.*'");
    AnalysisError("select int_col.* from functional.alltypes", "Cannot expand star in 'int_col.*' because " + "path 'int_col' resolved to type 'INT'.\n" + "Star expansion is only valid for paths to a struct type.");
    AnalysisError("select complex_struct_col.f2.* from functional.allcomplextypes", "Cannot expand star in 'complex_struct_col.f2.*' because " + "path 'complex_struct_col.f2' resolved to type 'ARRAY<INT>'.\n" + "Star expansion is only valid for paths to a struct type.");
    for (String joinType : new String[] { "left semi join", "left anti join" }) {
        // ignore semi-/anti-joined tables in unqualified '*' expansion
        SelectStmt stmt = (SelectStmt) AnalyzesOk(String.format("select * from functional.alltypes a " + "%s functional.testtbl b on (a.id = b.id)", joinType));
        // expect to have as many result exprs as alltypes has columns
        assertEquals(13, stmt.getResultExprs().size());
        // cannot expand '*" for a semi-/anti-joined table
        AnalysisError(String.format("select a.*, b.* from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType), "Illegal star expression 'b.*' of semi-/anti-joined table 'b'");
    }
    for (String joinType : new String[] { "right semi join", "right anti join" }) {
        // ignore semi-/anti-joined tables in unqualified '*' expansion
        SelectStmt stmt = (SelectStmt) AnalyzesOk(String.format("select * from functional.alltypes a " + "%s functional.testtbl b on (a.id = b.id)", joinType));
        // expect to have as many result exprs as testtbl has columns
        assertEquals(3, stmt.getResultExprs().size());
        // cannot expand '*" for a semi-/anti-joined table
        AnalysisError(String.format("select a.*, b.* from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType), "Illegal star expression 'a.*' of semi-/anti-joined table 'a'");
    }
}

/**
 * Test that complex types are supported in the select list.
 */
@Test
public void TestComplexTypesInSelectList() {
    // Star only expands to the scalar-typed fields.
    AnalyzesOk("select * from functional.allcomplextypes " + "cross join functional_parquet.alltypes");
    AnalyzesOk("select complex_struct_col.* from functional.allcomplextypes");
    // The result exprs could be empty after star expansion.
    addTestTable("create table only_complex_types " + "(a array<int>, b struct<x:int, y:int>, c map<string, int>)");
    AnalysisError("select * from only_complex_types", "The star exprs expanded to an empty select list because the referenced " + "tables only have complex-typed columns.");
    AnalysisError("select a.* from only_complex_types a, " + "functional.allcomplextypes b", "The star exprs expanded to an empty select list because the referenced " + "tables only have complex-typed columns.");
    // Empty star expansion, but non empty result exprs.
    AnalyzesOk("select 1, * from only_complex_types");
    // Struct in select list works only if codegen is OFF.
    AnalysisContext ctx = createAnalysisCtx();
    AnalyzesOk("select alltypes from functional_orc_def.complextypes_structs", ctx);
    AnalyzesOk("select int_array_col from functional.allcomplextypes");
    AnalyzesOk("select int_array_col from functional.allcomplextypes " + "union all select int_array_col from functional.allcomplextypes");
    AnalysisError("select int_array_col, item from functional.allcomplextypes", ctx, "Could not resolve column/field reference: 'item'");
    AnalysisError("select int_array_col, int_array_col.item " + "from functional.allcomplextypes", ctx, "Illegal column/field reference 'int_array_col.item' with intermediate " + "collection 'int_array_col' of type 'ARRAY<INT>'");
    AnalysisError("select tiny_struct from functional_orc_def.complextypes_structs " + "union all select tiny_struct from functional_orc_def.complextypes_structs", ctx, "Set operations don't support STRUCT type. STRUCT<b:BOOLEAN> in tiny_struct");
    AnalyzesOk("select 1 from " + "(select int_array_col from functional.allcomplextypes) v");
    AnalyzesOk("select int_array_col from " + "(select int_array_col from functional.allcomplextypes) v");
    // Structs are allowed in an inline view.
    AnalyzesOk("select v.ts from (select tiny_struct as ts from " + "functional_orc_def.complextypes_structs) v;", ctx);
    // Illegal complex-typed expr in an insert.
    AnalysisError("insert into functional.allcomplextypes " + "select int_array_col from functional.allcomplextypes", "Unable to INSERT into target table (functional.allcomplextypes) because " + "the column 'int_array_col' has a complex type 'ARRAY<INT>' and Impala " + "doesn't support inserting into tables containing complex type columns");
    // Illegal complex-typed expr in a CTAS.
    AnalysisError("create table new_tbl as " + "select int_array_col from functional.allcomplextypes", "Unable to INSERT into target table (default.new_tbl) because the column " + "'int_array_col' has a complex type 'ARRAY<INT>' and Impala doesn't support " + "inserting into tables containing complex type columns");
    AnalysisError("create table new_tbl as " + "select tiny_struct from functional_orc_def.complextypes_structs", ctx, "Unable to INSERT into target table (default.new_tbl) because the column " + "'tiny_struct' has a complex type 'STRUCT<b:BOOLEAN>' and Impala doesn't " + "support inserting into tables containing complex type columns");
    //Make complex types available in star queries
    ctx.getQueryOptions().setExpand_complex_types(true);
    AnalyzesOk("select * from functional_parquet.complextypes_structs", ctx);
    AnalyzesOk("select * from functional_parquet.complextypes_nested_structs", ctx);
    AnalyzesOk("select * from functional_parquet.complextypes_maps_view", ctx);
    AnalyzesOk("select outer_struct.str, outer_struct.* from " + "functional_parquet.complextypes_nested_structs", ctx);
    AnalyzesOk("select * from (select * from " + "functional_parquet.complextypes_nested_structs) v", ctx);
    AnalyzesOk("select * from (select int_map, int_map_array from " + "functional_parquet.complextypestbl) v", ctx);
    AnalyzesOk("select * from functional_parquet.complextypes_arrays", ctx);
    AnalyzesOk("select * from " + "functional_parquet.complextypes_arrays_only_view", ctx);
    AnalyzesOk("select v.id, v.* from " + "(select * from functional_parquet.complextypes_arrays) v", ctx);
    // Allow also structs in collections and vice versa.
    AnalyzesOk("select * from functional_parquet.allcomplextypes", ctx);
    AnalyzesOk("select * from functional_orc_def.complextypestbl", ctx);
    AnalysisError("select * from functional_parquet.binary_in_complex_types", ctx, "Binary type inside collection types is not supported (IMPALA-11491).");
}

@Test
public void TestGroupByAliases() throws AnalysisException {
    // IMPALA-5191: GROUP BY, aliases must only be
    // substituted at the top level
    AnalyzesOk("select int_col / 2 as x from functional.alltypes group by x");
    // GROUP BY contains alias in subexpression
    AnalysisError("select int_col / 2 as x from functional.alltypes group by x / 2", "Could not resolve column/field reference: 'x'");
    // Alias referring to aggregation output in GROUP BY
    AnalysisError("select count(*) a from functional.alltypes group by a", "GROUP BY expression must not contain aggregate functions: a");
    // Alias referring to predicate in GROUP BY
    AnalysisError("select count(*) > 10 a from functional.alltypes group by a", "GROUP BY expression must not contain aggregate functions: a");
    // Alias referring to analytic output in GROUP BY
    AnalysisError("select sum(id) over(order by id) a " + "from functional.alltypes group by a", "GROUP BY expression must not contain analytic expressions: " + "sum(id) OVER (ORDER BY id ASC)");
    // Alias referring to analytic output in GROUP BY
    AnalyzesOk("with w_test as (select '1' as `one`, 2 as two, '3' as three) " + "select `one` as `one`, substring(cast(two as string), 1, 1) as two, " + "three as three, count(1) as cnt " + "from w_test " + "group by `one`, substring(cast(two as string), 1, 1), three");
}

