@Test
public void TestInsertHints() throws AnalysisException {
    // Test table to make sure that conflicting hints and table properties result in a
    // warning.
    addTestDb("test_sort_by", "Test DB for SORT BY clause.");
    addTestTable("create table test_sort_by.alltypes (id int, int_col int, " + "bool_col boolean) partitioned by (year int, month int) " + "sort by (int_col, bool_col) location '/'");
    for (String[] hintStyle : getHintStyles()) {
        String prefix = hintStyle[0];
        String suffix = hintStyle[1];
        // Test plan hints for partitioned Hdfs tables.
        AnalyzesOk(String.format("insert into functional.alltypessmall " + "partition (year, month) %sshuffle%s select * from functional.alltypes", prefix, suffix));
        AnalyzesOk(String.format("insert into table functional.alltypessmall " + "partition (year, month) %snoshuffle%s select * from functional.alltypes", prefix, suffix));
        // Only warn on unrecognized hints.
        AnalyzesOk(String.format("insert into functional.alltypessmall " + "partition (year, month) %sbadhint%s select * from functional.alltypes", prefix, suffix), "INSERT hint not recognized: badhint");
        // Insert hints are ok for unpartitioned tables.
        AnalyzesOk(String.format("insert into table functional.alltypesnopart %sshuffle%s " + "select * from functional.alltypesnopart", prefix, suffix));
        // Insert hints are ok for Kudu tables.
        AnalyzesOk(String.format("insert into table functional_kudu.alltypes %sshuffle%s " + "select * from functional_kudu.alltypes", prefix, suffix));
        // Plan hints do not make sense for inserting into HBase tables.
        AnalysisError(String.format("insert into table functional_hbase.alltypes %sshuffle%s " + "select * from functional_hbase.alltypes", prefix, suffix), "INSERT hints are only supported for inserting into Hdfs and Kudu tables: " + "functional_hbase.alltypes");
        // Conflicting plan hints.
        AnalysisError("insert into table functional.alltypessmall " + "partition (year, month) /* +shuffle,noshuffle */ " + "select * from functional.alltypes", "Conflicting INSERT hints: shuffle and noshuffle");
        // Test clustered hint.
        AnalyzesOk(String.format("insert into functional.alltypessmall partition (year, month) %sclustered%s " + "select * from functional.alltypes", prefix, suffix));
        AnalyzesOk(String.format("insert into table functional.alltypesnopart %sclustered%s " + "select * from functional.alltypesnopart", prefix, suffix));
        // Test that noclustered is accepted.
        AnalyzesOk(String.format("insert into table functional.alltypesnopart %snoclustered%s " + "select * from functional.alltypesnopart", prefix, suffix));
        // Conflicting clustered hints.
        AnalysisError(String.format("insert into table functional.alltypessmall partition (year, month) " + "/* +clustered,noclustered */ select * from functional.alltypes", prefix, suffix), "Conflicting INSERT hints: clustered and noclustered");
        // noclustered hint on a table with sort.columns issues a warning.
        AnalyzesOk(String.format("insert into test_sort_by.alltypes partition (year, month) " + "%snoclustered%s select id, int_col, bool_col, year, month from " + "functional.alltypes", prefix, suffix), "Insert statement has 'noclustered' hint, but table has 'sort.columns' " + "property. The 'noclustered' hint will be ignored.");
        // Default hints should be ignored when query has plan hints.
        testDefaultHintIgnored(String.format("insert into functional.alltypes partition (year, month) " + "%snoclustered,shuffle%s select * from functional.alltypes", prefix, suffix), "CLUSTERED");
        testDefaultHintIgnored(String.format("insert into functional_kudu.alltypes " + "%snoclustered,shuffle%s select * from functional.alltypes", prefix, suffix), "CLUSTERED : NOSHUFFLE ");
    }
    // Multiple non-conflicting hints and case insensitivity of hints.
    AnalyzesOk("insert into table functional.alltypessmall " + "partition (year, month) /* +shuffle, ShUfFlE */ " + "select * from functional.alltypes");
    AnalyzesOk("insert into table functional.alltypessmall " + "partition (year, month) [shuffle, ShUfFlE] " + "select * from functional.alltypes");
    // Test default hints.
    AnalysisContext insertCtx = createAnalysisCtx();
    // Bad hint returns a warning.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("badhint");
    AnalyzesOk("insert into functional.alltypessmall partition (year, month) " + "select * from functional.alltypes", insertCtx, "INSERT hint not recognized: badhint");
    // Bad hint returns a warning.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("clustered:noshuffle:badhint");
    AnalyzesOk("insert into functional.alltypessmall partition (year, month) " + "select * from functional.alltypes", insertCtx, "INSERT hint not recognized: badhint");
    // Conflicting hints return an error.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("clustered:noclustered");
    AnalysisError("insert into functional.alltypessmall partition (year, month) " + "select * from functional.alltypes", insertCtx, "Conflicting INSERT hints: clustered and noclustered");
    // Conflicting hints return an error.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("shuffle:noshuffle");
    AnalysisError("insert into functional.alltypessmall partition (year, month) " + "select * from functional.alltypes", insertCtx, "Conflicting INSERT hints: shuffle and noshuffle");
    // Default hints ignored for HBase table.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("noclustered");
    AnalyzesOk("insert into table functional_hbase.alltypes " + "select * from functional_hbase.alltypes", insertCtx);
    // Default hints are ok for Kudu table.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("clustered:noshuffle");
    AnalyzesOk(String.format("insert into table functional_kudu.alltypes " + "select * from functional_kudu.alltypes"), insertCtx);
    testDefaultHintApplied(insertCtx);
    // Default hints are ok for partitioned Hdfs tables.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("NOCLUSTERED:noshuffle");
    AnalyzesOk("insert into functional.alltypessmall partition (year, month) " + "select * from functional.alltypes", insertCtx);
    testDefaultHintApplied(insertCtx);
    // Default hints are ok for non partitioned Hdfs tables.
    insertCtx.getQueryOptions().setDefault_hints_insert_statement("CLUSTERED:SHUFFLE");
    AnalyzesOk("insert into functional.alltypesnopart " + "select * from functional.alltypesnopart", insertCtx);
    testDefaultHintApplied(insertCtx);
}

@Test
public void TestWhereClause() throws AnalysisException {
    AnalyzesOk("select zip, name from functional.testtbl where id > 15");
    AnalysisError("select zip, name from functional.testtbl where badcol > 15", "Could not resolve column/field reference: 'badcol'");
    AnalyzesOk("select * from functional.testtbl where true");
    AnalysisError("select * from functional.testtbl where count(*) > 0", "aggregate function not allowed in WHERE clause");
    // NULL and bool literal in binary predicate.
    for (BinaryPredicate.Operator op : BinaryPredicate.Operator.values()) {
        AnalyzesOk("select id from functional.testtbl where id " + op.toString() + " true");
        AnalyzesOk("select id from functional.testtbl where id " + op.toString() + " false");
        AnalyzesOk("select id from functional.testtbl where id " + op.toString() + " NULL");
    }
    // Where clause is a SlotRef of type bool.
    AnalyzesOk("select id from functional.alltypes where bool_col");
    // Arbitrary exprs that do not return bool.
    AnalysisError("select id from functional.alltypes where int_col", "WHERE clause requires return type 'BOOLEAN'. Actual type is 'INT'.");
    AnalysisError("select id from functional.alltypes where trim('abc')", "WHERE clause requires return type 'BOOLEAN'. Actual type is 'STRING'.");
    AnalysisError("select id from functional.alltypes where (int_col + float_col) * 10", "WHERE clause requires return type 'BOOLEAN'. Actual type is 'DOUBLE'.");
}

