/**
 * Test ROLLUP, CUBE and GROUPING SETS functionality.
 */
@Test
public void TestGroupingSets() throws AnalysisException {
    // Basic examples of each clause.
    AnalyzesOk("select count(*) from functional.alltypes " + "group by rollup(int_col, string_col)");
    AnalyzesOk("select count(*) from functional.alltypes " + "group by int_col, string_col with rollup");
    AnalyzesOk("select count(*) from functional.alltypes " + "group by int_col, string_col with cube");
    AnalyzesOk("select count(*) from functional.alltypes " + "group by GROUPING SETS((int_col), (string_col))");
    // Test limits for number of distinct expressions
    StringBuilder sb = new StringBuilder();
    for (int i = 1; i <= 25; ++i) {
        sb.append("bool_col" + i + ", tinyint_col" + i + ", smallint_col" + i + ", int_col" + i + ", bigint_col" + i + ", float_col" + i + ", double_col" + i + ", string_col" + i);
        if (i != 25) {
            sb.append(",");
        }
    }
    String longColList = sb.toString();
    AnalysisError("select count(*) from functional.widetable_250_cols " + "group by rollup(" + longColList + ")", "Number of grouping columns (200) exceeds GROUP BY with ROLLUP limit of 63");
    AnalysisError("select count(*) from functional.widetable_250_cols " + "group by cube(" + longColList + ")", "Number of grouping columns (200) exceeds GROUP BY with CUBE limit of 63");
    AnalysisError("select count(*) from functional.widetable_250_cols " + "group by grouping sets((" + longColList + "))", "Number of grouping columns (200) exceeds GROUP BY with SETS limit of 63");
    // Duplicating the same column shouldn't increase distinct column count.
    AnalysisError("select count(*) from functional.widetable_250_cols " + "group by grouping sets((" + longColList + ", string_col1), " + "(bool_col1, int_col1))", "Number of grouping columns (200) exceeds GROUP BY with SETS limit of 63");
    // Grouping sets with overlapping expression lists doesn't hit limit, since exprs are
    // deduplicated.
    AnalyzesOk("select count(*) from functional.widetable_250_cols " + "group by grouping sets(( " + "  bool_col1, tinyint_col1, smallint_col1, int_col1, bigint_col1, " + "  float_col1, double_col1, string_col1, " + "  bool_col2, tinyint_col2, smallint_col2, int_col2, bigint_col2, " + "  float_col2, double_col2, string_col2, " + "  bool_col3, tinyint_col3, smallint_col3, int_col3, bigint_col3, " + "  float_col3, double_col3, string_col3, " + "  bool_col4, tinyint_col4, smallint_col4, int_col4, bigint_col4, " + "  float_col4, double_col4, string_col4, " + "  bool_col5, tinyint_col5, smallint_col5, int_col5, bigint_col5, " + "  float_col5, double_col5, string_col5, " + "  bool_col6, tinyint_col6, smallint_col6, int_col6, bigint_col6, " + "  float_col6, double_col6, string_col6, " + "  bool_col7, tinyint_col7, smallint_col7, int_col7, bigint_col7, " + "  float_col7, double_col7, string_col7), " + "  (bool_col1, tinyint_col1, smallint_col1, int_col1, bigint_col1, " + "  float_col1, double_col1, string_col1, " + "  bool_col2, tinyint_col2, smallint_col2, int_col2, bigint_col2, " + "  float_col2, double_col2, string_col2)); ");
    // Test limit of number of distinct grouping sets - 63. CUBE with 6 grouping exprs
    // results in 2^6 = 64 distinct grouping sets. CUBE with 5 grouping exprs and ROLLUP
    // with 6 grouping exprs are both under the limit.
    AnalyzesOk("select id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col, count(*) " + "from functional.alltypes " + "group by rollup(id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col)");
    AnalyzesOk("select id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "count(*) " + "from functional.alltypes " + "group by cube(id, bool_col, tinyint_col, smallint_col, int_col, bigint_col)");
    AnalysisError("select id, bool_col, tinyint_col, smallint_col, int_col, " + "bigint_col, float_col, count(*) " + "from functional.alltypes " + "group by cube(id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col)", "Limit of 64 grouping sets exceeded");
    // Basic test cases where grouping exprs are subset and superset of select list.
    AnalyzesOk("select int_col, count(*) from functional.alltypes " + "group by rollup(int_col, string_col)");
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by rollup(int_col, string_col)");
    AnalysisError("select int_col, bool_col, string_col, count(*) " + "from functional.alltypes " + "group by rollup(int_col, string_col)", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?): bool_col");
    AnalyzesOk("select int_col, count(*) from functional.alltypes " + "group by cube(int_col, string_col)");
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by cube(int_col, string_col)");
    AnalysisError("select int_col, bool_col, string_col, count(*) " + "from functional.alltypes " + "group by cube(int_col, string_col)", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?): bool_col");
    AnalyzesOk("select int_col, count(*) from functional.alltypes " + "group by grouping sets((int_col, string_col), (int_col))");
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by grouping sets((int_col, string_col), (int_col))");
    AnalysisError("select int_col, bool_col, string_col, count(*) " + "from functional.alltypes " + "group by grouping sets((int_col, string_col), (int_col))", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?): bool_col");
    // Support for ordinals.
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by rollup(1, 2)");
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by cube(1, 2)");
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by grouping sets((1, 2), (1))");
    AnalysisError("select int_col, string_col, count(*) from functional.alltypes " + "group by rollup(1, 3)", "GROUP BY expression must not contain aggregate functions: 3");
    AnalysisError("select int_col, string_col, count(*) from functional.alltypes " + "group by cube(1, 3)", "GROUP BY expression must not contain aggregate functions: 3");
    AnalysisError("select int_col, string_col, count(*) from functional.alltypes " + "group by grouping sets((1, 3), (1))", "GROUP BY expression must not contain aggregate functions: 3");
    // Refer to same column by name and ordinal in grouping sets.
    AnalyzesOk("select int_col, string_col, count(*) from functional.alltypes " + "group by grouping sets((1, 2), (int_col))");
    // Group by non-trivial expressions not in select list
    AnalyzesOk("select count(*) from functional.alltypes " + "group by rollup(int_col, substring(string_col, 1, 2))");
    AnalyzesOk("select int_col, count(*) from functional.alltypes " + "group by cube(int_col, substring(string_col, 1, 2))");
    AnalyzesOk("select int_col, count(*) from functional.alltypes " + "group by grouping sets((int_col), (int_col, substring(string_col, 1, 2)))");
    // Group by non-trivial expressions in select list
    AnalyzesOk("select int_col, substring(string_col, 1, 2) str, count(*) " + "from functional.alltypes " + "group by rollup(int_col, substring(string_col, 1, 2))");
    AnalyzesOk("select int_col, substring(string_col, 1, 2) str, count(*) " + "from functional.alltypes " + "group by cube(int_col, str)");
    AnalyzesOk("select int_col, substring(string_col, 1, 2) str, count(*) " + "from functional.alltypes " + "group by grouping sets((int_col, str), (substring(string_col, 1, 2)))");
    // Expressions in select list must appear in group by.
    AnalysisError("select int_col, substring(string_col, 1, 3) str, count(*) " + "from functional.alltypes " + "group by rollup(int_col, substring(string_col, 1, 2))", "select list expression not produced by aggregation output (missing from " + "GROUP BY clause?): substring(string_col, 1, 3)");
    // Use the expression and an alias.
    AnalyzesOk("select int_col, substring(string_col, 1, 2) str, count(*) " + "from functional.alltypes " + "group by rollup(int_col, str, substring(string_col, 1, 2))");
    // Group by constant expression.
    AnalyzesOk("select int_col, count(*) " + "from functional.alltypes " + "group by rollup(int_col, 'constant')");
    AnalyzesOk("select int_col, count(*) " + "from functional.alltypes " + "group by cube(int_col, 'constant')");
    AnalyzesOk("select int_col, count(*) " + "from functional.alltypes " + "group by grouping sets((false), (int_col, 'constant'))");
    // Subqueries with grouping sets inside and outside subquery.
    AnalyzesOk("select g.int_col, count(*) " + "from functional.alltypesagg g " + "left outer join functional.alltypes a on g.id = a.id " + "where g.int_col < 100 and g.tinyint_col < ( " + "  select count(*) from functional.alltypes t " + "  where t.id = g.id and g.string_col = t.string_col and t.bool_col = true) " + "group by rollup(g.int_col, g.string_col) " + "having count(*) < 100");
    AnalysisError("select g.int_col, count(*) " + "from functional.alltypesagg g " + "where g.int_col < 100 and g.tinyint_col < ( " + "  select count(*) from functional.alltypes t " + "  where t.id = g.id and g.string_col = t.string_col and t.bool_col = true " + "  group by rollup(t.string_col, t.bool_col)) " + "  group by g.int_col", "Unsupported correlated subquery with grouping and/or aggregation");
    // Combining grouping sets and distinct aggregations is not supported at this point.
    // See IMPALA-9914.
    AnalysisError("select count(distinct id) from functional.alltypes " + "group by rollup(int_col, bool_col)", "Distinct aggregate functions and grouping sets are not supported in the same " + "query block.");
    AnalysisError("select count(distinct id), count(distinct string_col) " + "from functional.alltypes " + "group by rollup(int_col, bool_col)", "Distinct aggregate functions and grouping sets are not supported in the same " + "query block.");
    // Combining DISTINCT and GROUP BY is not supported in general, not just for grouping
    // sets.
    AnalysisError("select distinct int_col, bool_col, count(*) " + "from functional.alltypes " + "group by rollup(int_col, bool_col)", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    // grouping_id() and grouping() are aggregate functions that can be used in any
    // GROUP BY, even though they are only meaningful in conjunction with
    // CUBE/ROLLUP/GROUPING SETS. grouping() must reference exactly one of the grouping
    // columns.
    AnalyzesOk("select int_col, string_col, grouping_id(), grouping(int_col), " + "grouping(string_col) " + "from functional.alltypes " + "group by rollup(int_col, string_col)");
    AnalyzesOk("select int_col, string_col, grouping_id(), grouping(int_col), " + "grouping(string_col) " + "from functional.alltypes " + "group by cube(int_col, string_col)");
    AnalyzesOk("select int_col, string_col, grouping_id(), grouping(int_col), " + "grouping(string_col) " + "from functional.alltypes " + "group by grouping sets((), (int_col, string_col))");
    // grouping_id() can reference a variable number of grouping columns.
    AnalyzesOk("select int_col, string_col, grouping_id(int_col, string_col), " + "grouping(string_col) " + "from functional.alltypes " + "group by rollup(int_col, string_col)");
    // Non-trivial expressions involving grouping_id().
    AnalyzesOk("select bitand(grouping_id(), 1), cast(grouping(int_col) as string) " + "from functional.alltypes " + "group by rollup(int_col, string_col)");
    // grouping() can reference non-trivial grouping expressions
    AnalyzesOk("select int_col * 2, string_col, grouping(int_col * 2),  count(*) " + "from functional.alltypes " + "group by rollup(1, 2)");
    // grouping_id() and grouping() can be used in conjunction with a plain GROUP BY.
    AnalyzesOk("select int_col, string_col, grouping_id() " + "from functional.alltypes " + "group by int_col, string_col");
    AnalyzesOk("select int_col, string_col, grouping(int_col) " + "from functional.alltypes " + "group by int_col, string_col");
    // grouping() and grouping_id() can be used in the degenerate case of a single
    // grouping set.
    AnalyzesOk("select int_col, string_col, grouping_id(), grouping(int_col) " + "from functional.alltypes " + "group by grouping sets((int_col, string_col))");
    // grouping() raises analysis error if given wrong number of args.
    AnalysisError("select int_col, string_col, grouping(int_col, string_col) " + "from functional.alltypes " + "group by grouping sets((), (int_col, string_col))", "No matching function with signature: grouping(INT, STRING).");
    AnalysisError("select int_col, string_col, grouping() " + "from functional.alltypes " + "group by grouping sets((), (int_col, string_col))", "No matching function with signature: grouping().");
    // grouping() and grouping_id() must reference grouping expressions.
    AnalysisError("select int_col, grouping('test') from functional.alltypes " + "group by rollup(int_col, string_col)", "'test' is not a grouping expression");
    AnalysisError("select int_col, grouping(1) from functional.alltypes " + "group by rollup(int_col, string_col)", "1 is not a grouping expression");
    AnalysisError("select grouping(tinyint_col) from functional.alltypes " + "group by rollup(int_col, string_col)", "tinyint_col is not a grouping expression");
    AnalysisError("select count(*), grouping(count(*)) from functional.alltypes " + "group by rollup(int_col, string_col)", "aggregate function must not contain aggregate parameters: grouping(count(*))");
    AnalysisError("select int_col, grouping_id(int_col, 'test') " + "from functional.alltypes " + "group by rollup(int_col, string_col)", "'test' is not a grouping expression");
    AnalysisError("select int_col, grouping_id(1) from functional.alltypes " + "group by rollup(int_col, string_col)", "1 is not a grouping expression");
    AnalysisError("select grouping_id(int_col, tinyint_col) from functional.alltypes " + "group by rollup(int_col, string_col)", "tinyint_col is not a grouping expression");
    AnalysisError("select count(*), grouping_id(count(*)) from functional.alltypes " + "group by rollup(int_col, string_col)", "count(*) is not a grouping expression");
    // grouping() and grouping_id() require GROUP BY clause.
    AnalysisError("select int_col, grouping(int_col) from functional.alltypes", "grouping() or grouping_id() function requires a GROUP BY clause: '" + "grouping(int_col)'");
    AnalysisError("select int_col, grouping_id() from functional.alltypes", "grouping() or grouping_id() function requires a GROUP BY clause: '" + "grouping_id()'");
}

@Test
public void TestDistinct() throws AnalysisException {
    AnalyzesOk("select count(distinct id) as sum_id from functional.testtbl");
    AnalyzesOk("select count(distinct id) as sum_id from " + "functional.testtbl order by sum_id");
    AnalyzesOk("select count(distinct id) as sum_id from " + "functional.testtbl order by max(id)");
    AnalyzesOk("select distinct id, zip from functional.testtbl");
    AnalyzesOk("select distinct * from functional.testtbl");
    AnalysisError("select distinct count(*) from functional.testtbl", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip from functional.testtbl group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip, count(*) from " + "functional.testtbl group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalyzesOk("select distinct id from functional.testtbl having id > 0");
    AnalysisError("select distinct id from functional.testtbl having max(id) > 0", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalyzesOk("select count(distinct id, zip) from functional.testtbl");
    AnalyzesOk("select tinyint_col, count(distinct int_col, bigint_col) " + "from functional.alltypesagg group by 1");
    AnalyzesOk("select tinyint_col, count(distinct int_col)," + "sum(distinct int_col) from functional.alltypesagg group by 1");
    AnalyzesOk("select avg(DISTINCT(tinyint_col)) from functional.alltypesagg");
    // SUM(DISTINCT) and AVG(DISTINCT) with duplicate grouping exprs (IMPALA-847).
    AnalyzesOk("select sum(distinct t1.bigint_col), avg(distinct t1.bigint_col) " + "from functional.alltypes t1 group by t1.int_col, t1.int_col");
    // min and max are ignored in terms of DISTINCT
    AnalyzesOk("select tinyint_col, count(distinct int_col)," + "min(distinct smallint_col), max(distinct string_col) " + "from functional.alltypesagg group by 1");
    // Test multiple distinct aggregations.
    Table alltypesTbl = catalog_.getOrLoadTable("functional", "alltypes");
    List<String> distinctFns = new ArrayList<>();
    for (Column col : alltypesTbl.getColumns()) {
        distinctFns.add(String.format("count(distinct %s)", col.getName()));
    }
    // Test a single query with a count(distinct) on all columns of alltypesTbl.
    AnalyzesOk(String.format("select %s from functional.alltypes", Joiner.on(",").join(distinctFns)));
    // Test various mixes of distinct and non-distinct, including multiple distinct.
    Set<String> testAggExprs = Sets.newHashSet("count(tinyint_col)", "count(string_col)", "avg(float_col)", "max(string_col)", "count(distinct tinyint_col)", "count(distinct tinyint_col, smallint_col, int_col)", "avg(distinct double_col)", "count(distinct string_col)", "sum(distinct smallint_col)");
    List<String> testGroupByExprs = Lists.newArrayList("int_col", "bigint_col", "string_col", "string_col, date_string_col", "id, double_col, date_string_col");
    for (Set<String> aggExprs : Sets.powerSet(testAggExprs)) {
        if (aggExprs.isEmpty())
            continue;
        String selectList = Joiner.on(",").join(aggExprs);
        AnalyzesOk(String.format("select %s from functional.alltypes", selectList));
        for (String groupByExprs : testGroupByExprs) {
            AnalyzesOk(String.format("select %s from functional.alltypes group by %s", selectList, groupByExprs));
        }
    }
    // IMPALA-6114: Test that numeric literals having the same value, but different types are
    // considered distinct.
    AnalyzesOk("select distinct cast(0 as decimal(14)), 0 from functional.alltypes");
}

@Test
public void TestSampledNdv() throws AnalysisException {
    Table allScalarTypes = addAllScalarTypesTestTable();
    String tblName = allScalarTypes.getFullName();
    // Positive tests: Test all scalar types and valid sampling percents.
    double[] validSamplePercs = new double[] { 0.0, 0.1, 0.2, 0.5, 0.8, 1.0 };
    for (double perc : validSamplePercs) {
        List<String> allAggFnCalls = new ArrayList<>();
        for (Column col : allScalarTypes.getColumns()) {
            String aggFnCall = String.format("sampled_ndv(%s, %s)", col.getName(), perc);
            allAggFnCalls.add(aggFnCall);
            String stmtSql = String.format("select %s from %s", aggFnCall, tblName);
            SelectStmt stmt = (SelectStmt) AnalyzesOk(stmtSql);
            // Verify that the resolved function signature matches as expected.
            AggregateInfo aggInfo = stmt.getMultiAggInfo().getAggClass(0);
            Type[] args = aggInfo.getAggregateExprs().get(0).getFn().getArgs();
            assertEquals(args.length, 2);
            assertTrue(col.getType().matchesType(args[0]) || col.getType().isStringType() && args[0].equals(Type.STRING));
            assertEquals(Type.DOUBLE, args[1]);
        }
        // Test several calls in the same query block.
        AnalyzesOk(String.format("select %s from %s", Joiner.on(",").join(allAggFnCalls), tblName));
    }
    // Negative tests: Incorrect number of args.
    AnalysisError(String.format("select sampled_ndv() from %s", tblName), "No matching function with signature: sampled_ndv().");
    AnalysisError(String.format("select sampled_ndv(int_col) from %s", tblName), "No matching function with signature: sampled_ndv(INT).");
    AnalysisError(String.format("select sampled_ndv(int_col, 0.1, 10) from %s", tblName), "No matching function with signature: sampled_ndv(INT, DECIMAL(1,1), TINYINT).");
    // Negative tests: Invalid sampling percent.
    String[] invalidSamplePercs = new String[] { "int_col", "double_col", "100 / 10", "-0.1", "1.1", "100", "50", "-50", "NULL" };
    for (String invalidPerc : invalidSamplePercs) {
        AnalysisError(String.format("select sampled_ndv(int_col, %s) from %s", invalidPerc, tblName), "Second parameter of SAMPLED_NDV() must be a numeric literal in [0,1]: " + invalidPerc);
    }
}

@Test
public void TestGroupConcat() throws AnalysisException {
    // Test valid and invalid parameters
    AnalyzesOk("select group_concat(distinct name) from functional.testtbl");
    AnalysisError("select group_concat(distinct name, name) from functional.testtbl", "Second parameter in GROUP_CONCAT(DISTINCT) must be a constant expression" + " that returns a string.");
    AnalyzesOk("select group_concat(distinct name, cast(123 as string)) " + "from functional.testtbl");
    AnalysisError("select group_concat(distinct name, cast(id as string)) " + "from functional.testtbl", "Second parameter in GROUP_CONCAT(DISTINCT) must be a constant expression" + " that returns a string.");
    AnalyzesOk("select group_concat(distinct string_col, concat('-', '?')) " + "from functional.alltypesagg");
    AnalysisError("select group_concat(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    // test group_concat using a column as the custom separator
    AnalyzesOk("select group_concat(string_col, string_col) from functional.alltypes");
    // test group_concat without and with distinct
    String[] keywords = new String[] { "distinct", "" };
    for (String keyword : keywords) {
        AnalysisError(String.format("select group_concat(%s '')", keyword), "aggregation" + " without a FROM clause is not allowed");
        AnalysisError(String.format("select group_concat(%s name, '-', ',') " + "from functional.testtbl", keyword), "No matching function with signature: " + "group_concat(STRING, STRING, STRING)");
        // test all types as arguments
        for (Type type : typeToLiteralValue_.keySet()) {
            String literal = typeToLiteralValue_.get(type);
            String query1 = String.format("select group_concat(%s %s) from functional.alltypes", keyword, literal);
            String query2 = String.format("select group_concat(%s %s, '---') from functional.alltypes", keyword, literal);
            if (type.getPrimitiveType() == PrimitiveType.STRING || type.isNull()) {
                AnalyzesOk(query1);
                AnalyzesOk(query2);
            } else {
                AnalysisError(query1, "No matching function with signature: group_concat(");
                AnalysisError(query2, "No matching function with signature: group_concat(");
            }
        }
    }
}

