    AnalysisError("select * from " + "(select distinct id, zip from functional.testtbl group by 1, 2) x", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select * from " + "(select distinct id, zip, count(*) from functional.testtbl group by 1, 2) x", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
