@Test
public void testIcebergTimeTravel() throws ImpalaException {
    TableName iceT = new TableName("functional_parquet", "iceberg_non_partitioned");
    TableName nonIceT = new TableName("functional", "allcomplextypes");
    TblsAnalyzeOk("select * from $TBL for system_time as of now()", iceT);
    TblsAnalyzeOk("select * from $TBL for system_time as of '2021-08-09 15:52:45'", iceT);
    TblsAnalyzeOk("select * from $TBL for system_time as of " + "cast('2021-08-09 15:52:45' as timestamp) - interval 2 days + interval 3 hours", iceT);
    TblsAnalyzeOk("select * from $TBL for system_time as of now() + interval 3 days", iceT);
    // Use a legal snapshot id '93996984692289973' from the testdata.
    TblsAnalyzeOk("select * from $TBL for system_version as of 93996984692289973", iceT);
    TblsAnalysisError("select * from $TBL for system_time as of 42", iceT, "FOR SYSTEM_TIME AS OF <expression> must be a timestamp type");
    TblsAnalysisError("select * from $TBL for system_time as of id", iceT, "FOR SYSTEM_TIME AS OF <expression> must be a constant expression");
    TblsAnalysisError("select * from $TBL for system_time as of '2021-02-32 15:52:45'", iceT, "Invalid TIMESTAMP expression");
    TblsAnalysisError("select * from $TBL for system_version as of 3.14", iceT, "FOR SYSTEM_VERSION AS OF <expression> must be an integer type but is");
    TblsAnalysisError("select * from $TBL for system_time as of now()", nonIceT, "FOR SYSTEM_TIME AS OF clause is only supported for Iceberg tables.");
    TblsAnalysisError("select * from $TBL for system_version as of 123", nonIceT, "FOR SYSTEM_VERSION AS OF clause is only supported for Iceberg tables.");
}

@Test
public void testIcebergDescribeHistory() throws ImpalaException {
    TableName iceT = new TableName("functional_parquet", "iceberg_non_partitioned");
    TableName nonIceT = new TableName("functional", "allcomplextypes");
    // Analyze without predicate.
    TblsAnalyzeOk("DESCRIBE HISTORY $TBL", iceT);
    // Analyze with predicates.
    TblsAnalyzeOk("DESCRIBE HISTORY $TBL FROM \"2022-02-14 13:31:09.819\"", iceT);
    TblsAnalyzeOk("DESCRIBE HISTORY $TBL FROM " + "cast('2021-08-09 15:52:45' as timestamp) - interval 2 days + interval 3 days", iceT);
    TblsAnalyzeOk("DESCRIBE HISTORY $TBL FROM now() + interval 3 days", iceT);
    TblsAnalyzeOk("DESCRIBE HISTORY $TBL BETWEEN '2021-02-22' AND '2021-02-22'", iceT);
    // Analyze should fail with unsupported expression types.
    TblsAnalysisError("DESCRIBE HISTORY $TBL FROM 42 ", iceT, "FROM <expression> must be a timestamp type");
    TblsAnalysisError("DESCRIBE HISTORY $TBL FROM id", iceT, "Unsupported expression: 'id'");
    TblsAnalysisError("DESCRIBE HISTORY $TBL FROM '2021-02-32 15:52:45'", iceT, "Invalid TIMESTAMP expression");
    // DESCRIBE HISTORY is only supported for Iceberg tables.
    TblsAnalysisError("DESCRIBE HISTORY $TBL", nonIceT, "DESCRIBE HISTORY must specify an Iceberg table:");
}

