@Test
public void TestInSubqueries() throws AnalysisException {
    String[] colNames = { "bool_col", "tinyint_col", "smallint_col", "int_col", "bigint_col", "float_col", "double_col", "string_col", "date_string_col", "timestamp_col" };
    String[] joinOperators = { "inner join", "left outer join", "right outer join", "left semi join", "left anti join" };
    // [NOT] IN subquery predicates
    String[] operators = { "IN", "NOT IN" };
    for (String op : operators) {
        AnalyzesOk(String.format("select * from functional.alltypes where id %s " + "(select id from functional.alltypestiny)", op));
        // Using column and table aliases similar to the ones produced by the
        // column/table alias generators during a rewrite.
        AnalyzesOk(String.format("select id `$c$1` from functional.alltypestiny `$a$1` " + "where id %s (select id from functional.alltypessmall)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select id from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a)", op));
        AnalyzesOk(String.format("select count(*) from functional.alltypes t where " + "t.id %s (select id from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select t.id, max(t.int_col) from " + "functional.alltypes t where t.int_col %s (select int_col from " + "functional.alltypesagg) group by t.id having count(*) < 10", op));
        AnalyzesOk(String.format("select t.bigint_col, t.string_col from " + "functional.alltypes t where t.id %s (select id from " + "functional.alltypesagg where int_col < 10) order by bigint_col", op));
        AnalyzesOk(String.format("select * from functional.alltypes a where a.id %s " + "(select id from functional.alltypes b where a.id = b.id)", op));
        // Complex expressions
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select id + int_col from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select 1 from functional.alltypes t where " + "t.int_col + 1 %s (select int_col - 1 from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where " + "abs(t.double_col) %s (select int_col from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select NULL from functional.alltypes t where " + "cast(t.double_col as int) %s (select int_col from " + "functional.alltypestiny)", op));
        AnalyzesOk(String.format("select count(*) from functional.alltypes where id %s " + "(select 1 from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select * from functional.alltypes where id %s " + "(select 1 + 1 from functional.alltypestiny group by int_col)", op));
        AnalyzesOk(String.format("select max(id) from functional.alltypes where id %s " + "(select max(id) from functional.alltypesagg a where a.int_col < 10) " + "and bool_col = false", op));
        // Subquery returns multiple columns
        AnalysisError(String.format("select * from functional.alltypestiny t where id %s " + "(select id, int_col from functional.alltypessmall)", op), "Subquery must return a single column: (SELECT id, int_col " + "FROM functional.alltypessmall)");
        // Subquery returns an incompatible column type
        AnalysisError(String.format("select * from functional.alltypestiny t where id %s " + "(select timestamp_col from functional.alltypessmall)", op), "Incompatible return types 'INT' and 'TIMESTAMP' of exprs 'id' and " + "'timestamp_col'.");
        // Different column types in the subquery predicate
        for (String col : colNames) {
            AnalyzesOk(String.format("select * from functional.alltypes t where t.%s %s " + "(select a.%s from functional.alltypestiny a)", col, op, col));
        }
        // Decimal in the subquery predicate
        AnalyzesOk(String.format("select * from functional.alltypes t where " + "t.double_col %s (select d3 from functional.decimal_tbl a)", op));
        // Varchar in the subquery predicate
        AnalyzesOk(String.format("select * from functional.alltypes t where " + "t.string_col %s (select cast(a.string_col as varchar(1)) from " + "functional.alltypestiny a)", op));
        // Date in the subquery predicate
        AnalyzesOk(String.format("select * from functional.alltypes where " + "timestamp_col %s (select date_col from functional.date_tbl)", op));
        // Timestamp in the subquery predicate
        AnalyzesOk(String.format("select * from functional.date_tbl where " + "date_col %s (select timestamp_col from functional.alltypes)", op));
        // Binary in the subquery predicate
        AnalyzesOk(String.format("select * from functional.binary_tbl where " + "binary_col %s (select cast(string_col as binary) " + "from functional.alltypes)", op));
        // Subqueries with multiple predicates in the WHERE clause
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a where a.int_col < 10)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a where a.int_col > 10 and " + "a.tinyint_col < 5)", op));
        // Subqueries with a GROUP BY clause
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a where a.double_col < 10.1 " + "group by a.id)", op));
        // Subqueries with GROUP BY and HAVING clauses
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a where a.bool_col = true and " + "int_col < 10 group by id having count(*) < 10)", op));
        // Subqueries with a LIMIT clause
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a where id < 100 limit 10)", op));
        // Subqueries with multiple tables in the FROM clause
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a, functional.alltypessmall s " + "where a.int_col = s.int_col and s.bigint_col < 100 and a.tinyint_col < 10)", op));
        // Different join operators between the tables in subquery's FROM clause
        for (String joinOp : joinOperators) {
            AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a %s functional.alltypessmall " + "s on a.int_col = s.int_col where a.bool_col = false)", op, joinOp));
        }
        // Complex type: subquery with relative table references
        AnalyzesOk(String.format("select id from functional.allcomplextypes t where id %s " + "(select f1 from t.struct_array_col a, t.int_array_col b " + "where f2 = 'xyz' and b.item < 3 group by f1 having count(*) > 2 limit 5)", op));
        // Correlated predicates in the subquery's ON clause. Vary join column type.
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypesagg a left outer join " + "functional.alltypessmall s on s.int_col = t.int_col)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypesagg a left outer join " + "functional.alltypessmall s on s.bigint_col = a.bigint_col and " + "s.int_col = t.int_col)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypesagg a left outer join " + "functional.alltypessmall s on a.bool_col = s.bool_col and t.int_col = 1)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypesagg a left outer join " + "functional.alltypessmall s on ifnull(s.int_col, s.int_col + 20) = " + "t.int_col + t.bigint_col)", op));
        // Subqueries with inline views
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypestiny a, " + "(select * from functional.alltypessmall) s where s.int_col = a.int_col " + "and s.bool_col = false)", op));
        // Subqueries with inline views that contain subqueries
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from (select id from functional.alltypesagg g where " + "g.int_col in (select int_col from functional.alltypestiny)) a)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from (select g.* from functional.alltypesagg g where " + "g.int_col in (select int_col from functional.alltypestiny)) a where " + "a.bigint_col = 100)", op));
        // Multiple tables in the FROM clause of the outer query block
        for (String joinOp : joinOperators) {
            AnalyzesOk(String.format("select * from functional.alltypes t %s " + "functional.alltypessmall s on t.int_col = s.int_col where " + "t.tinyint_col %s (select tinyint_col from functional.alltypesagg) " + "and t.bool_col = false and t.bigint_col = 10", joinOp, op));
        }
        // Subqueries in WITH clause
        AnalyzesOk(String.format("with t as (select a.* from functional.alltypes a where " + "id %s (select id from functional.alltypestiny)) select * from t where " + "t.bool_col = false and t.int_col = 10", op));
        // Subqueries in WITH and WHERE clauses
        AnalyzesOk(String.format("with t as (select a.* from functional.alltypes a " + "where id %s (select id from functional.alltypestiny s)) select * from t " + "where t.int_col in (select int_col from functional.alltypessmall) and " + "t.bool_col = false", op));
        // Subqueries in WITH, FROM and WHERE clauses
        AnalyzesOk(String.format("with t as (select a.* from functional.alltypes a " + "where id %s (select id from functional.alltypestiny)) select t.* from t, " + "(select * from functional.alltypesagg g where g.id in " + "(select id from functional.alltypes)) s where s.string_col = t.string_col " + "and t.int_col in (select int_col from functional.alltypessmall) and " + "s.bool_col = false", op));
        // Correlated subqueries
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.int_col = a.int_col) " + "and t.bool_col = false", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.int_col + 1 = a.int_col)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.int_col + 1 = a.int_col + 1)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.int_col + a.int_col  = " + "a.bigint_col and a.bool_col = true)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.bool_col = false and " + "a.int_col < 10)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.bool_col)", op));
        AnalyzesOk(String.format("select id from functional.allcomplextypes t where id %s " + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 = a.f1)", op));
        // Test correlated BETWEEN predicates.
        AnalyzesOk(String.format("select 1 from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where " + " a.tinyint_col between t.tinyint_col and t.smallint_col and " + " a.smallint_col between 10 and t.int_col and " + " 20 between t.bigint_col and a.int_col and " + " t.float_col between a.float_col and a.double_col and " + " t.string_col between a.string_col and t.date_string_col and " + " a.double_col between round(acos(t.float_col), 2) " + " and cast(t.string_col as int))", op));
        // Multiple nesting levels (uncorrelated queries)
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg where int_col %s " + "(select int_col from functional.alltypestiny) and bool_col = false) " + "and bigint_col < 1000", op, op));
        // Multiple nesting levels (correlated queries)
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where a.int_col = t.int_col " + "and a.tinyint_col %s (select tinyint_col from functional.alltypestiny s " + "where s.bigint_col = a.bigint_col))", op, op));
        // Multiple nesting levels (correlated and uncorrelated queries)
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where t.int_col = a.int_col " + "and a.int_col %s (select int_col from functional.alltypestiny s))", op, op));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes t1 where id %s " + "(select f11 from t1.complex_nested_struct_col.f2 t2 " + "where t1.year = f11 and f11 %s " + "(select value.f21 from t2.f12 where key = 'test'))", op, op));
        // NOT ([NOT] IN predicate)
        AnalyzesOk(String.format("select * from functional.alltypes t where not (id %s " + "(select id from functional.alltypesagg))", op));
        // Different cmp operators in the correlation predicate
        for (String cmpOp : cmpOperators) {
            AnalyzesOk(String.format("select * from functional.alltypes t " + "where t.id %s (select a.id from functional.alltypesagg a where " + "t.int_col %s a.int_col)", op, cmpOp));
        }
        // Uncorrelated IN subquery with analytic function
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col %s (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 where " + "int_col < 10)", op));
        // [NOT] IN subquery with a correlated non-equi predicate is ok if the subquery only
        // has relative table refs
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes t where id %s " + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 < a.f1)", op));
        // Statement with a GROUP BY and a correlated IN subquery that has a non-equi
        // correlated predicate and only relative table refs
        AnalyzesOk(String.format("select id, count(*) from functional.allcomplextypes t " + "where id %s" + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 < a.f1) " + "group by id", op));
        // Complex type: Correlated, non-equijoins.
        for (String cmpOp : nonEquiCmpOperators) {
            // Complex type: allowed because the subquery only has relative table refs.
            AnalyzesOk(String.format("select 1 from functional.allcomplextypes t " + "where id %s " + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 %s a.f1)", op, cmpOp));
        }
        // Reference a non-existing table in the subquery
        AnalysisError(String.format("select * from functional.alltypestiny t where id %s " + "(select id from functional.alltypessmall s left outer join p on " + "(s.int_col = p.int_col))", op), "Could not resolve table reference: 'p'");
        // Reference a non-existing column from a table in the outer scope
        AnalysisError(String.format("select * from functional.alltypestiny t where id %s " + "(select id from functional.alltypessmall s where s.int_col = t.bad_col)", op), "Could not resolve column/field reference: 't.bad_col'");
        // Referencing the same table in the inner and the outer query block
        // No explicit alias
        AnalyzesOk(String.format("select id from functional.alltypestiny where " + "int_col %s (select int_col from functional.alltypestiny)", op));
        // Different alias between inner and outer block referencing the same table
        AnalyzesOk(String.format("select id from functional.alltypestiny t where " + "int_col %s (select int_col from functional.alltypestiny p)", op));
        // Alias only in the outer block
        AnalyzesOk(String.format("select id from functional.alltypestiny t where " + "int_col %s (select int_col from functional.alltypestiny)", op));
        // Same alias in both inner and outer block
        AnalyzesOk(String.format("select id from functional.alltypestiny t where " + "int_col %s (select int_col from functional.alltypestiny t)", op));
        // OR with subquery predicates. Only a single subquery is supported.
        AnalysisError(String.format("select * from functional.alltypes t where t.id %s " + "(select id from functional.alltypesagg) or t.int_col %s " + "(select int_col from functional.alltypesagg)", op, op), String.format("Multiple subqueries are not supported in expression: t.id %s " + "(SELECT id FROM functional.alltypesagg) OR t.int_col %s " + "(SELECT int_col FROM functional.alltypesagg)", op, op));
        // Binary predicate with non-comparable operands
        AnalysisError(String.format("select * from functional.alltypes t where " + "(id %s (select id from functional.alltypestiny)) = 'string_val'", op), String.format("operands of type BOOLEAN and STRING are not comparable: " + "(id %s (SELECT id FROM functional.alltypestiny)) = 'string_val'", op));
        // TODO: Modify the StmtRewriter to allow this case with relative refs.
        // Correlated subquery with relative table refs and OR predicate is not allowed
        AnalysisError(String.format("select id from functional.allcomplextypes t where " + "id %s (select f1 from t.struct_array_col a where t.int_struct_col.f1 < a.f1 " + "or id < 10)", op), "Disjunctions with correlated predicates are not supported: " + "t.int_struct_col.f1 < a.f1 OR id < 10");
        // Correlated subquery with absolute table refs and OR predicate is not allowed
        AnalysisError(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypesagg a where " + "a.int_col = t.int_col or a.bool_col = false)", op), "Disjunctions " + "with correlated predicates are not supported: a.int_col = " + "t.int_col OR a.bool_col = FALSE");
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypestiny) and (bool_col = false or " + "int_col = 10)", op));
        // Correlated subqueries with GROUP BY, AGG functions or DISTINCT are not allowed
        // with relative table refs in the subquery
        // TODO: Modify the StmtRewriter to allow this case with relative refs
        AnalysisError(String.format("select id from functional.allcomplextypes t where " + "id %s" + "(select count(f1) from t.struct_array_col a where t.int_struct_col.f1 < a.f1)", op), "Unsupported correlated subquery with grouping and/or aggregation: " + "SELECT count(f1) FROM t.struct_array_col a WHERE t.int_struct_col.f1 < a.f1");
        // Correlated subqueries with GROUP BY, AGG functions or DISTINCT are not allowed
        // with absolute table refs in the subquery
        AnalysisError(String.format("select * from functional.alltypes t where t.id %s " + "(select max(a.id) from functional.alltypesagg a where " + "t.int_col = a.int_col)", op), "Unsupported correlated subquery with grouping and/or aggregation: " + "SELECT max(a.id) FROM functional.alltypesagg a " + "WHERE t.int_col = a.int_col");
        AnalysisError(String.format("select * from functional.alltypes t where t.id %s " + "(select a.id from functional.alltypesagg a where " + "t.int_col = a.int_col group by a.id)", op), "Unsupported correlated " + "subquery with grouping and/or aggregation: SELECT a.id FROM " + "functional.alltypesagg a WHERE t.int_col = a.int_col GROUP BY a.id");
        AnalysisError(String.format("select * from functional.alltypes t where t.id %s " + "(select distinct a.id from functional.alltypesagg a where " + "a.bigint_col = t.bigint_col)", op), "Unsupported correlated subquery with " + "grouping and/or aggregation: SELECT DISTINCT a.id FROM " + "functional.alltypesagg a WHERE a.bigint_col = t.bigint_col");
        // Multiple subquery predicates
        AnalyzesOk(String.format("select * from functional.alltypes t where id %s " + "(select id from functional.alltypestiny where int_col = 10) and int_col %s " + "(select int_col from functional.alltypessmall where bigint_col = 1000) and " + "string_col not in (select string_col from functional.alltypesagg where " + "tinyint_col > 10) and bool_col = false", op, op));
        AnalyzesOk(String.format("select id, year, month from " + "functional.allcomplextypes t where id %s " + "(select item from t.int_array_col where item < 10) and id not in " + "(select f1 from t.struct_array_col where f2 = 'test')", op));
        // Correlated subquery with a LIMIT clause
        AnalysisError(String.format("select * from functional.alltypes t where id %s " + "(select s.id from functional.alltypesagg s where s.int_col = t.int_col " + "limit 1)", op), "Unsupported correlated subquery with a LIMIT clause: " + "SELECT s.id FROM functional.alltypesagg s WHERE s.int_col = t.int_col " + "LIMIT 1");
        // Correlated IN with an analytic function
        AnalysisError(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 " + "where int_col %s (select min(bigint_col) over (partition by bool_col) " + "from functional.alltypessmall t2 where t1.id < t2.id)", op), "Unsupported " + "correlated subquery with grouping and/or aggregation: SELECT " + "min(bigint_col) OVER (PARTITION BY bool_col) FROM " + "functional.alltypessmall t2 WHERE t1.id < t2.id");
        // IN subquery in binary predicate
        AnalysisError(String.format("select * from functional.alltypestiny where " + "(tinyint_col %s (1,2)) = (bool_col %s (select bool_col from " + "functional.alltypes))", op, op), String.format("IN subquery predicates are not supported " + "in binary predicates: (tinyint_col %s (1, 2)) = (bool_col %s (SELECT " + "bool_col FROM functional.alltypes))", op, op));
        // Column labels may conflict after the rewrite as an inline view
        AnalyzesOk(String.format("select int_col from functional.alltypestiny where " + "int_col %s (select 1 as int_col from functional.alltypesagg)", op));
        AnalyzesOk(String.format("select int_col from functional.alltypestiny a where " + "int_col %s (select 1 as int_col from functional.alltypesagg b " + "where a.int_col = b.int_col)", op));
        // NOT compound predicates with OR
        AnalyzesOk(String.format("select * from functional.alltypes t where not (" + "id %s (select id from functional.alltypesagg) or int_col < 10)", op));
        AnalyzesOk(String.format("select * from functional.alltypes t where not (" + "t.id < 10 or not (t.int_col %s (select int_col from " + "functional.alltypesagg) and t.bool_col = false))", op));
    }
}

@Test
public void TestInConstantLHSSubqueries() throws AnalysisException {
    // [NOT] IN subquery predicates
    String[] operators = { "IN", "NOT IN" };
    for (String op : operators) {
        // Uncorrelated subquery.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select int_col from functional.alltypesagg)", op));
        // Uncorrelated and limited subquery.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select int_col from functional.alltypesagg limit 1)", op));
        // Select * in uncorrelated subquery.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select * from functional.tinyinttable)", op));
        // Select * in subquery, uncorrelated inline view.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select * from (select f2 from functional.emptytable) s)", op));
        // Uncorrelated aggregate subquery.
        AnalyzesOk(String.format("select * from functional.alltypestiny t1 where " + "10 %s (select max(int_col) from functional.alltypestiny)", op));
        AnalyzesOk(String.format("select * from functional.alltypestiny t1 where " + "(10 - 2) %s (select count(*) from functional.alltypestiny)", op));
        // Uncorrelated analytic function.
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where 1 %s (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 where " + "int_col < 10)", op));
        // Uncorrelated group by with no aggregate function.
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col %s (select int_col " + "from functional.alltypessmall t2 where " + "int_col < 10 group by int_col)", op));
        // Uncorrelated group by with only aggregate function.
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col %s (select max(id) " + "from functional.alltypessmall t2 where " + "int_col < 10 group by int_col)", op));
        // Nested subqueries.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select int_col from functional.tinyinttable where " + "1 %s (select int_col from functional.alltypestiny))", op, op));
        // Nested subqueries with *.
        AnalyzesOk(String.format("select * from functional.alltypes t where 1 %s " + "(select * from functional.tinyinttable where " + "1 %s (select * from functional.tinyinttable))", op, op));
        // Limit + correlation
        AnalysisError(String.format("select id from functional.alltypessmall a where 1 " + "%s (select int_col from functional.alltypestiny b where b.id = a.id limit 5)", op), "Unsupported correlated subquery with a LIMIT clause: ");
        // Order + limit + correlation.
        AnalysisError(String.format("select id from functional.alltypessmall a where 1 %s " + "(select int_col from functional.alltypestiny b where b.id = a.id " + "order by int_col limit 5)", op), "Unsupported correlated subquery with a LIMIT clause");
    }
    // Non-equijoins are not supported for NOT IN (not supported for EXISTS) when there
    // is a constant on the left-hand side and a correlation.
    // TODO: move into above, main test loop when NOT IN is supported.
    for (String cmpOp : nonEquiCmpOperators) {
        // Constant on the left hand side: correlated, non-equijoins
        AnalyzesOk(String.format("select 1 from functional.alltypes t where 1 IN " + "(select int_col from functional.alltypesagg g where g.id %s t.id)", cmpOp));
        AnalysisError(String.format("select 1 from functional.alltypes t where 1 NOT IN " + "(select int_col from functional.alltypesagg g where g.id %s t.id)", cmpOp), String.format("Unsupported NOT IN predicate with subquery: 1 NOT IN", cmpOp));
        // Constant on the left hand side: correlated, non-equijoin with a group by.
        AnalyzesOk(String.format("select id, count(*) from functional.alltypes t " + "where 1 IN (select id from functional.alltypesagg g where t.int_col %s " + "g.int_col) group by id", cmpOp));
        AnalysisError(String.format("select id, count(*) from functional.alltypes t " + "where 1 NOT IN (select id from functional.alltypesagg g where t.int_col %s " + "g.int_col) group by id", cmpOp), String.format("Unsupported NOT IN predicate with subquery: 1 NOT IN", cmpOp));
    }
    // Correlated subquery.
    AnalyzesOk("select * from functional.alltypes a where 1 in " + "(select id from functional.alltypesagg s where s.int_col = a.int_col)");
    AnalysisError("select * from functional.alltypes a where 1 not in " + "(select id from functional.alltypesagg s where s.int_col = a.int_col)", "Unsupported NOT IN predicate with subquery: 1 NOT IN");
    // Select * in correlated subquery.
    AnalyzesOk("select * from functional.alltypes t where 1 in " + "(select * from functional.tinyinttable x where t.id = x.int_col)");
    AnalysisError("select * from functional.alltypes t where 1 not in " + "(select * from functional.tinyinttable x where t.id = x.int_col)", "Unsupported NOT IN predicate with subquery: 1 NOT IN");
    // Select * in subquery, correlated inline view.
    AnalyzesOk("select * from functional.alltypes t where 1 in " + "(select * from (select f2 from functional.emptytable) s " + "where s.f2 = t.int_col)");
    AnalysisError("select * from functional.alltypes t where 1 not in " + "(select * from (select f2 from functional.emptytable) s " + "where s.f2 = t.int_col)", "Unsupported NOT IN predicate with subquery: 1 NOT IN");
}

@Test
public void TestExistsSubqueries() throws AnalysisException {
    String[] existsOperators = { "exists", "not exists" };
    for (String op : existsOperators) {
        // [NOT] EXISTS predicate (correlated)
        AnalyzesOk(String.format("select * from functional.alltypes t " + "where %s (select * from functional.alltypestiny p where " + "p.id = t.id)", op));
        AnalyzesOk(String.format("select count(*) from functional.alltypes t " + "where %s (select * from functional.alltypestiny p where " + "p.int_col = t.int_col and p.bool_col = false)", op));
        AnalyzesOk(String.format("select count(*) from functional.alltypes t, " + "functional.alltypessmall s where s.id = t.id and %s (select * from " + "functional.alltypestiny a where a.int_col = t.int_col)", op));
        AnalyzesOk(String.format("select count(*) from functional.alltypes t, " + "functional.alltypessmall s where s.id = t.id and %s (select * from " + "functional.alltypestiny a where a.int_col = t.int_col and a.bool_col = " + "t.bool_col)", op));
        // Multiple [NOT] EXISTS predicates
        AnalyzesOk(String.format("select 1 from functional.alltypestiny t where " + "%s (select * from functional.alltypessmall s where s.id = t.id) and " + "%s (select NULL from functional.alltypesagg g where t.int_col = g.int_col)", op, op));
        // OR between two subqueries
        AnalysisError(String.format("select * from functional.alltypestiny t where " + "%s (select * from functional.alltypesagg a where a.id = t.id) or %s " + "(select * from functional.alltypessmall s where s.int_col = t.int_col)", op, op), String.format("Multiple subqueries are not supported in expression: %s " + "(SELECT * FROM functional.alltypesagg a WHERE a.id = t.id) OR %s (SELECT " + "* FROM functional.alltypessmall s WHERE s.int_col = t.int_col)", op.toUpperCase(), op.toUpperCase()));
        // Complex correlation predicates
        AnalyzesOk(String.format("select 1 from functional.alltypestiny t where " + "%s (select * from functional.alltypesagg a where a.id = t.id + 1) and " + "%s (select 1 from functional.alltypes s where s.int_col + s.bigint_col = " + "t.bigint_col + 1)", op, op));
        // Correlated predicates
        AnalyzesOk(String.format("select * from functional.alltypestiny t where " + "%s (select * from functional.alltypesagg g where t.int_col = g.int_col " + "and t.bool_col = false)", op));
        AnalyzesOk(String.format("select * from functional.alltypestiny t where " + "%s (select id from functional.alltypessmall s where t.tinyint_col = " + "s.tinyint_col and t.bool_col)", op));
        // Multiple nesting levels
        AnalyzesOk(String.format("select * from functional.alltypes t where %s " + "(select * from functional.alltypessmall s where t.id = s.id and %s " + "(select * from functional.alltypestiny g where g.int_col = s.int_col))", op, op));
        AnalyzesOk(String.format("select * from functional.alltypes t where %s " + "(select * from functional.alltypessmall s where t.id = s.id and %s " + "(select * from functional.alltypestiny g where g.bool_col = " + "s.bool_col))", op, op));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes t1 where %s " + "(select f11 from t1.complex_nested_struct_col.f2 t2 " + "where t1.id = f11 and %s " + "(select value.f21 from t2.f12 where key = 'test'))", op, op));
        // Correlated EXISTS subquery with aggregation only in the HAVING clause
        AnalyzesOk(String.format("select 1 from functional.alltypestiny t1 " + "where %s (select 1 from functional.alltypestiny t2 where " + "t1.int_col = t2.int_col having count(*) > 1)", op));
        // Correlated EXISTS subquery with a group by and aggregation
        AnalyzesOk(String.format("select 1 from functional.alltypestiny t " + "where %s (select id, count(*) from functional.alltypesagg g where " + "t.id = g.id group by id having count(*) > 2)", op));
        // Correlated EXISTS subquery with a HAVING clause but no grouping or
        // aggregate exprs
        AnalysisError(String.format("select 1 from functional.alltypestiny t1 " + "where %s (select 1 from functional.alltypestiny t2 where " + "t1.int_col = t2.int_col having t2.int_col > 1)", op), "Unsupported correlated EXISTS subquery with a HAVING clause: " + "SELECT 1 FROM functional.alltypestiny t2 WHERE t1.int_col = " + "t2.int_col HAVING t2.int_col > 1");
        // Correlated EXISTS subquery with a HAVING clause and non-equality
        // correlated predicates
        AnalysisError(String.format("select 1 from functional.alltypestiny t1 " + "where %s (select 1 from functional.alltypestiny t2 where " + "t1.int_col < t2.int_col and t1.id = t2.id group by t2.id " + "having count(1) = 1)", op), "Unsupported correlated " + "EXISTS subquery with a HAVING clause: SELECT 1 FROM " + "functional.alltypestiny t2 WHERE t1.int_col < t2.int_col AND " + "t1.id = t2.id GROUP BY t2.id HAVING count(1) = 1");
        AnalysisError(String.format("select 1 from functional.alltypestiny t1 " + "where %s (select 1 from functional.alltypestiny t2 where t1.id = t2.id " + "and (t1.string_col like t2.string_col) = true group by t2.id " + "having count(1) = 1)", op), "Unsupported correlated EXISTS subquery " + "with a HAVING clause: SELECT 1 FROM functional.alltypestiny t2 WHERE " + "t1.id = t2.id AND (t1.string_col LIKE t2.string_col) = TRUE GROUP BY " + "t2.id HAVING count(1) = 1");
        AnalysisError(String.format("select id from functional.allcomplextypes t where %s " + "(select avg(f1) from t.struct_array_col a where t.int_struct_col.f1 < a.f1 " + "and a.f2 != 'xyz' group by a.f2 having count(*) > 2)", op), "Unsupported correlated EXISTS subquery with a HAVING clause: " + "SELECT avg(f1) FROM t.struct_array_col a WHERE t.int_struct_col.f1 < a.f1 " + "AND a.f2 != 'xyz' GROUP BY a.f2 HAVING count(*) > 2");
        // Correlated EXISTS subquery with an analytic function
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where %s (select min(bigint_col) over " + "(partition by bool_col) from functional.alltypessmall t2 where " + "t1.id = t2.id)", op));
        // Correlated EXISTS subquery with an analytic function and a group by
        // clause
        AnalyzesOk(String.format("select id, int_col, bool_col from " + "functional.alltypestiny t1 where exists (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 " + "where t1.id = t2.id group by bigint_col, bool_col)", op));
        // Correlated [NOT] EXISTS subquery with relative table refs.
        AnalyzesOk(String.format("select id from functional.allcomplextypes t where %s " + "(select item from t.int_array_col a where t.id = a.item)", op));
        String[] nullOps = { "is null", "is not null" };
        for (String nullOp : nullOps) {
            // Uncorrelated EXISTS subquery in an IS [NOT] NULL predicate
            AnalyzesOk(String.format("select * from functional.alltypes where %s " + "(select * from functional.alltypestiny) %s and id < 5", op, nullOp));
            // Correlated EXISTS subquery in an IS [NOT] NULL predicate
            AnalyzesOk(String.format("select * from functional.alltypes t where " + "%s (select 1 from functional.alltypestiny s where t.id = s.id) " + "%s and t.bool_col = false", op, nullOp));
        }
    }
    // Uncorrelated EXISTS subquery with an analytic function
    AnalyzesOk("select * from functional.alltypestiny t " + "where EXISTS (select id, min(int_col) over (partition by bool_col) " + "from functional.alltypesagg a where bigint_col < 10)");
    for (String cmpOp : nonEquiCmpOperators) {
        // Allowed because the subquery only has relative table refs.
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes t where exists " + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 %s a.f1)", cmpOp));
        // Not allowed because the subquery has absolute table refs.
        AnalysisError(String.format("select * from functional.alltypes t where exists " + "(select * from functional.alltypesagg a where t.id %s a.id)", cmpOp), String.format("Unsupported predicate with subquery: EXISTS (SELECT * FROM " + "functional.alltypesagg a WHERE t.id %s a.id)", cmpOp));
    }
    // Correlated BETWEEN predicate with relative table refs.
    AnalyzesOk("select 1 from functional.allcomplextypes t where exists " + "(select a.f1 from t.struct_array_col a " + " where a.f1 between t.int_struct_col.f1 and t.int_struct_col.f2)");
    // Correlated BETWEEN predicate with absolute table refs.
    AnalysisError("select 1 from functional.alltypes t where EXISTS " + "(select id from functional.alltypessmall a " + " where a.int_col between t.tinyint_col and t.bigint_col)", "Unsupported predicate with subquery: " + "EXISTS (SELECT id FROM functional.alltypessmall a " + "WHERE a.int_col BETWEEN t.tinyint_col AND t.bigint_col)");
    // Uncorrelated EXISTS in a query with GROUP BY
    AnalyzesOk("select id, count(*) from functional.alltypes t " + "where exists (select 1 from functional.alltypestiny where id < 5) group by id");
    // Subquery with a correlated predicate that cannot be transformed into an
    // equi-join is legal with only relative refs in the subquery
    AnalyzesOk("select id from functional.allcomplextypes t where " + "exists (select 1 from t.int_array_col a where t.id = 10)");
    // Subquery with a correlated predicate that cannot be transformed into an
    // equi-join is illegal with absolute table refs in the subquery
    AnalysisError("select * from functional.alltypestiny t where " + "exists (select int_col + 1 from functional.alltypessmall s where " + "t.int_col = 10)", "Unsupported predicate with subquery: EXISTS " + "(SELECT int_col + 1 FROM functional.alltypessmall s WHERE t.int_col = 10)");
    // Uncorrelated EXISTS subquery
    AnalyzesOk("select * from functional.alltypestiny where exists " + "(select * from functional.alltypesagg where id < 10)");
    AnalyzesOk("select id from functional.alltypestiny where exists " + "(select id from functional.alltypessmall where bool_col = false)");
    AnalyzesOk("select 1 from functional.alltypestiny t where exists " + "(select 1 from functional.alltypessmall where id < 5)");
    AnalyzesOk("select 1 + 1 from functional.alltypestiny where exists " + "(select null from functional.alltypessmall where id != 5)");
    AnalyzesOk(String.format("select id from functional.allcomplextypes t where exists " + "(select item from t.int_array_col a where item < 10)"));
    // Multiple nesting levels with uncorrelated EXISTS
    AnalyzesOk("select id from functional.alltypes where exists " + "(select id from functional.alltypestiny where int_col < 10 and exists (" + "select id from functional.alltypessmall where bool_col = true))");
    // Uncorrelated NOT EXISTS with relative table ref
    AnalyzesOk(String.format("select id from functional.allcomplextypes t where not exists " + "(select item from t.int_array_col a where item < 10)"));
    // Uncorrelated NOT EXISTS subquery
    AnalyzesOk("select * from functional.alltypestiny where not exists " + "(select 1 from functional.alltypessmall where bool_col = false)");
    // Subquery references an explicit alias from the outer block in the FROM
    // clause
    AnalysisError("select * from functional.alltypestiny t where " + "exists (select * from t)", "Illegal table reference to non-collection type: 't'");
    // Uncorrelated subquery with no FROM clause
    AnalyzesOk("select * from functional.alltypes where exists (select 1,2)");
    // EXISTS subquery in a binary predicate
    AnalysisError("select * from functional.alltypes where " + "if(exists(select * from functional.alltypesagg), 1, 0) = 1", "EXISTS subquery predicates are not supported in binary predicates: " + "if(EXISTS (SELECT * FROM functional.alltypesagg), 1, 0) = 1");
    // Correlated subquery with a LIMIT clause
    AnalyzesOk("select count(*) from functional.alltypes t where exists " + "(select 1 from functional.alltypesagg g where t.id = g.id limit 1)");
    // Column labels may conflict after the rewrite as an inline view
    AnalyzesOk("select int_col from functional.alltypestiny where " + "exists (select int_col from functional.alltypesagg)");
    AnalyzesOk("select int_col from functional.alltypestiny a where " + "not exists (select 1 as int_col from functional.alltypesagg b " + "where a.int_col = b.int_col)");
    // TODO: IMPALA-9945: EXISTS subquery inside FunctionCallExpr results in
    // IllegalStateException.
    AnalysisError("select * from functional.alltypes t " + "where nvl(exists(select id from functional.alltypesagg), false)", "Failed analysis after expr substitution.");
    // TODO: IMPALA-9945: EXISTS subquery inside CaseExpr results in
    // IllegalStateException.
    AnalysisError("select * from functional.alltypes t " + "where case when id % 2 = 0 then exists(select id from functional.alltypesagg) " + "end", "Failed analysis after expr substitution.");
}

/**
 * Test subqueries in an OR predicate. Most cases cannot be handled by the
 * StmtRewriter and should fail in analysis - see IMPALA-5226.
 */
@Test
public void TestDisjunctiveSubqueries() throws AnalysisException {
    // Only a single IN subquery is supported. Multiple subquery error cases are tested
    // in TestInSubqueries. We test the remaining cases here.
    // Basic IN subquery.
    AnalyzesOk("select * from functional.alltypes t where t.id IN " + "(select id from functional.alltypesagg) or t.bool_col = false");
    // IN subquery with unnesting of array.
    AnalyzesOk("select id from functional.allcomplextypes t where id IN " + "(select f1 from t.struct_array_col a where t.int_struct_col.f1 < a.f1) " + "or id < 10");
    // IN scalar subquery.
    AnalyzesOk("select * from functional.alltypes where int_col > 10 or " + "string_col in (select min(string_col) from functional.alltypestiny)");
    AnalyzesOk("select * from functional.alltypes where int_col > 10 or " + "string_col in (select min(string_col) from functional.alltypestiny " + "having min(string_col) > 'abc')");
    // Aggregate functions with GROUP BY not supported in disjunctive subquery.
    AnalysisError("select * from functional.alltypes where int_col > 10 or " + "string_col in (select min(string_col) from functional.alltypestiny " + "group by int_col)", "Aggregate functions in subquery in disjunction not supported: " + "SELECT min(string_col) FROM functional.alltypestiny GROUP BY int_col");
    // Aggregate functions in HAVING not supported in disjunctive subquery.
    AnalysisError("select * from functional.alltypes where int_col > 10 or " + "string_col in (select string_col from functional.alltypestiny " + "group by string_col having min(int_col) > 1)", "Aggregate functions in subquery in disjunction not supported: " + "SELECT string_col FROM functional.alltypestiny GROUP BY string_col " + "HAVING min(int_col) > 1");
    // GROUP BY in subquery can be ignored if not aggregate function are present.
    AnalyzesOk("select * from functional.alltypes t where t.id IN " + "(select int_col from functional.alltypesagg group by int_col, string_col) " + "or t.bool_col = false");
    AnalyzesOk("select * from functional.alltypes t where t.id IN " + "(select int_col from functional.alltypesagg group by int_col) " + "or t.bool_col = false");
    // DISTINCT in subquery should work.
    AnalyzesOk("select * from functional.alltypes t where t.id IN " + "(select distinct id from functional.alltypesagg) or t.bool_col = false");
    // NOT IN, EXISTS and NOT EXISTS subqueries are not supported.
    AnalysisError("select * from functional.alltypes t where t.id not in " + "(select id from functional.alltypesagg) OR t.int_col = 10", "NOT IN subqueries in OR predicates are not supported: t.id NOT IN " + "(SELECT id FROM functional.alltypesagg) OR t.int_col = 10");
    AnalysisError("select * from functional.alltypes t where exists (select 1 " + "from functional.alltypesagg t2 where t.id = t2.id) OR t.int_col = 10", "EXISTS/NOT EXISTS subqueries in OR predicates are not supported: EXISTS " + "(SELECT 1 FROM functional.alltypesagg t2 WHERE t.id = t2.id) OR " + "t.int_col = 10");
    // Negated [NOT] IN subquery with disjunction. Only IN can be rewritten by the
    // analyzer.
    AnalysisError("select * from functional.alltypes t where not (t.id in " + "(select id from functional.alltypesagg) and t.int_col = 10)", "NOT IN subqueries in OR predicates are not supported: t.id NOT IN " + "(SELECT id FROM functional.alltypesagg) OR t.int_col != 10");
    AnalyzesOk("select * from functional.alltypes t where not (t.id not in " + "(select id from functional.alltypesagg) and t.int_col = 10)");
    // Comparator-based subqueries in disjunctions are supported for scalar subqueries
    // but not runtime scalar subqueries.
    AnalyzesOk("select * from functional.alltypes t where t.id = " + "(select min(id) from functional.alltypesagg g) or t.id = 10");
    AnalyzesOk("select * from functional.alltypes t where t.id = " + "(select min(id) from functional.alltypesagg g where t.int_col = g.int_col) " + "or t.id = 10");
    AnalysisError("select * from functional.alltypes t where t.id = " + "(select id from functional.alltypesagg g where t.int_col = g.int_col) " + "or t.id = 10", "Unsupported correlated subquery with runtime scalar check: SELECT id FROM " + "functional.alltypesagg g WHERE t.int_col = g.int_col");
    // OR predicates must be at top-level - can't be more deeply nested inside another
    // predicate.
    AnalysisError("select * from functional.alltypes " + "where int_col > 10 = (string_col in ('a', 'b') or string_col in " + "(select min(string_col) from functional.alltypestiny))", "IN subquery predicates are not supported in binary predicates: int_col > 10 = " + "(string_col IN ('a', 'b') OR string_col IN (SELECT min(string_col) " + "FROM functional.alltypestiny))");
    // IN subquery inside function call inside OR is supported.
    AnalyzesOk("select * from functional.alltypes t " + "where nvl(int_col in (select id from functional.alltypesagg), false) or id = 2");
    // IN subquery inside case inside OR is supported.
    AnalyzesOk("select * from functional.alltypes t " + "where case when id % 2 = 0 then int_col in (" + "   select id from functional.alltypesagg) end or id = 2");
    // BETWEEN predicate is rewritten during analysis into inequality operators. The
    // subquery rewriter cannot directly handle BETWEEN predicates, but should be able
    // to handle the rewritten version of BETWEEN. Ensure this is handled correctly,
    // with the same validations applied as other predicates.
    AnalyzesOk("select int_col from functional.alltypes t " + " where (t.int_col is null or (t.int_col between " + "   (select min(int_col) from functional.alltypesagg t2 where t.year = t2.year)" + "   and 2))");
    AnalysisError("select int_col from functional.alltypes t " + " where (t.int_col is null or (t.int_col between " + "  (select min(int_col) from functional.alltypesagg t2 where t.year = t2.year) " + "  and (select max(int_col) from functional.alltypesagg t3)))", "Multiple subqueries are not supported in expression: (t.int_col IS NULL OR " + "t.int_col >= (SELECT min(int_col) FROM functional.alltypesagg t2 WHERE " + "t.`year` = t2.`year`) AND " + "t.int_col <= (SELECT max(int_col) FROM functional.alltypesagg t3))");
    // LIKE predicate can be converted into a join conjunct.
    AnalyzesOk("select * from functional.alltypes t1 " + "where string_col like (select min(string_col) from functional.alltypesagg t2 " + " where t1.int_col = t2.int_col) or id = 2");
    // OR predicates nested inside a different expr type should be rejected -
    // the rewrite is only implemented for WHERE and HAVING conjuncts with OR
    // at the top level. The different Expr subclasses should reject subqueries
    // during analysis. We try to test all Expr subclasses that could contain
    // a Subquery here. Note that many of these are also unsupported in general -
    // i.e. even outside a disjunct.
    // TODO: IMPALA-5226: support all of these that can be safely rewritten into
    // joins.
    // IsNullPredicate rejects nested subqueries.
    AnalysisError("select * from functional.alltypes t " + "where cast((t.id IN (select id from functional.alltypesagg) " + "  or t.bool_col = false) as string) is not null ", "Unsupported IS NULL predicate that contains a subquery: " + "CAST((t.id IN (SELECT id FROM functional.alltypesagg) " + "OR t.bool_col = FALSE) AS STRING) IS NOT NULL");
    AnalysisError("select * from functional.alltypes t " + "where cast((t.id IN (select id from functional.alltypesagg) " + "  or t.bool_col = false) as string) is null ", "Unsupported IS NULL predicate that contains a subquery: " + "CAST((t.id IN (SELECT id FROM functional.alltypesagg) " + "OR t.bool_col = FALSE) AS STRING) IS NULL");
    // BinaryPredicate rejects nested subqueries.
    AnalysisError("select * from functional.alltypes t " + "where (t.id IN (select id from functional.alltypesagg) " + "or t.bool_col = false) > 1", "IN subquery predicates are not supported in binary predicates: " + "(t.id IN (SELECT id FROM functional.alltypesagg) OR t.bool_col = FALSE) > 1");
    // InPredicate rejects nested subqueries.
    AnalysisError("select * from functional.alltypes t1 " + "where id in (1, (select min(id) from functional.alltypesagg t2 " + "where t1.int_col = t2.int_col)) or t1.bool_col = false", "Unsupported IN predicate with a subquery: id IN 1, " + "(SELECT min(id) FROM functional.alltypesagg t2 WHERE t1.int_col = t2.int_col)");
    // Subquery that is argument of ArithmeticExpr inside OR is not supported.
    AnalysisError("select * from functional.alltypes t1 " + "where (select min(int_col) from functional.alltypesagg t2 " + "       where t1.int_col = t2.int_col) % 2 = 0 or id = 1", "Subqueries that are arguments to non-predicate exprs are not supported inside " + "OR: (SELECT min(int_col) FROM functional.alltypesagg t2 " + "WHERE t1.int_col = t2.int_col) % 2 = 0 OR id = 1");
    // Subquery that is argument of TimestampArithmeticExpr inside OR is not supported.
    AnalysisError("select * from functional.alltypes t1 " + "where (select min(timestamp_col) from functional.alltypesagg t2 " + "       where t1.int_col = t2.int_col) + interval 1 day > '2020-01-01' or id = 2", "Subqueries that are arguments to non-predicate exprs are not supported inside " + "OR: (SELECT min(timestamp_col) FROM functional.alltypesagg t2 " + "WHERE t1.int_col = t2.int_col) + INTERVAL 1 day > '2020-01-01' OR id = 2");
    // Subquery that is argument of CaseExpr inside OR is not supported.
    AnalysisError("select * from functional.alltypes t " + "where case when id % 2 = 0 then (" + "   select bool_col from functional.alltypesagg) end or id = 2", "Subqueries that are arguments to non-predicate exprs are not supported inside " + "OR: CASE WHEN id % 2 = 0 THEN (" + "SELECT bool_col FROM functional.alltypesagg) END OR id = 2");
}

@Test
public void TestAggregateSubqueries() throws AnalysisException {
    String[] aggFns = { "count(id)", "max(id)", "min(id)", "avg(id)", "sum(id)" };
    for (String aggFn : aggFns) {
        for (String cmpOp : cmpOperators) {
            // Uncorrelated
            AnalyzesOk(String.format("select * from functional.alltypes where id %s " + "(select %s from functional.alltypestiny)", cmpOp, aggFn));
            AnalyzesOk(String.format("select * from functional.alltypes where " + "(select %s from functional.alltypestiny) %s id", aggFn, cmpOp));
            AnalyzesOk(String.format("select id from functional.allcomplextypes t where id %s " + "(select %s from (select item as id from t.int_array_col) v)", cmpOp, aggFn));
            // Uncorrelated with constant expr
            AnalyzesOk(String.format("select * from functional.alltypes where 10 %s " + "(select %s from functional.alltypestiny)", cmpOp, aggFn));
            // Uncorrelated with complex cmp expr
            AnalyzesOk(String.format("select * from functional.alltypes where id + 10 %s " + "(select %s from functional.alltypestiny)", cmpOp, aggFn));
            AnalyzesOk(String.format("select * from functional.alltypes where id + 10 %s " + "(select %s + 1 from functional.alltypestiny)", cmpOp, aggFn));
            AnalyzesOk(String.format("select * from functional.alltypes where " + "(select %s + 1 from functional.alltypestiny) %s id + 10", aggFn, cmpOp));
            AnalyzesOk(String.format("select 1 from functional.alltypes where " + "1 + (select %s - 1 from functional.alltypestiny where bool_col = false) " + "%s id - 10", aggFn, cmpOp));
            AnalyzesOk(String.format("select 1 from functional.alltypestiny t1 where " + "(select %s from functional.alltypes) - t1.id %s " + "t1.tinyint_col", aggFn, cmpOp));
            AnalyzesOk(String.format("select 1 from functional.alltypestiny t1 where " + "(select %s from functional.alltypes) + t1.id %s " + "t1.tinyint_col + t1.bigint_col + 1", aggFn, cmpOp));
            AnalyzesOk(String.format("select 1 from functional.alltypestiny t1 inner " + "join functional.alltypessmall t2 on t1.id = t2.id where " + "(select %s from functional.alltypes) + 1 %s t1.int_col + t2.int_col", aggFn, cmpOp));
            // Correlated
            AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "id %s (select %s from functional.alltypestiny t where t.bool_col = false " + "and a.int_col = t.int_col) and a.bigint_col < 10", cmpOp, aggFn));
            AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "id %s (select %s from functional.alltypestiny t where " + "t.int_col = a.int_col and a.id < 10)", cmpOp, aggFn));
            // TODO: The rewrite of this query is correct, but could be improved by using a
            // semi join instead of an outer join.
            AnalyzesOk(String.format("select id from functional.allcomplextypes t where id " + " %s (select %s from (select f1 as id, f2 from t.struct_array_col) v " + "where t.int_struct_col.f1 < v.id)", cmpOp, aggFn));
            // Correlated with inequality predicate
            AnalysisError(String.format("select id from functional.alltypes t1 where " + "id %s (select %s from functional.alltypestiny t2 where " + "t1.int_col = t2.int_col and t1.tinyint_col < t2.tinyint_col)", cmpOp, aggFn), String.format("Unsupported aggregate subquery with non-equality " + "correlated predicates: t1.tinyint_col < t2.tinyint_col", aggFn));
            AnalysisError(String.format("select id from functional.alltypes t1 where " + "id %s (select %s from functional.alltypestiny t2 where " + "t1.int_col = t2.int_col and t1.tinyint_col + 1 < t2.tinyint_col - 1)", cmpOp, aggFn), String.format("Unsupported aggregate subquery with non-equality " + "correlated predicates: t1.tinyint_col + 1 < t2.tinyint_col - 1", aggFn));
            // Correlated with constant expr
            AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "10 %s (select %s from functional.alltypestiny t where t.bool_col = false " + "and a.int_col = t.int_col) and a.bigint_col < 10", cmpOp, aggFn));
            // Correlated with complex expr
            AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "id - 10 %s (select %s from functional.alltypestiny t where t.bool_col = " + "false and a.int_col = t.int_col) and a.bigint_col < 10", cmpOp, aggFn));
            // count is not supported in select list expressions of a correlated subquery
            if (aggFn.equals("count(id)")) {
                AnalysisError(String.format("select count(*) from functional.alltypes a where " + "id - 10 %s (select 1 + %s from functional.alltypestiny t where " + "t.bool_col = false and a.int_col = t.int_col) and a.bigint_col < 10", cmpOp, aggFn), String.format("Aggregate function that returns non-null " + "on an empty input cannot be used in an expression in a " + "correlated subquery's select list: (SELECT 1 + %s FROM " + "functional.alltypestiny t WHERE t.bool_col = FALSE AND a.int_col = " + "t.int_col)", aggFn));
                // TODO: This subquery with relative table refs could be supported if we used a
                // semi join instead of an outer join.
                AnalysisError(String.format("select id from functional.allcomplextypes t where id %s " + "(select %s + 1 from (select f1 as id, f2 from t.struct_array_col) v " + "where t.int_struct_col.f1 < v.id)", cmpOp, aggFn), "Aggregate function that returns non-null on an empty input " + "cannot be used in an expression in a correlated subquery's select list");
            } else {
                AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "id - 10 %s (select 1 + %s from functional.alltypestiny t where " + "t.bool_col = false and a.int_col = t.int_col) and a.bigint_col < 10", cmpOp, aggFn));
                AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "(select 1 + %s from functional.alltypestiny t where t.bool_col = false " + "and a.int_col = t.int_col) %s id - 10 and a.bigint_col < 10", aggFn, cmpOp));
                AnalyzesOk(String.format("select count(*) from functional.alltypes a where " + "1 + (select 1 + %s from functional.alltypestiny t where t.id = a.id " + "and t.int_col < 10) %s a.id + 10", aggFn, cmpOp));
                AnalyzesOk(String.format("select id from functional.allcomplextypes t where id %s " + "(select %s + 1 from (select f1 as id, f2 from t.struct_array_col) v " + "where t.int_struct_col.f1 < v.id)", cmpOp, aggFn));
            }
        }
    }
    // Column labels may conflict after the rewrite as an inline view
    AnalyzesOk("select 1 from functional.alltypestiny where " + "int_col = (select count(int_col) as int_col from functional.alltypesagg)");
    AnalyzesOk("select 1 from functional.alltypestiny where " + "int_col in (select sum(int_col) as int_col from functional.alltypesagg)");
    for (String cmpOp : cmpOperators) {
        // Multiple tables in parent and subquery query blocks
        AnalyzesOk(String.format("select * from functional.alltypes t, " + "functional.alltypesagg a where a.id = t.id and t.int_col %s (" + "select max(g.int_col) from functional.alltypestiny g left outer join " + "functional.alltypessmall s on s.bigint_col = g.bigint_col where " + "g.bool_col = false) and t.bool_col = true", cmpOp));
        // Group by in the parent query block
        AnalyzesOk(String.format("select t.int_col, count(*) from " + "functional.alltypes t left outer join functional.alltypesagg g " + "on t.id = g.id where t.bigint_col %s (select count(*) from " + "functional.alltypestiny a where a.int_col < 10) and g.bool_col = false " + "group by t.int_col having count(*) < 100", cmpOp));
        // Multiple binary predicates
        AnalyzesOk(String.format("select * from functional.alltypes a where " + "int_col %s (select min(int_col) from functional.alltypesagg g where " + "g.bool_col = false) and int_col %s (select max(int_col) from " + "functional.alltypesagg g where g.bool_col = true) and a.tinyint_col = 10", cmpOp, cmpOp));
        // Multiple nesting levels
        AnalyzesOk(String.format("select * from functional.alltypes a where " + "tinyint_col %s (select count(*) from functional.alltypesagg g where " + "g.int_col %s (select max(int_col) from functional.alltypestiny t where " + "t.id = g.id) and g.id = a.id and g.bool_col = false) and a.int_col < 10", cmpOp, cmpOp));
        // NOT with a binary subquery predicate
        AnalyzesOk(String.format("select * from functional.alltypes a where " + "not (int_col %s (select max(int_col) from functional.alltypesagg g where " + "a.id = g.id and g.bool_col = false))", cmpOp));
        // Subquery returns a scalar (no FORM clause)
        AnalyzesOk(String.format("select id from functional.alltypestiny where id %s " + "(select 1)", cmpOp));
        // Incompatible comparison types
        AnalysisError(String.format("select id from functional.alltypestiny where " + "int_col %s (select max(timestamp_col) from functional.alltypessmall)", cmpOp), String.format("operands of type INT and TIMESTAMP are not comparable: " + "int_col %s (SELECT max(timestamp_col) FROM functional.alltypessmall)", cmpOp));
        // Compatible comparison types
        AnalyzesOk(String.format("select date_col from functional.date_tbl where " + "date_col %s (select max(timestamp_col) from functional.alltypessmall)", cmpOp));
        // Distinct in the outer select block
        if (cmpOp == "=") {
            AnalyzesOk(String.format("select distinct id from functional.alltypes a " + "where 100 %s (select count(*) from functional.alltypesagg g where " + "a.int_col %s g.int_col) and a.bool_col = false", cmpOp, cmpOp));
        } else {
            AnalysisError(String.format("select distinct id from functional.alltypes a " + "where 100 %s (select count(*) from functional.alltypesagg g where " + "a.int_col %s g.int_col) and a.bool_col = false", cmpOp, cmpOp), String.format("Unsupported aggregate subquery with non-equality " + "correlated predicates: a.int_col %s g.int_col", cmpOp));
        }
    }
    // Subquery returns multiple columns
    AnalysisError("select id from functional.alltypestiny where int_col = " + "(select id, int_col from functional.alltypessmall)", "operands of type INT and STRUCT<id:INT,int_col:INT> are not " + "comparable: int_col = (SELECT id, int_col FROM functional.alltypessmall)");
    AnalysisError("select * from functional.alltypestiny where id in " + "(select * from (values(1,2)) as t)", "Subquery must return a single column: (SELECT * FROM (VALUES(1, 2)) t)");
    // Subquery returns multiple columns due to a group by clause
    AnalysisError("select id from functional.alltypestiny where int_col = " + "(select int_col, count(*) from functional.alltypessmall group by int_col)", "operands of type INT and STRUCT<int_col:INT,_1:BIGINT> are not " + "comparable: int_col = (SELECT int_col, count(*) FROM " + "functional.alltypessmall GROUP BY int_col)");
    // Outer join with a table from the outer block using an explicit alias
    AnalysisError("select id from functional.alltypestiny t where int_col = " + "(select count(*) from functional.alltypessmall s left outer join t " + "on (t.id = s.id))", "Illegal table reference to non-collection type: 't'");
    AnalysisError("select id from functional.alltypestiny t where int_col = " + "(select count(*) from functional.alltypessmall s right outer join t " + "on (t.id = s.id))", "Illegal table reference to non-collection type: 't'");
    AnalysisError("select id from functional.alltypestiny t where int_col = " + "(select count(*) from functional.alltypessmall s full outer join t " + "on (t.id = s.id))", "Illegal table reference to non-collection type: 't'");
    // Multiple subqueries in a binary predicate
    AnalysisError("select * from functional.alltypestiny t where " + "(select count(*) from functional.alltypessmall) = " + "(select count(*) from functional.alltypesagg)", "Multiple subqueries are not " + "supported in binary predicates: (SELECT count(*) FROM " + "functional.alltypessmall) = (SELECT count(*) FROM functional.alltypesagg)");
    AnalysisError("select * from functional.alltypestiny t where " + "(select max(id) from functional.alltypessmall) + " + "(select min(id) from functional.alltypessmall) - " + "(select count(id) from functional.alltypessmall) < 1000", "Multiple subqueries are not supported in binary predicates: (SELECT max(id) " + "FROM functional.alltypessmall) + (SELECT min(id) FROM " + "functional.alltypessmall) - (SELECT count(id) FROM functional.alltypessmall) " + "< 1000");
    // Comparison between invalid types
    AnalysisError("select * from functional.alltypes where " + "(select max(string_col) from functional.alltypesagg) = 1", "operands of type STRING and TINYINT are not comparable: (SELECT " + "max(string_col) FROM functional.alltypesagg) = 1");
    // Comparison between valid types
    AnalyzesOk("select * from functional.alltypes where " + "(select max(date_col) from functional.date_tbl) = '2011-01-01'");
    // Aggregate subquery with a LIMIT 1 clause
    AnalyzesOk("select id from functional.alltypestiny t where int_col = " + "(select int_col from functional.alltypessmall limit 1)");
    // Correlated aggregate subquery with correlated predicate that can't be
    // transformed into an equi-join
    AnalyzesOk("select id from functional.alltypestiny t where " + "1 < (select sum(int_col) from functional.alltypessmall s where " + "t.id < 10)");
    // Aggregate subqueries in an IS [NOT] NULL predicate
    String[] nullOps = { "is null", "is not null" };
    for (String aggFn : aggFns) {
        for (String nullOp : nullOps) {
            // Uncorrelated aggregate subquery
            AnalyzesOk(String.format("select * from functional.alltypestiny where " + "(select %s from functional.alltypessmall where bool_col = false) " + "%s and int_col < 10", aggFn, nullOp));
            // Correlated aggregate subquery
            AnalyzesOk(String.format("select * from functional.alltypestiny t where " + "(select %s from functional.alltypessmall s where s.id = t.id " + "and s.bool_col = false) %s and bool_col = true", aggFn, nullOp));
        }
    }
    // Aggregate subquery with a correlated predicate that can't be transformed
    // into an equi-join in an IS NULL predicate
    AnalyzesOk("select 1 from functional.alltypestiny t where " + "(select max(id) from functional.alltypessmall s where t.id < 10) " + "is null");
    // Mathematical functions with scalar subqueries
    String[] mathFns = { "abs", "cos", "ceil", "floor" };
    for (String mathFn : mathFns) {
        for (String aggFn : aggFns) {
            String expr = aggFn.equals("count(id)") ? "" : "1 + ";
            for (String cmpOp : cmpOperators) {
                // Uncorrelated scalar subquery
                AnalyzesOk(String.format("select count(*) from functional.alltypes t where " + "%s((select %s %s from functional.alltypessmall where bool_col = " + "false)) %s 100 - t.int_col and t.bigint_col < 100", mathFn, expr, aggFn, cmpOp));
                // Correlated scalar subquery
                AnalyzesOk(String.format("select count(*) from functional.alltypes t where " + "%s((select %s %s from functional.alltypessmall s where bool_col = false " + "and t.id = s.id)) %s 100 - t.int_col and t.bigint_col < 100", mathFn, expr, aggFn, cmpOp));
            }
        }
    }
    // Conditional functions with scalar subqueries
    for (String aggFn : aggFns) {
        AnalyzesOk(String.format("select * from functional.alltypestiny t where " + "nullifzero((select %s from functional.alltypessmall s where " + "s.bool_col = false)) is null", aggFn));
        AnalyzesOk(String.format("select count(*) from functional.alltypes t where " + "zeroifnull((select %s from functional.alltypessmall s where t.id = s.id)) " + "= 0 and t.int_col < 10", aggFn));
        AnalyzesOk(String.format("select 1 from functional.alltypes t where " + "isnull((select %s from functional.alltypestiny s where s.bool_col = false " + "), 10) < 5", aggFn));
    }
    // Correlated aggregate subquery with a GROUP BY and a relative table ref
    // TODO: Modify the StmtRewriter to allow this query with only relative refs.
    AnalysisError("select min(t.year) from functional.allcomplextypes t " + "where t.id < (select max(f1) from t.struct_array_col a " + "where a.f1 = t.id group by a.f2 order by 1 limit 1)", "Unsupported correlated subquery with grouping and/or aggregation: " + "SELECT max(f1) FROM t.struct_array_col a WHERE a.f1 = t.id " + "GROUP BY a.f2 ORDER BY 1 ASC LIMIT 1");
    // Correlated aggregate subquery with a GROUP BY and an absolute table ref
    AnalysisError("select min(t.id) as min_id from functional.alltypestiny t " + "where t.int_col < (select max(s.int_col) from functional.alltypessmall s " + "where s.id = t.id group by s.bigint_col order by 1 limit 1)", "Unsupported correlated subquery with grouping and/or aggregation: " + "SELECT max(s.int_col) FROM functional.alltypessmall s WHERE " + "s.id = t.id GROUP BY s.bigint_col ORDER BY 1 ASC LIMIT 1");
    // Correlated aggregate subquery with a LIMIT clause
    AnalyzesOk("select count(*) from functional.alltypes t where " + "t.id = (select count(*) from functional.alltypesagg g where " + "g.int_col = t.int_col limit 1)");
    // Aggregate subquery with analytic function
    AnalyzesOk("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col = (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 where " + "int_col < 10)");
    // Aggregate subquery with analytic function + limit 1 and a relative table ref
    // TODO: Modify the StmtRewriter to allow this query with only relative refs.
    AnalysisError("select id from functional.allcomplextypes t where year = " + "(select min(f1) over (partition by f2) from t.struct_array_col a where " + "t.id = f1 limit 1)", "Unsupported correlated subquery with grouping and/or aggregation: " + "SELECT min(f1) OVER (PARTITION BY f2) FROM t.struct_array_col a " + "WHERE t.id = f1 LIMIT 1");
    // Aggregate subquery with analytic function + limit 1 and an absolute table ref
    AnalysisError("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col = (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 where " + "t1.id = t2.id and int_col < 10 limit 1)", "Unsupported correlated " + "subquery with grouping and/or aggregation: SELECT min(bigint_col) " + "OVER (PARTITION BY bool_col) FROM functional.alltypessmall t2 WHERE " + "t1.id = t2.id AND int_col < 10 LIMIT 1");
    // Uncorrelated aggregate subquery with analytic function and limit 1 clause
    AnalyzesOk("select id, int_col, bool_col from " + "functional.alltypestiny t1 where int_col = (select min(bigint_col) " + "over (partition by bool_col) from functional.alltypessmall t2 where " + "int_col < 10 limit 1)");
    // Subquery with distinct in binary predicate
    AnalyzesOk("select * from functional.alltypes where int_col = " + "(select distinct int_col from functional.alltypesagg)");
    AnalyzesOk("select * from functional.alltypes where int_col = " + "(select count(distinct int_col) from functional.alltypesagg)");
    // Multiple count aggregate functions in a correlated subquery's select list
    AnalysisError("select * from functional.alltypes t where " + "int_col = (select count(id) + count(int_col) - 1 from " + "functional.alltypesagg g where g.int_col = t.int_col)", "Aggregate function that returns non-null on an empty input " + "cannot be used in an expression in a correlated " + "subquery's select list: (SELECT count(id) + count(int_col) - 1 " + "FROM functional.alltypesagg g WHERE g.int_col = t.int_col)");
    // UDAs in aggregate subqqueries
    addTestUda("AggFn", Type.BIGINT, Type.BIGINT);
    AnalysisError("select * from functional.alltypesagg g where " + "(select aggfn(int_col) from functional.alltypes s where " + "s.id = g.id) = 10", "UDAs are not supported in the select list of " + "correlated subqueries: (SELECT default.aggfn(int_col) /* NATIVE UDF */ FROM " + "functional.alltypes s WHERE s.id = g.id)");
    AnalyzesOk("select * from functional.alltypesagg g where " + "(select aggfn(int_col) from functional.alltypes s where " + "s.bool_col = false) < 10");
    // sample, histogram in scalar subqueries
    String[] aggFnsReturningStringOnEmpty = { "sample(int_col)", "histogram(int_col)" };
    for (String aggFn : aggFnsReturningStringOnEmpty) {
        AnalyzesOk(String.format("select * from functional.alltypestiny t where " + "t.string_col = (select %s from functional.alltypesagg g where t.id = " + "g.id)", aggFn));
    }
    // Complex correlated predicate in which columns from the subquery appear in
    // both sides of a correlated binary predicate
    AnalysisError("select 1 from functional.alltypestiny t where " + "(select sum(t1.id) from functional.alltypesagg t1 inner join " + "functional.alltypes t2 on t1.id = t2.id where " + "t1.id + t2.id = t.int_col + t1.int_col) = t.int_col", "All subquery columns that participate in a predicate " + "must be on the same side of that predicate: t1.id + t2.id = t.int_col " + "+ t1.int_col");
}

