@Test
public void testScalarSubqueries() throws AnalysisException {
    // Scalar subquery check is done at runtime, not during analysis
    for (String cmpOp : cmpOperators) {
        AnalyzesOk(String.format("select id from functional.alltypestiny t where int_col %s " + "(select int_col from functional.alltypessmall)", cmpOp));
        AnalyzesOk(String.format("select id from functional.alltypestiny t where int_col %s " + "(select int_col from functional.alltypessmall where id = 1)", cmpOp));
        AnalyzesOk(String.format("select id from functional.alltypestiny t where int_col %s " + "1 - (select int_col from functional.alltypessmall where id = 1)", cmpOp));
        AnalyzesOk(String.format("select id from functional.alltypestiny t where int_col %s " + "1 - (select int_col from functional.alltypessmall limit 10)", cmpOp));
        AnalyzesOk(String.format("select id from functional.alltypestiny t where int_col %s " + "(select int_col from functional.alltypessmall) * 7", cmpOp));
    }
    AnalysisError("select * from functional.alltypes t1 where id < " + "(select id from functional.alltypes t2 where t1.int_col = t2.int_col)", "Unsupported correlated subquery with runtime scalar check: " + "SELECT id FROM functional.alltypes t2 WHERE t1.int_col = t2.int_col");
    // Scalar subqueries in the select list
    AnalyzesOk("select id, 10 + (select max(int_col) from functional.alltypestiny) " + "from functional.alltypestiny");
    AnalyzesOk("select id, (select count(*) from functional.alltypestiny where int_col " + "< (select max(int_col) from functional.alltypes)) from functional.dimtbl");
    AnalysisError("select id, (select id, count(*) from functional.alltypestiny " + "group by 1) from functional.dimtbl", "A non-scalar subquery is not supported in the expression: " + "(SELECT id, count(*) FROM functional.alltypestiny GROUP BY id)");
    AnalysisError("select id, (select count(*) from functional.alltypestiny b where " + "id=a.id ) from functional.alltypes a", "A correlated scalar subquery is not supported in the expression: " + "(SELECT count(*) FROM functional.alltypestiny b WHERE id = a.id)");
    AnalysisError("select id, min(id) in (select id from functional.alltypestiny) " + "from functional.alltypes a", "Only subqueries that are guaranteed to return a single row are supported: " + "min(id) IN (SELECT id FROM functional.alltypestiny)");
}

