    // so only an INT constant is tested, all others are the same.
    verifyNdv("10", 1);
    // Propagation of const NDV. All expressions save CASE use
    // the same max logic.
    verifyNdv("10 * 3", 1);
    // Planner defines NDV as "number of distinct values
