@Test
public void TestEqualityDisjunctsToInRuleSizeLimit() throws ImpalaException {
    String stmtPrefix = "select count(*) from functional.alltypes where ( ";
    // Test that EqualityDisjunctsToInRule doesn't create an expr with a number of
    // children exceeding the limit.
    {
        // Create a disjunct with 2 in-lists of length Expr.EXPR_CHILDREN_LIMIT - 1.
        StringBuilder stmtSb = new StringBuilder(stmtPrefix);
        for (int i = 0; i < 2; ++i) {
            int offset = (Expr.EXPR_CHILDREN_LIMIT - 1) * i;
            CreateInList(offset, Expr.EXPR_CHILDREN_LIMIT - 1, stmtSb);
            if (i != 1)
                stmtSb.append(" or ");
        }
        stmtSb.append(")");
        CheckNumChangesByEqualityDisjunctsToInRule(stmtSb.toString(), 0);
    }
    {
        // Create a disjunct with an in-list of length Expr.EXPR_CHILDREN_LIMIT - 1 and a
        // EQ predicate.
        StringBuilder stmtSb = new StringBuilder(stmtPrefix);
        CreateInList(0, Expr.EXPR_CHILDREN_LIMIT - 1, stmtSb);
        stmtSb.append("or string_col='").append(Expr.EXPR_CHILDREN_LIMIT - 1).append("')");
        CheckNumChangesByEqualityDisjunctsToInRule(stmtSb.toString(), 0);
    }
    {
        // Create a disjunct with an in-list of length Expr.EXPR_CHILDREN_LIMIT - 2 and 2
        // EQ predicates.
        StringBuilder stmtSb = new StringBuilder(stmtPrefix);
        CreateInList(0, Expr.EXPR_CHILDREN_LIMIT - 2, stmtSb);
        stmtSb.append("or string_col='").append(Expr.EXPR_CHILDREN_LIMIT - 2).append("' or string_col='").append(Expr.EXPR_CHILDREN_LIMIT - 1).append("')");
        CheckNumChangesByEqualityDisjunctsToInRule(stmtSb.toString(), 1);
    }
}

@Test
public void TestToSql() {
    TQueryOptions options = new TQueryOptions();
    options.setEnable_expr_rewrites(true);
    AnalysisContext ctx = createAnalysisCtx(options);
    //----------------------
    // Test query rewrites.
    //----------------------
    assertToSql(ctx, "select 1 + 1", "SELECT 1 + 1", "SELECT 2");
    assertToSql(ctx, "select (case when true then 1 else id end) from functional.alltypes " + "union " + "select 1 + 1", "SELECT (CASE WHEN TRUE THEN 1 ELSE id END) FROM functional.alltypes " + "UNION " + "SELECT 1 + 1", "SELECT 1 FROM functional.alltypes UNION SELECT 2");
    assertToSql(ctx, "values(1, '2', 3, 4.1), (1, '2', 3, 4.1)", "VALUES((1, '2', 3, 4.1), (1, '2', 3, 4.1))", "SELECT 1, '2', 3, 4.1 UNION ALL SELECT 1, '2', 3, 4.1");
    assertToSql(ctx, "select case when 1 = 1 then 1 else 2.0 end from functional.alltypes", "SELECT CASE WHEN 1 = 1 THEN 1 ELSE 2.0 END FROM functional.alltypes", "SELECT 1.0 FROM functional.alltypes");
    assertToSql(ctx, "select case when false then 1.0 else 2 end from functional.alltypes", "SELECT CASE WHEN FALSE THEN 1.0 ELSE 2 END FROM functional.alltypes", "SELECT 2.0 FROM functional.alltypes");
    assertToSql(ctx, "select * from functional.alltypes where case " + "when true = true then year < 2019 " + "when false then year > 2010 end", "SELECT * FROM functional.alltypes WHERE CASE " + "WHEN TRUE = TRUE THEN `year` < 2019 " + "WHEN FALSE THEN `year` > 2010 END", "SELECT * FROM functional.alltypes WHERE `year` < 2019");
    //-------------------------
    // Test subquery rewrites.
    //-------------------------
    assertToSql(ctx, "select * from (" + "select * from functional.alltypes where id = (select 1 + 1)) a", "SELECT * FROM (SELECT * FROM functional.alltypes WHERE id = (SELECT 1 + 1)) a", "SELECT * FROM (SELECT * FROM functional.alltypes LEFT SEMI JOIN " + "(SELECT 2) `$a$1` (`$c$1`) ON id = `$a$1`.`$c$1`) a");
    assertToSql(ctx, "select * from (select * from functional.alltypes where id = (select 1 + 1)) a " + "union " + "select * from (select * from functional.alltypes where id = (select 1 + 1)) b", "SELECT * FROM (SELECT * FROM functional.alltypes WHERE id = (SELECT 1 + 1)) a " + "UNION " + "SELECT * FROM (SELECT * FROM functional.alltypes WHERE id = (SELECT 1 + 1)) b", "SELECT * FROM (SELECT * FROM functional.alltypes LEFT SEMI JOIN (SELECT 2) " + "`$a$1` (`$c$1`) ON id = `$a$1`.`$c$1`) a " + "UNION " + "SELECT * FROM (SELECT * FROM functional.alltypes LEFT SEMI JOIN (SELECT 2) " + "`$a$1` (`$c$1`) ON id = `$a$1`.`$c$1`) b");
    assertToSql(ctx, "select * from " + "(select (case when true then 1 else id end) from functional.alltypes " + "union select 1 + 1) v", "SELECT * FROM (SELECT (CASE WHEN TRUE THEN 1 ELSE id END) " + "FROM functional.alltypes UNION SELECT 1 + 1) v", "SELECT * FROM (SELECT 1 FROM functional.alltypes " + "UNION SELECT 2) v");
    //---------------------
    // Test CTAS rewrites.
    //---------------------
    assertToSql(ctx, "create table ctas_test as select 1 + 1", "CREATE TABLE default.ctas_test\n" + "STORED AS TEXTFILE\n" + " AS SELECT 1 + 1", "CREATE TABLE default.ctas_test\n" + "STORED AS TEXTFILE\n" + " AS SELECT 2");
    //--------------------
    // Test DML rewrites.
    //--------------------
    // Insert
    assertToSql(ctx, "insert into functional.alltypes(id) partition(year=2009, month=10) " + "select 1 + 1", "INSERT INTO TABLE functional.alltypes(id) " + "PARTITION (`year`=2009, `month`=10) SELECT 1 + 1", "INSERT INTO TABLE functional.alltypes(id) " + "PARTITION (`year`=2009, `month`=10) SELECT 2");
    // Update.
    assertToSql(ctx, "update functional_kudu.alltypes " + "set string_col = 'test' where id = (select 1 + 1)", "UPDATE functional_kudu.alltypes SET string_col = 'test' " + "FROM functional_kudu.alltypes WHERE id = (SELECT 1 + 1)", "UPDATE functional_kudu.alltypes SET string_col = 'test' " + "FROM functional_kudu.alltypes LEFT SEMI JOIN (SELECT 2) `$a$1` (`$c$1`) " + "ON id = `$a$1`.`$c$1` WHERE id = (SELECT 2)");
    // Delete
    assertToSql(ctx, "delete functional_kudu.alltypes " + "where id = (select 1 + 1)", "DELETE FROM functional_kudu.alltypes " + "WHERE id = (SELECT 1 + 1)", "DELETE functional_kudu.alltypes " + "FROM functional_kudu.alltypes LEFT SEMI JOIN (SELECT 2) `$a$1` (`$c$1`) " + "ON id = `$a$1`.`$c$1` WHERE id = (SELECT 2)");
    //-------------------------
    // Test || rewrites.
    //-------------------------
    assertToSql(ctx, "select * from functional.alltypes where " + "int_col = 1 || int_col = 2 " + "|| tinyint_col > 5 || (string_col || string_col) = 'testtest'", "SELECT * FROM functional.alltypes WHERE " + "int_col = 1 OR int_col = 2 " + "OR tinyint_col > 5 OR (concat(string_col, string_col)) = 'testtest'", "SELECT * FROM functional.alltypes WHERE " + "int_col IN (1, 2) " + "OR tinyint_col > 5 OR concat(string_col, string_col) = 'testtest'");
    assertToSql(ctx, "select int_col = 1 || int_col = 2, string_col || 'test' " + "from functional.alltypes where " + "(bool_col || id = 2) || (string_col || 'test') = 'testtest'", "SELECT int_col = 1 OR int_col = 2, concat(string_col, 'test') " + "FROM functional.alltypes WHERE " + "(bool_col OR id = 2) OR (concat(string_col, 'test')) = 'testtest'", "SELECT int_col IN (1, 2), concat(string_col, 'test') " + "FROM functional.alltypes WHERE " + "bool_col OR id = 2 OR concat(string_col, 'test') = 'testtest'");
    // We don't do any rewrite for WITH clause.
    StatementBase stmt = (StatementBase) AnalyzesOk("with t as (select 1 + 1) " + "select id from functional.alltypes union select id from functional.alltypesagg", ctx);
    Assert.assertEquals(stmt.toSql(), stmt.toSql());
}

