@Test
public void TestToSqlWithAppxCountDistinctAndDefaultNdvs() {
    TQueryOptions options = new TQueryOptions();
    options.setEnable_expr_rewrites(true);
    AnalysisContext ctx = createAnalysisCtx(options);
    //----------------------
    // Test query rewrites.
    //----------------------
    String countDistinctSql = "SELECT count(DISTINCT id) FROM functional.alltypes";
    // No rewrite
    assertToSql(ctx, countDistinctSql, countDistinctSql, countDistinctSql);
    // Rewrite to ndv
    options.setAppx_count_distinct(true);
    assertToSql(createAnalysisCtx(options), countDistinctSql, countDistinctSql, "SELECT ndv(id) FROM functional.alltypes");
    // Rewrite to ndv(10)
    options.setDefault_ndv_scale(10);
    assertToSql(createAnalysisCtx(options), countDistinctSql, countDistinctSql, "SELECT ndv(id, 10) FROM functional.alltypes");
    String ndvSql = "SELECT ndv(id) FROM functional.alltypes";
    // No rewrite
    options.setDefault_ndv_scale(2);
    assertToSql(createAnalysisCtx(options), ndvSql, ndvSql, ndvSql);
    // Rewrite ndv scale
    options.setDefault_ndv_scale(9);
    assertToSql(createAnalysisCtx(options), ndvSql, ndvSql, "SELECT ndv(id, 9) FROM functional.alltypes");
    //-----------------------------------------------------------------------------------
    // Test complex sql which has all 3 types of functions.
    // NDV(<expr>) | NDV(<expr>, <scale>) | COUNT(DISTINCT <expr>)
    //
    // For coverage, we have these scenarios:
    // CASE 1: DEFAULT_NDV_SCALE=5(same as the value in original sql),
    //         APPX_COUNT_DISTINCT=True
    // CASE 2: DEFAULT_NDV_SCALE=5, APPX_COUNT_DISTINCT=False
    // CASE 3: DEFAULT_NDV_SCALE=9(different with original), APPX_COUNT_DISTINCT=True
    // CASE 4: DEFAULT_NDV_SCALE=3, APPX_COUNT_DISTINCT=False
    // CASE 5: DEFAULT_NDV_SCALE=2, APPX_COUNT_DISTINCT=True
    // CASE 6: DEFAULT_NDV_SCALE=2, APPX_COUNT_DISTINCT=False
    //-----------------------------------------------------------------------------------
    String sql1 = "SELECT ndv(id), ndv(id, 5), count(DISTINCT id) FROM " + "functional.alltypes";
    // CASE 1
    options.setDefault_ndv_scale(5).setAppx_count_distinct(true);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id, 5), ndv(id, 5), ndv(id, 5) FROM functional.alltypes");
    // CASE 2
    options.setDefault_ndv_scale(5).setAppx_count_distinct(false);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id, 5), ndv(id, 5), count(DISTINCT id)" + " FROM functional.alltypes");
    // CASE 3
    options.setDefault_ndv_scale(9).setAppx_count_distinct(true);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id, 9), ndv(id, 5), ndv(id, 9) FROM functional.alltypes");
    // CASE 4
    options.setDefault_ndv_scale(3).setAppx_count_distinct(false);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id, 3), ndv(id, 5), count(DISTINCT id) " + "FROM functional.alltypes");
    // CASE 5
    options.setDefault_ndv_scale(2).setAppx_count_distinct(true);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id), ndv(id, 5), ndv(id) FROM functional.alltypes");
    // CASE 6
    options.setDefault_ndv_scale(2).setAppx_count_distinct(false);
    assertToSql(createAnalysisCtx(options), sql1, sql1, "SELECT ndv(id), ndv(id, 5), count(DISTINCT id) FROM functional.alltypes");
}

@Test
public void TestShouldConvertToCNF() {
    TQueryOptions options = new TQueryOptions();
    options.setEnable_expr_rewrites(false);
    AnalysisContext ctx = createAnalysisCtx(options);
    // Positive tests
    List<String> convertablePredicates = Arrays.asList("select (1=cast(1 as int))", "select (cast(d_date_sk as int) = 10) from tpcds_parquet.date_dim", "select (d_date_sk = d_year) from tpcds_parquet.date_dim", "select (d_date_sk between 1 and 10) from tpcds_parquet.date_dim", "select (d_date_sk in (1,2,10)) from tpcds_parquet.date_dim", "select (d_date_sk is null) from tpcds_parquet.date_dim", "select (cos(1) = 1.1)", "select (cast(d_date_sk as int) * 2 = 10) from tpcds_parquet.date_dim", "select ((2 = cast(1 as int)) and (cos(1) = 1))", "select ((2 = cast(1 as int)) or (cast(0 as int) is not null))", "select (sin(cos(2*pi())))");
    for (String query : convertablePredicates) {
        Expr expr = analyze(query);
        assertTrue("Should convert to CNF: " + query, expr.shouldConvertToCNF());
    }
    // Negative tests
    List<String> inconvertablePredicates = Arrays.asList("select (upper(d_day_name) = 'A') from tpcds_parquet.date_dim", "select (d_day_name like '%A') from tpcds_parquet.date_dim", "select (coalesce(d_date_sk, -1) = d_year) from tpcds_parquet.date_dim", "select (log10(cast(1 + length(upper(d_day_name)) as double)) > 1.0) from " + "tpcds_parquet.date_dim");
    for (String query : inconvertablePredicates) {
        Expr expr = analyze(query);
        assertFalse("Should not convert to CNF: " + query, expr.shouldConvertToCNF());
    }
}

@Test
public void testBetweenToCompoundRule() throws ImpalaException {
    ExprRewriteRule rule = BetweenToCompoundRule.INSTANCE;
    // Basic BETWEEN predicates.
    RewritesOk("int_col between float_col and double_col", rule, "int_col >= float_col AND int_col <= double_col");
    RewritesOk("int_col not between float_col and double_col", rule, "int_col < float_col OR int_col > double_col");
    RewritesOk("50.0 between null and 5000", rule, "50.0 >= NULL AND 50.0 <= 5000");
    // Basic NOT BETWEEN predicates.
    RewritesOk("int_col between 10 and 20", rule, "int_col >= 10 AND int_col <= 20");
    RewritesOk("int_col not between 10 and 20", rule, "int_col < 10 OR int_col > 20");
    RewritesOk("50.0 not between null and 5000", rule, "50.0 < NULL OR 50.0 > 5000");
    // Nested BETWEEN predicates.
    RewritesOk("int_col between if(tinyint_col between 1 and 2, 10, 20) " + "and cast(smallint_col between 1 and 2 as int)", rule, "int_col >= if(tinyint_col >= 1 AND tinyint_col <= 2, 10, 20) " + "AND int_col <= CAST(smallint_col >= 1 AND smallint_col <= 2 AS INT)");
    // Nested NOT BETWEEN predicates.
    RewritesOk("int_col not between if(tinyint_col not between 1 and 2, 10, 20) " + "and cast(smallint_col not between 1 and 2 as int)", rule, "int_col < if(tinyint_col < 1 OR tinyint_col > 2, 10, 20) " + "OR int_col > CAST(smallint_col < 1 OR smallint_col > 2 AS INT)");
    // Mixed nested BETWEEN and NOT BETWEEN predicates.
    RewritesOk("int_col between if(tinyint_col between 1 and 2, 10, 20) " + "and cast(smallint_col not between 1 and 2 as int)", rule, "int_col >= if(tinyint_col >= 1 AND tinyint_col <= 2, 10, 20) " + "AND int_col <= CAST(smallint_col < 1 OR smallint_col > 2 AS INT)");
}

@Test
public void testExtractCommonConjunctsRule() throws ImpalaException {
    ExprRewriteRule rule = ExtractCommonConjunctRule.INSTANCE;
    // One common conjunct: int_col < 10
    RewritesOk("(int_col < 10 and bigint_col < 10) or " + "(string_col = '10' and int_col < 10)", rule, "int_col < 10 AND ((bigint_col < 10) OR (string_col = '10'))");
    // One common conjunct in multiple disjuncts: int_col < 10
    RewritesOk("(int_col < 10 and bigint_col < 10) or " + "(string_col = '10' and int_col < 10) or " + "(id < 20 and int_col < 10) or " + "(int_col < 10 and float_col > 3.14)", rule, "int_col < 10 AND " + "((bigint_col < 10) OR (string_col = '10') OR " + "(id < 20) OR (float_col > 3.14))");
    // Same as above but with a bushy OR tree.
    RewritesOk("((int_col < 10 and bigint_col < 10) or " + " (string_col = '10' and int_col < 10)) or " + "((id < 20 and int_col < 10) or " + " (int_col < 10 and float_col > 3.14))", rule, "int_col < 10 AND " + "((bigint_col < 10) OR (string_col = '10') OR " + "(id < 20) OR (float_col > 3.14))");
    // Multiple common conjuncts: int_col < 10, bool_col is null
    RewritesOk("(int_col < 10 and bigint_col < 10 and bool_col is null) or " + "(bool_col is null and string_col = '10' and int_col < 10)", rule, "int_col < 10 AND bool_col IS NULL AND " + "((bigint_col < 10) OR (string_col = '10'))");
    // Negated common conjunct: !(int_col=5 or tinyint_col > 9)
    RewritesOk("(!(int_col=5 or tinyint_col > 9) and double_col = 7) or " + "(!(int_col=5 or tinyint_col > 9) and double_col = 8)", rule, "NOT (int_col = 5 OR tinyint_col > 9) AND " + "((double_col = 7) OR (double_col = 8))");
    // Test common BetweenPredicate: int_col between 10 and 30
    RewritesOk("(int_col between 10 and 30 and bigint_col < 10) or " + "(string_col = '10' and int_col between 10 and 30) or " + "(id < 20 and int_col between 10 and 30) or " + "(int_col between 10 and 30 and float_col > 3.14)", rule, "int_col BETWEEN 10 AND 30 AND " + "((bigint_col < 10) OR (string_col = '10') OR " + "(id < 20) OR (float_col > 3.14))");
    // Test common NOT BetweenPredicate: int_col not between 10 and 30
    RewritesOk("(int_col not between 10 and 30 and bigint_col < 10) or " + "(string_col = '10' and int_col not between 10 and 30) or " + "(id < 20 and int_col not between 10 and 30) or " + "(int_col not between 10 and 30 and float_col > 3.14)", rule, "int_col NOT BETWEEN 10 AND 30 AND " + "((bigint_col < 10) OR (string_col = '10') OR " + "(id < 20) OR (float_col > 3.14))");
    // Test mixed BetweenPredicates are not common.
    RewritesOk("(int_col not between 10 and 30 and bigint_col < 10) or " + "(string_col = '10' and int_col between 10 and 30) or " + "(id < 20 and int_col not between 10 and 30) or " + "(int_col between 10 and 30 and float_col > 3.14)", rule, null);
    // All conjuncts are common.
    RewritesOk("(int_col < 10 and id between 5 and 6) or " + "(id between 5 and 6 and int_col < 10) or " + "(int_col < 10 and id between 5 and 6)", rule, "int_col < 10 AND id BETWEEN 5 AND 6");
    // Complex disjuncts are redundant.
    RewritesOk("(int_col < 10) or " + "(int_col < 10 and bigint_col < 10 and bool_col is null) or " + "(int_col < 10) or " + "(bool_col is null and int_col < 10)", rule, "int_col < 10");
    // Due to the shape of the original OR tree we are left with redundant
    // disjuncts after the extraction.
    RewritesOk("(int_col < 10 and bigint_col < 10) or " + "(string_col = '10' and int_col < 10) or " + "(id < 20 and int_col < 10) or " + "(int_col < 10 and id < 20)", rule, "int_col < 10 AND " + "((bigint_col < 10) OR (string_col = '10') OR (id < 20) OR (id < 20))");
}

