    ParserError("SHOW COLUMN STATS");
    // String literal not accepted.
    ParserError("SHOW TABLE STATS 'strlit'");
    // Missing table.
    ParserError("SHOW FILES IN");
    ParsesOk("SHOW FILES IN db.tbl PARTITION(p)");
}

