/**
 * Tests that the toSql() of plan hints use the end-of-line commented hint style
 * (for view compatibility with Hive) regardless of what style was used in the
 * original query.
 */
@Test
public void planHintsTest() {
    for (String[] hintStyle : hintStyles_) {
        String prefix = hintStyle[0];
        String suffix = hintStyle[1];
        // Hint in Insert/Upsert.
        planHintsTestForInsertAndUpsert(prefix, suffix);
        // Join hint.
        testToSql(String.format("select * from functional.alltypes a join %sbroadcast%s " + "functional.alltypes b on a.id = b.id", prefix, suffix), "SELECT * FROM functional.alltypes a INNER JOIN \n-- +broadcast\n " + "functional.alltypes b ON a.id = b.id");
        // Table hint
        testToSql(String.format("select * from functional.alltypes atp %sschedule_random_replica%s", prefix, suffix), "SELECT * FROM functional.alltypes atp\n-- +schedule_random_replica\n");
        testToSql(String.format("select * from functional.alltypes %sschedule_random_replica%s", prefix, suffix), "SELECT * FROM functional.alltypes\n-- +schedule_random_replica\n");
        testToSql(String.format("select * from functional.alltypes %sschedule_random_replica," + "schedule_disk_local%s", prefix, suffix), "SELECT * FROM functional.alltypes\n-- +schedule_random_replica," + "schedule_disk_local\n");
        testToSql(String.format("select c1 from (select atp.tinyint_col as c1 from functional.alltypes atp " + "%sschedule_random_replica%s) s1", prefix, suffix), "SELECT c1 FROM (SELECT atp.tinyint_col c1 FROM functional.alltypes atp\n-- +" + "schedule_random_replica\n) s1");
        // Select-list hint. The legacy-style hint has no prefix and suffix.
        if (prefix.contains("[")) {
            prefix = "";
            suffix = "";
        }
        // Comment-style select-list plan hint.
        testToSql(String.format("select %sstraight_join%s * from functional.alltypes", prefix, suffix), "SELECT \n-- +straight_join\n * FROM functional.alltypes");
        testToSql(String.format("select distinct %sstraight_join%s * from functional.alltypes", prefix, suffix), "SELECT DISTINCT \n-- +straight_join\n * FROM functional.alltypes");
        // Tests for analyzed/rewritten sql.
        // First test the test by passing ToSqlOptions.DEFAULT which should result in the
        // hints appearing with '--' style comments.
        testToSql(String.format("select distinct %sstraight_join%s * from functional.alltypes", prefix, suffix), "SELECT DISTINCT \n-- +straight_join\n * FROM functional.alltypes", ToSqlOptions.DEFAULT);
        // Test that analyzed queries use the '/*' style comments.
        testToSql(String.format("select distinct %sstraight_join%s * from functional.alltypes " + "where bool_col = false and id <= 5 and id >= 2", prefix, suffix), "SELECT DISTINCT /* +straight_join */ * FROM functional.alltypes " + "WHERE bool_col = FALSE AND id <= 5 AND id >= 2", ToSqlOptions.REWRITTEN);
    }
}

