        createColumnMaskingPolicy("kudu_id_mask", "functional_kudu", "alltypes", "id", user_.getShortName(), "MASK_NULL", /*maskExpr*/
        null);
        // Add an unmasked policy. It should not block updates.
        createColumnMaskingPolicy("alltypessmall_id_unmask", "functional", "alltypessmall", "id", user_.getShortName(), "MASK_NONE", /*maskExpr*/
        null);
        createColumnMaskingPolicy("alltypes_sint_mask", "functional_orc_def", "alltypes", "smallint_col", user_.getShortName(), "MASK_NULL", /*maskExpr*/
        null);
        // Create a column mask on a materialized view column. Since this
        // MV references source table with a column masking policy (defined
        // above), the expectation is that the MV's own column masking should
        // not trigger but rather the authorization exception for the
        // source table should be thrown.
        createColumnMaskingPolicy("mv1_alltypes_jointbl_c2_mask", "functional_orc_def", "mv1_alltypes_jointbl", "c2", user_.getShortName(), "MASK_NULL", /*maskExpr*/
        null);
        rangerImpalaPlugin_.refreshPoliciesAndTags();
        // Select is ok.
        authorize("select * from functional.alltypes").ok(onTable("functional", "alltypes", TPrivilegeLevel.SELECT));
        authorize("select * from functional.alltypes_view").ok(onTable("functional", "alltypes_view", TPrivilegeLevel.SELECT));
        authorize("select * from functional.alltypestiny").ok(onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // Select * from materialized view is NOT OK since one of the source
        // tables used in the join within the MV have column masking.
        authorize("select * from functional_orc_def.mv1_alltypes_jointbl").error(mvSelectError("functional_orc_def.mv1_alltypes_jointbl"), onTable("functional_orc_def", "mv1_alltypes_jointbl", TPrivilegeLevel.SELECT));
        // Select <col> from MV is NOT OK even if the column being selected was
        // originally from a non-masked table.
        authorize("select c3 from functional_orc_def.mv1_alltypes_jointbl").error(mvSelectError("functional_orc_def.mv1_alltypes_jointbl"), onTable("functional_orc_def", "mv1_alltypes_jointbl", TPrivilegeLevel.SELECT));
        // Block INSERT, TRUNCATE even given SERVER ALL privilege
        authorize("insert into functional.alltypes partition(year, month) " + "select * from functional.alltypestiny").error(insertError("functional.alltypes"), onServer(TPrivilegeLevel.ALL)).// error for 'select' appears earlier than 'insert'
