        authorize("truncate table functional.alltypes").error(insertError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("insert into functional.alltypestiny partition(year, month) " + "select * from functional.alltypessmall").error(insertError("functional.alltypestiny"), onServer(TPrivilegeLevel.ALL)).// error for 'select' appears earlier than 'insert'
        error(selectError("functional.alltypessmall"), onTable("functional", "alltypestiny", TPrivilegeLevel.ALL)).error(selectError("functional.alltypessmall"), onDatabase("functional", allExcept(TPrivilegeLevel.ALL, TPrivilegeLevel.OWNER, TPrivilegeLevel.INSERT, TPrivilegeLevel.SELECT)));
        authorize("truncate table functional.alltypestiny").error(insertError("functional.alltypestiny"), onServer(TPrivilegeLevel.ALL));
        // Block UPSERT, DELETE even given SERVER ALL privilege
        authorize("upsert into functional_kudu.alltypes " + "select * from functional.alltypes").error(accessError("functional_kudu.alltypes"), onServer(TPrivilegeLevel.ALL)).// error for 'select' appears earlier than 'access'
        error(selectError("functional.alltypes"), onTable("functional_kudu", "alltypes", TPrivilegeLevel.ALL));
        authorize("delete from functional_kudu.alltypes").error(accessError("functional_kudu.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("delete from functional_kudu.alltypes").error(accessError("functional_kudu.alltypes"), onServer(TPrivilegeLevel.ALL));
