        authorize("delete a from functional_kudu.alltypes a join functional.alltypes b " + "on a.id = b.id").error(accessError("functional_kudu.alltypes"), onServer(TPrivilegeLevel.ALL));
        // Block compute stats even given SERVER ALL privilege
        authorize("compute stats functional.alltypes").error(alterError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("compute incremental stats functional.alltypes").error(alterError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        // Block ALTER even given SERVER ALL privilege
        authorize("alter table functional.alltypes add columns (new_id int)").error(alterError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("alter table functional.alltypes drop partition (year=2009, month=1)").error(alterError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("alter view functional.alltypes_view as select 1").error(alterError("functional.alltypes_view"), onServer(TPrivilegeLevel.ALL));
        authorize("alter table functional.alltypestiny add partition (year=1, month=1)").error(alterError("functional.alltypestiny"), onServer(TPrivilegeLevel.ALL));
        // Block DROP even given SERVER ALL privilege
