        authorize("refresh functional.alltypes_view").error(refreshError("functional.alltypes_view"), onServer(TPrivilegeLevel.ALL));
        authorize("refresh functional.alltypestiny").error(refreshError("functional.alltypestiny"), onServer(TPrivilegeLevel.ALL));
        authorize("invalidate metadata functional.alltypes").error(refreshError("functional.alltypes"), onServer(TPrivilegeLevel.ALL));
        authorize("invalidate metadata functional.alltypes_view").error(refreshError("functional.alltypes_view"), onServer(TPrivilegeLevel.ALL));
        authorize("invalidate metadata functional.alltypestiny").error(refreshError("functional.alltypestiny"), onServer(TPrivilegeLevel.ALL));
        // Unmasked policy won't block updates
        authorize("insert into functional.alltypessmall partition(year, month) " + "select * from functional.alltypestiny").ok(onTable("functional", "alltypessmall", TPrivilegeLevel.INSERT), onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        authorize("alter table functional.alltypessmall add partition (year=1, month=1)").ok(onTable("functional", "alltypessmall", TPrivilegeLevel.ALTER));
