 * policy to the Ranger server to explicitly grant a user the access privileges of the
 * resources if the user is the owner of the resources.
 */
@Test
public void testRangerObjectOwnership() throws Exception {
    // 'as_owner_' is by default set to false for AuthorizationTestBase. But since this
    // test is meant for testing Ranger's behavior when the requesting user is the owner
    // of the resources, we set 'as_owner_' to true.
    as_owner_ = true;
    TQueryOptions options = new TQueryOptions();
    ImmutableSet<AuthzTest> testQueries = ImmutableSet.<AuthzTest>builder().add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select count(*) from functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select id from functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select id from functional.alltypes_view")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "show create table functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "describe functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "show create table functional.alltypes_view")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "describe functional.alltypes_view")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "describe functional.allcomplextypes.int_struct_col")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "refresh functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "invalidate metadata functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "compute stats functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "drop stats functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "create table functional.test_tbl(a int)")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "create table functional.test_tbl like functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "create table functional.test_tbl as select 1")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "create view functional.test_view as select 1")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "alter table functional.alltypes add column c1 int")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "drop table functional.alltypes")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "drop view functional.alltypes_view")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "alter view functional.alltypes_view as select 1")).add(authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "alter database functional set owner user foo")).build();
    // Run the queries.
    for (AuthzTest authz : testQueries) authz.ok();
    // Tests for more fine grained {OWNER} privileges.
    //
    // SELECT privilege.
    authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select count(*) from functional.alltypes").ok();
    authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select count(*) from functional.alltypes_view").ok();
    // The owner is granted all privileges in the following by default.
    try {
        authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select count(*) from functional.alltypes").ok();
        authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "alter table functional.alltypes add column c1 int").ok();
        authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "drop table functional.alltypes").ok();
        authorize(createAnalysisCtx(options, authzFactory_, OWNER_USER.getName()), "select count(*) from functional.alltypes_view").ok();
    } finally {
        as_owner_ = false;
    }
}

