@Test
public void testAuditsForColumnMasking() throws ImpalaException {
    String databaseName = "functional";
    String tableName = "alltypestiny";
    String[] policyNames = { "col_mask_custom", "col_mask_null", "col_mask_none", "col_mask_redact" };
    String[] columnNames = { "string_col", "date_string_col", "id", "year" };
    String[] users = { user_.getShortName(), user_.getShortName(), user_.getShortName(), "non_owner_2" };
    String[] masks = { "  {\n" + "    \"dataMaskType\": \"CUSTOM\",\n" + "    \"valueExpr\": \"concat({col}, 'xyz')\"\n" + "  }\n", "  {\n" + "    \"dataMaskType\": \"MASK_NULL\"\n" + "  }\n", // We add a mask of type "MASK_NONE" that corresponds to an "Unmasked" policy in
    // the Ranger UI to verify the respective AuthzAuditEvent is removed.
    "  {\n" + "    \"dataMaskType\": \"MASK_NONE\"\n" + "  }\n", // We add a mask of type "MASK" that corresponds to a "Redact" policy in the
    // Ranger UI for the user "non_owner_2" to verify the respective AuthzAuditEvent
    // is removed.
    "  {\n" + "    \"dataMaskType\": \"MASK\"\n" + "  }\n" };
    long[] policyIds = { -1, -1, -1, -1 };
    Set<Long> columnMaskingPolicyIds = new HashSet<>();
    List<String> policies = new ArrayList<>();
    for (int i = 0; i < masks.length; ++i) {
        String json = String.format("{\n" + "  \"name\": \"%s\",\n" + "  \"policyType\": 1,\n" + "  \"serviceType\": \"%s\",\n" + "  \"service\": \"%s\",\n" + "  \"resources\": {\n" + "    \"database\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    },\n" + "    \"table\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    },\n" + "    \"column\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    }\n" + "  },\n" + "  \"dataMaskPolicyItems\": [\n" + "    {\n" + "      \"accesses\": [\n" + "        {\n" + "          \"type\": \"select\",\n" + "          \"isAllowed\": true\n" + "        }\n" + "      ],\n" + "      \"users\": [\"%s\"],\n" + "      \"dataMaskInfo\":\n" + "%s" + "    }\n" + "  ]\n" + "}", policyNames[i], RANGER_SERVICE_TYPE, RANGER_SERVICE_NAME, databaseName, tableName, columnNames[i], users[i], masks[i]);
        policies.add(json);
    }
    try {
        for (int i = 0; i < masks.length; ++i) {
            String policyName = policyNames[i];
            String json = policies.get(i);
            policyIds[i] = createRangerPolicy(policyName, json);
            assertNotEquals("Illegal policy id", -1, policyIds[i]);
            // Only the first 3 policies apply on current user.
            if (i < 3)
                columnMaskingPolicyIds.add(policyIds[i]);
        }
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("select id, bool_col, string_col from functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id,bool_col,string_col", 1, events.get(1));
            assertEventEquals("@column", "custom", "functional/alltypestiny/string_col", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select id, bool_col, string_col from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        authzOk(events -> {
            assertEquals(4, events.size());
            assertEquals("select * from functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id,bool_col,tinyint_col,smallint_col,int_col," + "bigint_col,float_col,double_col,date_string_col,string_col,timestamp_col," + "year,month", 1, events.get(1));
            assertEventEquals("@column", "mask_null", "functional/alltypestiny/date_string_col", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[1]);
            assertEventEquals("@column", "custom", "functional/alltypestiny/string_col", 1, events.get(3));
            assertEquals(events.get(3).getPolicyId(), policyIds[0]);
        }, "select * from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // This query results in 2 calls to RangerImpalaPlugin#evalDataMaskPolicies() for
        // the column of 'string_col' during the execution of SelectStmt#analyze(). One is
        // due to the analysis of the WithClause and the other is due to the analysis of
        // the enclosing SelectStmt. Two duplicate audit log entries are thus generated for
        // this column. This test verifies that the duplicate event is indeed removed,
        // i.e., only one entry for the column of 'string_col' having accessType as
        // 'custom'.
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("with iv as (select id, bool_col, string_col from " + "functional.alltypestiny) select * from iv", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id,bool_col,string_col", 1, events.get(1));
            assertEventEquals("@column", "custom", "functional/alltypestiny/string_col", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "with iv as (select id, bool_col, string_col from functional.alltypestiny) " + "select * from iv", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // Test on masking subquery. No redundant audit events.
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("select id, string_col from functional.alltypestiny a " + "where exists (select id from functional.alltypestiny where id = a.id) " + "order by id;", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id,string_col", 1, events.get(1));
            assertEventEquals("@column", "custom", "functional/alltypestiny/string_col", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select id, string_col from functional.alltypestiny a where exists " + "(select id from functional.alltypestiny where id = a.id) order by id;", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // When the requesting user is not granted the necessary privileges, the audit log
        // entries corresponding to column masking are not generated. Notice that in the
        // case when the requesting user is not granted the necessary privileges, only the
        // event of the table that failed the authorization will be logged. Refer to
        // RangerAuthorizationChecker#authorizeTableAccess() for further details.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("with iv as (select id, bool_col, string_col from " + "functional.alltypestiny) select * from iv", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 0, events.get(0));
        }, "with iv as (select id, bool_col, string_col from functional.alltypestiny) " + "select * from iv", onTable("functional", "alltypestiny"));
        // Updates on metadata fails by column-masking policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("invalidate metadata functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "refresh", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by a column masking policy.
            assertTrue(columnMaskingPolicyIds.contains(events.get(0).getPolicyId()));
        }, "invalidate metadata functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on metadata fails by column-masking policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("compute stats functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "alter", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by a column masking policy.
            assertTrue(columnMaskingPolicyIds.contains(events.get(0).getPolicyId()));
        }, "compute stats functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on metadata fails by column-masking policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("alter table functional.alltypestiny change column id id string", events.get(0).getRequestData());
            assertEventEquals("@table", "alter", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by a column masking policy.
            assertTrue(columnMaskingPolicyIds.contains(events.get(0).getPolicyId()));
        }, "alter table functional.alltypestiny change column id id string", onServer(TPrivilegeLevel.ALL));
        // Updates on data fails by column-masking policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("truncate table functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "insert", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by a column masking policy.
            assertTrue(columnMaskingPolicyIds.contains(events.get(0).getPolicyId()));
        }, "truncate table functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on data fails by column-masking policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("insert into functional.alltypestiny partition(year, month) " + "select * from functional.alltypes", events.get(0).getRequestData());
            assertEventEquals("@table", "insert", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by a column masking policy.
            assertTrue(columnMaskingPolicyIds.contains(events.get(0).getPolicyId()));
        }, "insert into functional.alltypestiny partition(year, month) " + "select * from functional.alltypes", onServer(TPrivilegeLevel.ALL));
    } finally {
        for (int i = 0; i < masks.length; ++i) {
            String policyName = policyNames[i];
            deleteRangerPolicy(policyName);
        }
    }
}

@Test
public void testAuditsForRowFiltering() throws ImpalaException {
    // Two row filter policies will be added. The first one affects 'user_' and keeps rows
    // of "functional.alltypestiny" satisfied "id=0". The second one affects user
    // "non_owner_2" and keeps rows of "functional.alltypes" satisfied "id=1".
    String databaseName = "functional";
    String[] tableNames = { "alltypestiny", "alltypes" };
    String[] policyNames = { "tiny_filter", "all_filter" };
    String[] users = { user_.getShortName(), "non_owner_2" };
    String[] filters = { "id=0", "id=1" };
    long[] policyIds = { -1, -1 };
    List<String> policies = new ArrayList<>();
    for (int i = 0; i < filters.length; ++i) {
        String json = String.format("{\n" + "  \"name\": \"%s\",\n" + "  \"policyType\": 2,\n" + "  \"serviceType\": \"%s\",\n" + "  \"service\": \"%s\",\n" + "  \"resources\": {\n" + "    \"database\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    },\n" + "    \"table\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    }\n" + "  },\n" + "  \"rowFilterPolicyItems\": [\n" + "    {\n" + "      \"accesses\": [\n" + "        {\n" + "          \"type\": \"select\",\n" + "          \"isAllowed\": true\n" + "        }\n" + "      ],\n" + "      \"users\": [\"%s\"],\n" + "      \"rowFilterInfo\": {\"filterExpr\": \"%s\"}\n" + "    }\n" + "  ]\n" + "}", policyNames[i], RANGER_SERVICE_TYPE, RANGER_SERVICE_NAME, databaseName, tableNames[i], users[i], filters[i]);
        policies.add(json);
    }
    try {
        for (int i = 0; i < filters.length; ++i) {
            String policyName = policyNames[i];
            String json = policies.get(i);
            policyIds[i] = createRangerPolicy(policyName, json);
            assertNotEquals("Illegal policy id", -1, policyIds[i]);
        }
        // Verify row filter audits. Note that columns used in the row filter also creates
        // column access audits.
        authzOk(events -> {
