            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/bool_col,id", 1, events.get(1));
            assertEventEquals("@table", "row_filter", "functional/alltypestiny", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select bool_col from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("select 1 from functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id", 1, events.get(1));
            assertEventEquals("@table", "row_filter", "functional/alltypestiny", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select 1 from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("select count(*) from functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id", 1, events.get(1));
            assertEventEquals("@table", "row_filter", "functional/alltypestiny", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select count(*) from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // No row filters applied to current user. So no audits of row_filter.
        authzOk(events -> {
            assertEquals(1, events.size());
            assertEquals("select count(*) from functional.alltypes", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypes", 1, events.get(0));
        }, "select count(*) from functional.alltypes", onTable("functional", "alltypes", TPrivilegeLevel.SELECT));
        authzOk(events -> {
            assertEquals(3, events.size());
            assertEquals("select * from functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypestiny", 1, events.get(0));
            assertEventEquals("@column", "select", "functional/alltypestiny/id,bool_col,tinyint_col,smallint_col,int_col," + "bigint_col,float_col,double_col,date_string_col,string_col,timestamp_col," + "year,month", 1, events.get(1));
            assertEventEquals("@table", "row_filter", "functional/alltypestiny", 1, events.get(2));
            assertEquals(events.get(2).getPolicyId(), policyIds[0]);
        }, "select * from functional.alltypestiny", onTable("functional", "alltypestiny", TPrivilegeLevel.SELECT));
        // No row filters applied to current user. So no audits of row_filter.
        authzOk(events -> {
            assertEquals(2, events.size());
            assertEquals("select * from functional.alltypes", events.get(0).getRequestData());
            assertEventEquals("@table", "select", "functional/alltypes", 1, events.get(0));
