        }, "select * from functional.alltypestiny", onTable("functional", "alltypestiny"));
        // Updates on metadata fails by row-filtering policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("invalidate metadata functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "refresh", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by the row filtering policy.
            assertEquals(events.get(0).getPolicyId(), policyIds[0]);
        }, "invalidate metadata functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on metadata fails by row-filtering policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("compute stats functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "alter", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by the row filtering policy.
            assertEquals(events.get(0).getPolicyId(), policyIds[0]);
        }, "compute stats functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on metadata fails by row-filtering policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("alter table functional.alltypestiny change column id id string", events.get(0).getRequestData());
            assertEventEquals("@table", "alter", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by the row filtering policy.
            assertEquals(events.get(0).getPolicyId(), policyIds[0]);
        }, "alter table functional.alltypestiny change column id id string", onServer(TPrivilegeLevel.ALL));
        // Updates on data fails by row-filtering policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("truncate table functional.alltypestiny", events.get(0).getRequestData());
            assertEventEquals("@table", "insert", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by the row filtering policy.
            assertEquals(events.get(0).getPolicyId(), policyIds[0]);
        }, "truncate table functional.alltypestiny", onServer(TPrivilegeLevel.ALL));
        // Updates on data fails by row-filtering policies.
        authzError(events -> {
            assertEquals(1, events.size());
            assertEquals("insert into functional.alltypestiny partition(year, month) " + "select * from functional.alltypes", events.get(0).getRequestData());
            assertEventEquals("@table", "insert", "functional/alltypestiny", 0, events.get(0));
            // Make sure it's denied by the row filtering policy.
            assertEquals(events.get(0).getPolicyId(), policyIds[0]);
        }, "insert into functional.alltypestiny partition(year, month) " + "select * from functional.alltypes", onServer(TPrivilegeLevel.ALL));
    } finally {
        for (int i = 0; i < filters.length; ++i) {
            String policyName = policyNames[i];
            try {
                deleteRangerPolicy(policyName);
            } catch (RuntimeException e) {
                // ignore this to expose the original error.
            }
        }
    }
}

