/**
 * Test creates multiple reader and writer threads which operate on the test database.
 * The readers fetch the Db object and validate its owner information while the writer
 * thread changes the owner of the database concurrently
 */
@Test
public void testConcurrentAlterDbOps() throws Exception {
    ExecutorService threadPool = Executors.newFixedThreadPool(NUM_READERS + NUM_WRITERS);
    List<Future<Void>> results = new ArrayList<>(NUM_READERS + NUM_WRITERS);
    for (int i = 0; i < NUM_WRITERS; i++) {
        results.add(threadPool.submit(new SetOwnerTask()));
    }
    for (int i = 0; i < NUM_READERS; i++) {
        results.add(threadPool.submit(new ValidateDbOwnerTask()));
    }
    try {
        for (Future<Void> result : results) {
            result.get(100, TimeUnit.SECONDS);
        }
    } finally {
        threadPool.shutdownNow();
    }
}

/**
 * Test time-based invalidation in CatalogdTableInvalidator.
 */
@Test
public void testCatalogdTableInvalidator() throws CatalogException, InterruptedException {
    Reference<Boolean> tblWasRemoved = new Reference<>();
    Reference<Boolean> dbWasAdded = new Reference<>();
    String dbName = "functional";
    String tblName = "alltypes";
    catalog_.invalidateTable(new TTableName(dbName, tblName), tblWasRemoved, dbWasAdded);
    MockTicker ticker = new MockTicker();
    CatalogdTableInvalidator.TIME_SOURCE = ticker;
    catalog_.setCatalogdTableInvalidator(new CatalogdTableInvalidator(catalog_, /*unusedTableTtlSec=*/
    2, /*invalidateTablesOnMemoryPressure=*/
    false, /*oldGenFullThreshold=*/
    0.6, /*gcInvalidationFraction=*/
    0.1));
    Assert.assertFalse(catalog_.getDb(dbName).getTable(tblName).isLoaded());
    Table table = catalog_.getOrLoadTable(dbName, tblName, "test", null);
    Assert.assertTrue(table.isLoaded());
    Assert.assertEquals(ticker.now_, table.getLastUsedTime());
    long previousTriggerCount = catalog_.getCatalogdTableInvalidator().scanCount_.get();
    ticker.set(TimeUnit.SECONDS.toNanos(1));
    table.refreshLastUsedTime();
    ticker.set(TimeUnit.SECONDS.toNanos(3));
    previousTriggerCount = waitForTrigger(previousTriggerCount);
    // The last used time is refreshed so the table won't be invalidated
    Assert.assertTrue(catalog_.getTable(dbName, tblName).isLoaded());
    ticker.set(TimeUnit.SECONDS.toNanos(6));
    waitForTrigger(previousTriggerCount);
    // The table is now invalidated
    Assert.assertFalse(catalog_.getTable(dbName, tblName).isLoaded());
}

@Test
public void TestPartitionedTable() throws CatalogException {
    String[] dbNames = { "functional", "functional_avro", "functional_parquet", "functional_seq" };
    for (String dbName : dbNames) {
        Table table = catalog_.getOrLoadTable(dbName, "alltypes", "test", null);
        Assert.assertEquals(24, ((HdfsTable) table).getPartitions().size());
        Assert.assertEquals(24, ((HdfsTable) table).getPartitionIds().size());
        TTable thriftTable = getThriftTable(table);
        Assert.assertEquals(thriftTable.tbl_name, "alltypes");
        Assert.assertEquals(thriftTable.db_name, dbName);
        Assert.assertTrue(thriftTable.isSetTable_type());
        Assert.assertEquals(thriftTable.getClustering_columns().size(), 2);
        Assert.assertEquals(thriftTable.getTable_type(), TTableType.HDFS_TABLE);
        THdfsTable hdfsTable = thriftTable.getHdfs_table();
        Assert.assertTrue(hdfsTable.hdfsBaseDir != null);
        // The table has 24 partitions.
        Assert.assertEquals(24, hdfsTable.getPartitions().size());
        Assert.assertFalse(hdfsTable.getPartitions().containsKey(CatalogObjectsConstants.PROTOTYPE_PARTITION_ID));
        // The prototype partition should be included and set properly.
        Assert.assertTrue(hdfsTable.isSetPrototype_partition());
        Assert.assertEquals(CatalogObjectsConstants.PROTOTYPE_PARTITION_ID, hdfsTable.getPrototype_partition().id);
        Assert.assertNull(hdfsTable.getPrototype_partition().location);
        for (Map.Entry<Long, THdfsPartition> kv : hdfsTable.getPartitions().entrySet()) {
            Assert.assertEquals(kv.getValue().getPartitionKeyExprs().size(), 2);
        }
        // Now try to load the thrift struct.
        Table newTable = Table.fromThrift(catalog_.getDb(dbName), thriftTable);
        Assert.assertTrue(newTable instanceof HdfsTable);
        Assert.assertEquals(newTable.name_, thriftTable.tbl_name);
        Assert.assertEquals(newTable.numClusteringCols_, 2);
        // Currently only have table stats on "functional.alltypes"
        if (dbName.equals("functional"))
            Assert.assertEquals(7300, newTable.getNumRows());
        HdfsTable newHdfsTable = (HdfsTable) newTable;
        Assert.assertEquals(newHdfsTable.getPartitions().size(), 24);
        Assert.assertEquals(newHdfsTable.getPartitionIds().size(), 24);
        Collection<? extends FeFsPartition> parts = FeCatalogUtils.loadAllPartitions(newHdfsTable);
        for (FeFsPartition hdfsPart : parts) {
            Assert.assertEquals(hdfsPart.getFileDescriptors().size(), 1);
            Assert.assertTrue(hdfsPart.getFileDescriptors().get(0).getNumFileBlocks() > 0);
            // Verify the partition access level is getting set properly. The alltypes_seq
            // table has two partitions that are read_only.
            if (dbName.equals("functional_seq") && (hdfsPart.getPartitionName().equals("year=2009/month=1") || hdfsPart.getPartitionName().equals("year=2009/month=3"))) {
                Assert.assertEquals(TAccessLevel.READ_ONLY, hdfsPart.getAccessLevel());
            } else {
                Assert.assertEquals(TAccessLevel.READ_WRITE, hdfsPart.getAccessLevel());
            }
        }
        Assert.assertNotNull(newHdfsTable.prototypePartition_);
        Assert.assertEquals(((HdfsTable) table).prototypePartition_.getParameters(), newHdfsTable.prototypePartition_.getParameters());
    }
}

