    events = MetastoreEventsProcessor.getNextMetastoreEventsInBatches(eventsProcessor_.catalog_, currentEventId + 1, null, 10);
    assertEquals(2, events.size());
    events = MetastoreEventsProcessor.getNextMetastoreEventsInBatches(eventsProcessor_.catalog_, currentEventId, null, 3);
    assertEquals(3, events.size());
    events = MetastoreEventsProcessor.getNextMetastoreEventsInBatches(eventsProcessor_.catalog_, currentEventId + 3, null, 3);
    assertEquals(0, events.size());
}

