/**
 * Test compares a HdfsPartition in catalog with a test storage descriptor and confirms
 * that the comparison returns expected results.
 */
@Test
public void testCompareSds() throws Exception {
    assertNotNull(hmsPartition_);
    assertNotNull(hmsPartition_.getSd());
    StorageDescriptor hmsSd = hmsPartition_.getSd();
    HdfsTable tbl = (HdfsTable) catalog_.getOrLoadTable("functional", "alltypes", "test", null);
    HdfsPartition hdfsPartition = tbl.getPartitionsForNames(Arrays.asList("year=2009/month=1")).get(0);
    // make sure that the sd in HMS without any change matches with the sd in catalog.
    assertTrue(hdfsPartition.compareSd(hmsSd));
    // test location change
    StorageDescriptor testSd = new StorageDescriptor(hmsSd);
    testSd.setLocation("file:///tmp/year=2009/month=1");
    assertFalse(hdfsPartition.compareSd(testSd));
    // test input format change
    testSd = new StorageDescriptor(hmsSd);
    testSd.setInputFormat("org.apache.hadoop.hive.ql.io.parquet.MapredParquetInputFormat");
    assertFalse(hdfsPartition.compareSd(testSd));
    // test output format change
    testSd = new StorageDescriptor(hmsSd);
    testSd.setOutputFormat("org.apache.hadoop.hive.ql.io.parquet.MapredParquetOutputFormat");
    assertFalse(hdfsPartition.compareSd(testSd));
    // test change in cols
    testSd = new StorageDescriptor(hmsSd);
    testSd.addToCols(new FieldSchema("c1", "int", "comment"));
    assertFalse(hdfsPartition.compareSd(testSd));
    // test change in sortCols
    testSd = new StorageDescriptor(hmsSd);
    testSd.addToSortCols(new Order());
    testSd.setLocation("file:///tmp/year=2009/month=1");
    assertFalse(hdfsPartition.compareSd(testSd));
    // test serde library change
    testSd = new StorageDescriptor(hmsSd);
    testSd.setSerdeInfo(new SerDeInfo("parquet", "org.apache.hadoop.hive.ql.io.parquet.serde.ParquetHiveSerDe", new HashMap<>()));
    assertFalse(hdfsPartition.compareSd(testSd));
    // test compressed flag change
    testSd = new StorageDescriptor(hmsSd);
    testSd.setCompressed(!hmsSd.isCompressed());
    assertFalse(hdfsPartition.compareSd(testSd));
    // test number of buckets change
    testSd = new StorageDescriptor(hmsSd);
    testSd.setNumBuckets(hmsSd.getNumBuckets() + 1);
    assertFalse(hdfsPartition.compareSd(testSd));
    // test sd params change
    testSd = new StorageDescriptor(hmsSd);
    testSd.putToParameters("test", "value");
    assertFalse(hdfsPartition.compareSd(testSd));
}

@Test
public void testCompare() {
    List<List<LiteralExpr>> allLists = new ArrayList<>();
    allLists.add(valuesNull_);
    allLists.add(valuesDecimal_);
    allLists.add(valuesDecimal1_);
    allLists.add(valuesDecimal2_);
    allLists.add(valuesMixed_);
    allLists.add(valuesMixed1_);
    allLists.add(valuesMixed2_);
    for (List<LiteralExpr> l1 : allLists) {
        verifyReflexive(l1);
        for (List<LiteralExpr> l2 : allLists) {
            verifySymmetric(l1, l2);
            for (List<LiteralExpr> l3 : allLists) {
                verifyTransitive(l1, l2, l3);
            }
        }
    }
    List<LiteralExpr> valuesTest = new ArrayList<>();
    valuesTest.add(NumericLiteral.create(3));
    verifyAntiSymmetric(valuesDecimal1_, valuesTest, valuesNull_);
    valuesTest.add(NullLiteral.create(Type.BIGINT));
    verifyAntiSymmetric(valuesMixed_, valuesTest, valuesDecimal_);
}

@Test
public void testCloneWithNewHostIndex() throws Exception {
    // Fetch some metadata from a directory in HDFS.
    Path p = new Path("hdfs://localhost:20500/test-warehouse/schemas");
    ListMap<TNetworkAddress> origIndex = new ListMap<>();
    FileMetadataLoader fml = new FileMetadataLoader(p, /* recursive= */
    false, Collections.emptyList(), origIndex, /*validTxnList=*/
    null, /*writeIds=*/
    null);
    fml.load();
    List<FileDescriptor> fileDescriptors = fml.getLoadedFds();
    assertTrue(!fileDescriptors.isEmpty());
    FileDescriptor fd = fileDescriptors.get(0);
    // Get the list of locations, using the original host index.
    List<TNetworkAddress> origAddresses = getAllReplicaAddresses(fd, origIndex);
    // Make a new host index with the hosts in the opposite order.
    ListMap<TNetworkAddress> newIndex = new ListMap<>();
    newIndex.populate(Lists.reverse(origIndex.getList()));
    // Clone the FD over to the reversed index. The actual addresses should be the same.
    FileDescriptor cloned = fd.cloneWithNewHostIndex(origIndex.getList(), newIndex);
    List<TNetworkAddress> newAddresses = getAllReplicaAddresses(cloned, newIndex);
    assertEquals(origAddresses, newAddresses);
}

