    String expectedOutput = expectedOutputPrefix + " functional_kudu.alltypes (\n" + "  id INT NOT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  bool_col BOOLEAN NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  tinyint_col TINYINT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  smallint_col SMALLINT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  int_col INT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  bigint_col BIGINT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  float_col FLOAT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  double_col DOUBLE NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  date_string_col STRING NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  string_col STRING NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  timestamp_col TIMESTAMP NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  year INT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  month INT NULL ENCODING AUTO_ENCODING COMPRESSION DEFAULT_COMPRESSION,\n" + "  PRIMARY KEY (id)\n" + ")\n" + "PARTITION BY HASH (id) PARTITIONS 3\n" + "STORED AS KUDU\n" + "TBLPROPERTIES";
    if (areDefaultSynchronizedTablesExternal) {
        // Assert on the generated SQL for the table, but not the table properties, since
        // those might change based on whether this test runs before or after other
        // tests which compute stats, etc.
        String output = ToSqlUtils.getCreateTableSql(t);
        Assert.assertThat(output, CoreMatchers.startsWith(expectedOutput));
        // the tblproperties have keys which are not in a deterministic order
        // we will confirm if the 'external.table.purge'='TRUE' is available in the
        // tblproperties substring separately
        Assert.assertTrue("Synchronized Kudu tables in Hive-3 must contain external.table" + ".purge table property", output.contains("'external.table.purge'='TRUE'"));
        Assert.assertFalse("Found internal property TRANSLATED_TO_EXTERNAL in table " + "properties", output.contains("TRANSLATED_TO_EXTERNAL"));
    } else {
        // Assert on the generated SQL for the table, but not the table properties, since
        // those might change based on whether this test runs before or after other
        // tests which compute stats, etc.
        Assert.assertThat(ToSqlUtils.getCreateTableSql(t), CoreMatchers.startsWith(expectedOutput));
    }
}

