public void testIsInIgnoredDirectory() {
    // test positive cases
    assertTrue("Files in hive staging directory should be ignored", testIsInIgnoredDirectory(new Path(TEST_TABLE_PATH, "/part=1/" + ".hive-staging/tempfile")));
    assertTrue("Files in hidden directory ignored", testIsInIgnoredDirectory(new Path(TEST_TABLE_PATH, ".hidden/000000_0")));
    assertTrue("Files in the hive temporary directories should be ignored", testIsInIgnoredDirectory(new Path(TEST_TABLE_PATH, HIVE_TEMP_FILE_PREFIX + "base_0000000_1/000000_1.manifest")));
