    assertTrue("Files in spark temporary directories should be ignored", testIsInIgnoredDirectory(new Path(TEST_TABLE_PATH, SPARK_TEMP_FILE_PREFIX + "/0")));
    //multiple nested levels
    assertTrue(testIsInIgnoredDirectory(new Path(TEST_TABLE_PATH, ".hive-staging/nested-1/nested-2/nested-3/tempfile")));
