@Test
public void testIsPathOnFileSystem() throws IOException {
    List<String> schemes = Arrays.asList(FileSystemUtil.SCHEME_ABFS, FileSystemUtil.SCHEME_ABFSS, FileSystemUtil.SCHEME_ADL, FileSystemUtil.SCHEME_HDFS, FileSystemUtil.SCHEME_S3A, FileSystemUtil.SCHEME_FILE);
    List<Path> mockFiles = new ArrayList<>();
    for (String scheme : schemes) {
        mockFiles.add(new Path(mockLocation(scheme)));
    }
    List<FileSystem> fileSystems = new ArrayList<>();
    for (Path mockFile : mockFiles) {
        fileSystems.add(FileSystemUtil.getFileSystemForPath(mockFile));
    }
    for (int i = 0; i < fileSystems.size(); ++i) {
        FileSystem fs = fileSystems.get(i);
        for (int j = 0; j < mockFiles.size(); ++j) {
            Path mockFile = mockFiles.get(j);
            if (i == j) {
                assertTrue(String.format("Path '%s' should be on file system '%s'", mockFile, fs), FileSystemUtil.isPathOnFileSystem(mockFile, fs));
            } else {
                assertFalse(String.format("Path '%s' should not be on file system '%s'", mockFile, fs), FileSystemUtil.isPathOnFileSystem(mockFile, fs));
            }
        }
    }
}

