/**
 * Tests ldap authentication using impala-shell.
 */
@Test
public void testImpylaHttpLdapAuth() throws Exception {
    // 1. Valid username and password with default HTTP cookie names. Should succeed.
    String[] validCmd = buildCommand(testUser_, testPassword_, null, null);
    RunShellCommand.Run(validCmd, /*shouldSucceed*/
    true, testUser_, "");
    // Check that cookies are being used.
    verifyMetrics(Range.atLeast(1L), zero, Range.atLeast(6L), zero);
    // 2. Invalid username password combination. Should fail.
    long successBasicAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-basic-auth-success");
    long successCookieAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-cookie-auth-success");
    String[] invalidCmd = buildCommand("foo", "bar", null, null);
    RunShellCommand.Run(invalidCmd, /*shouldSucceed*/
    false, "", "HTTP code 401: Unauthorized");
    // Check that basic authentication fails after retrying three times.
    verifyMetrics(Range.closed(successBasicAuthBefore, successBasicAuthBefore), Range.closed(3L, 3L), Range.closed(successCookieAuthBefore, successCookieAuthBefore), zero);
    // 3. Without username and password. Should fail.
    long failedBasicAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-basic-auth-failure");
    String[] noAuthCmd = { "impala-python", helper_, "--query", query_ };
    RunShellCommand.Run(noAuthCmd, /*shouldSucceed*/
    false, "", "HTTP code 401: Unauthorized");
    // Check that there is no authentication attempt.
    verifyMetrics(Range.closed(successBasicAuthBefore, successBasicAuthBefore), Range.closed(failedBasicAuthBefore, failedBasicAuthBefore), Range.closed(successCookieAuthBefore, successCookieAuthBefore), zero);
    // 4. Valid username and password, but empty string for HTTP cookie names.
    // Should succeed without cookie authentication.
    String[] emptyCookieNamesCmd = buildCommand(testUser_, testPassword_, null, "");
    RunShellCommand.Run(emptyCookieNamesCmd, /*shouldSucceed*/
    true, testUser_, "");
    // Check that cookies are not being used.
    verifyMetrics(Range.atLeast(successBasicAuthBefore + 7L), Range.closed(failedBasicAuthBefore, failedBasicAuthBefore), Range.closed(successCookieAuthBefore, successCookieAuthBefore), zero);
    // 5. Valid username, password, and HTTP cookie names.
    // Should succeed with cookie authentication.
    successBasicAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-basic-auth-success");
    String[] validCookieNamesCmd = buildCommand(testUser_, testPassword_, null, "impala.auth");
    RunShellCommand.Run(validCookieNamesCmd, /*shouldSucceed*/
    true, testUser_, "");
    // Check that cookies are being used.
    verifyMetrics(Range.atLeast(successBasicAuthBefore + 1L), Range.closed(failedBasicAuthBefore, failedBasicAuthBefore), Range.atLeast(successCookieAuthBefore + 6L), zero);
    // 6. Valid username and password, but HTTP cookie names don't consist of
    // "impala.auth". Should succeed with cookie authentication failures.
    successBasicAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-basic-auth-success");
    successCookieAuthBefore = (long) client_.getMetric("impala.thrift-server.hiveserver2-http-frontend." + "total-cookie-auth-success");
    String[] nonAuthCookieNamesCmd = buildCommand(testUser_, testPassword_, null, "impala.session.id");
    RunShellCommand.Run(nonAuthCookieNamesCmd, /*shouldSucceed*/
    true, testUser_, "");
    // Check that cookies are not being used.
    verifyMetrics(Range.atLeast(successBasicAuthBefore + 7L), Range.closed(failedBasicAuthBefore, failedBasicAuthBefore), Range.closed(successCookieAuthBefore, successCookieAuthBefore), zero);
}

