@Test
public void testRangeResponse() {
    long[] exceptions = new long[1000];
    for (int i = 0; i < 1000; i++) {
        exceptions[i] = i + 100;
    }
    ValidWriteIdList writeIdList = new ValidReaderWriteIdList(tableName, exceptions, new BitSet(), 2000, 900);
    MutableValidReaderWriteIdList mutableWriteIdList = new MutableValidReaderWriteIdList(writeIdList);
    for (int i = 0; i < 100; i++) {
        assertTrue(mutableWriteIdList.isWriteIdValid(i));
    }
    assertEquals(ValidWriteIdList.RangeResponse.ALL, mutableWriteIdList.isWriteIdRangeValid(0, 99));
    for (int i = 100; i < 1100; i++) {
        assertFalse(mutableWriteIdList.isWriteIdValid(i));
    }
    assertEquals(ValidWriteIdList.RangeResponse.NONE, mutableWriteIdList.isWriteIdRangeValid(100, 1099));
    for (int i = 1100; i < 2001; i++) {
        assertTrue(mutableWriteIdList.isWriteIdValid(i));
    }
    assertFalse(mutableWriteIdList.isWriteIdValid(2001));
    assertEquals(ValidWriteIdList.RangeResponse.SOME, mutableWriteIdList.isWriteIdRangeValid(1100, 2001));
    // test for aborted write ids
    BitSet abortedBits = new BitSet();
    for (int i = 0; i < 1000; i++) {
        abortedBits.set(i);
    }
    writeIdList = new ValidReaderWriteIdList(tableName, exceptions, abortedBits, 2000, 900);
    mutableWriteIdList = new MutableValidReaderWriteIdList(writeIdList);
    for (int i = 0; i < 100; i++) {
        assertFalse(mutableWriteIdList.isWriteIdAborted(i));
    }
    assertEquals(ValidWriteIdList.RangeResponse.NONE, mutableWriteIdList.isWriteIdRangeAborted(0, 99));
    for (int i = 100; i < 1100; i++) {
        assertTrue(mutableWriteIdList.isWriteIdAborted(i));
    }
    assertEquals(ValidWriteIdList.RangeResponse.ALL, mutableWriteIdList.isWriteIdRangeAborted(100, 1099));
    for (int i = 1100; i < 2000; i++) {
        assertFalse(mutableWriteIdList.isWriteIdAborted(i));
    }
    assertEquals(ValidWriteIdList.RangeResponse.SOME, mutableWriteIdList.isWriteIdRangeAborted(100, 2000));
}

