@Test
public void testHookPostQueryExecuteInvokedCorrectly() throws Exception {
    final QueryEventHookManager mgr = createQueryEventHookManager(1, CountingQueryEventHook.class.getCanonicalName(), CountingQueryEventHook.class.getCanonicalName());
    List<Future<QueryEventHook>> futures = mgr.executeQueryCompleteHooks(mockQueryCompleteContext);
    assertEquals(futures.size(), mgr.getHooks().size());
    for (Future<QueryEventHook> f : futures) {
        CountingQueryEventHook hook = (CountingQueryEventHook) f.get(2, TimeUnit.SECONDS);
        assertEquals(1, hook.getPostQueryExecuteInvocations());
    }
    futures = mgr.executeQueryCompleteHooks(mockQueryCompleteContext);
    assertEquals(futures.size(), mgr.getHooks().size());
    for (Future<QueryEventHook> f : futures) {
        CountingQueryEventHook hook = (CountingQueryEventHook) f.get(2, TimeUnit.SECONDS);
        assertEquals(2, hook.getPostQueryExecuteInvocations());
    }
}

/**
 * Test the happy path: table with stats, no all-null cols.
 */
@Test
public void testBasicsWithStats() {
    // Return all rows. Cardinality is row count;
    verifyCardinality("SELECT id FROM functional.alltypes", 7300);
    // Return all rows. Cardinality is row count,
    // should not be influenced by limited NDV of selected
    // column.
    verifyCardinality("SELECT bool_col FROM functional.alltypes", 7300);
    // Result cardinality reduced by limited NDV.
    // Boolean column has cardinality 3 (true, false, null).
    // Since we have metadata, and know the column is non-null,
    // NDV is 2. We select one of them.
    verifyCardinality("SELECT id FROM functional.alltypes WHERE bool_col = TRUE", 7300 / 2);
    // Result cardinality reduced by NDV.
    // NDV should be 10 (from metadata).
    verifyCardinality("SELECT id FROM functional.alltypes WHERE int_col = 1", 7300 / 10);
    verifyCardinality("SELECT id FROM functional.alltypes WHERE int_col != 1", 6570);
    // IMPALA-7601 says the following should be revised.
    verifyCardinality("SELECT id FROM functional.alltypes WHERE int_col > 1", 730);
    verifyCardinality("SELECT id FROM functional.alltypes WHERE int_col > 1", 730);
    // Not using NDV of int_col, instead uses default 0.1 value.
    // Since NULL is one of the NDV's, nullvalue() is true
    // 1/NDV of the time, on average.
    verifyCardinality("SELECT id FROM functional.alltypes WHERE nullvalue(int_col)", 730);
    // IMPALA-7695: IS [NOT] NULL predicates should factor in null count.
    verifyCardinality("select id from functional.alltypesagg where tinyint_col IS NULL", 2000);
    verifyCardinality("select id from functional.alltypesagg where tinyint_col IS NOT NULL", 9000);
    verifyCardinality("select id from functional.alltypesaggnonulls where int_col IS NULL", 1);
    verifyCardinality("select id from functional.alltypesaggnonulls where int_col IS NOT NULL", 10000);
    // Grouping should reduce cardinality
    verifyCardinality("SELECT COUNT(*) FROM functional.alltypes GROUP BY int_col", 10);
    verifyCardinality("SELECT COUNT(*) FROM functional.alltypes GROUP BY id", 7300);
    verifyCardinality("SELECT COUNT(*) FROM functional.alltypes GROUP BY bool_col", 2);
    // Regression test for IMPALA-11301.
    verifyCardinality("SELECT * FROM tpcds_parquet.date_dim WHERE d_current_day != 'a'", 36525);
}

/**
 * Test tables with all-null columns. Test need for IMPALA-7310, NDV of an
 * all-null column should be 1.
 */
@Test
public void testNulls() {
    verifyCardinality("SELECT null_int FROM functional.nullrows", 26);
    // a has unique values, so NDV = 26, card = 26/26 = 1
    verifyCardinality("SELECT null_int FROM functional.nullrows WHERE id = 'x'", 1);
    // f repeats for 5 rows, so NDV=7, 26/7 =~ 4
    verifyCardinality("SELECT null_int FROM functional.nullrows WHERE group_str = 'x'", 4);
    // null_str is all nulls, NDV = 1, selectivity =0, cardinality = 0
    // PlanNode#applySelectivity, If cardinality is 0, set cardinality to 1
    // IMPALA-8647: don't round cardinality down to zero for safety.
    verifyCardinality("SELECT null_int FROM functional.nullrows WHERE null_str = 'x'", 1);
}

@Test
public void testGroupBy() {
    String baseStmt = "SELECT COUNT(*) " + "FROM functional.nullrows " + "GROUP BY ";
    // NDV(id) = 26
    verifyCardinality(baseStmt + "id", 26);
    // group_str has NDV=3
    verifyCardinality(baseStmt + "group_str", 6);
    // blank has NDV=1 (and no nulls)
    verifyCardinality(baseStmt + "blank", 1);
    // null_str is all nulls
    verifyCardinality(baseStmt + "null_str", 1);
    // NDV(id) * ndv(null_str) = 26 * 1 = 26
    verifyCardinality(baseStmt + "id, null_str", 26);
    // NDV(id) * ndv(group_str) = 26 * 3 = 78, capped at row count = 26
    verifyCardinality(baseStmt + "id, group_str", 26);
}

