/**
 * Test that agg nodes correctly gap output cardinality based on input
 * cardinality with and without stats.
 */
@Test
public void testAggregationNodeGroupByCardinalityCapping() {
    // Create the paths to the AggregationNode's of interest
    // in a distributed plan involving GROUP BY.
    // Since there are two resulting AggregationNode's, we create two paths.
    List<Integer> pathToFirstAggregationNode = Arrays.asList(0);
    List<Integer> pathToSecondAggregationNode = Arrays.asList(0, 0, 0);
    // With table and column stats available.
    verifyCardinality("select distinct id, int_col from functional.alltypes", 7300, true, ImmutableSet.of(), pathToFirstAggregationNode, AggregationNode.class);
    verifyCardinality("select distinct id, int_col from functional.alltypes", 7300, true, ImmutableSet.of(), pathToSecondAggregationNode, AggregationNode.class);
    // No column stats available but number of rows inferred from file size.
    // The estimated number of rows caps the output cardinality.
    verifyApproxCardinality("select distinct id, int_col from functional_parquet.alltypes", 12400, true, ImmutableSet.of(), pathToFirstAggregationNode, AggregationNode.class);
    verifyApproxCardinality("select distinct id, int_col from functional_parquet.alltypes", 12400, true, ImmutableSet.of(), pathToSecondAggregationNode, AggregationNode.class);
    // No column stats available and row estimation disabled - no estimate is possible.
    verifyCardinality("select distinct id, int_col from functional_parquet.alltypes", -1, true, ImmutableSet.of(PlannerTestOption.DISABLE_HDFS_NUM_ROWS_ESTIMATE), pathToFirstAggregationNode, AggregationNode.class);
    verifyCardinality("select distinct id, int_col from functional_parquet.alltypes", -1, true, ImmutableSet.of(PlannerTestOption.DISABLE_HDFS_NUM_ROWS_ESTIMATE), pathToSecondAggregationNode, AggregationNode.class);
}

