    // estimate based on the number of files.
    verifyCardinality("SELECT distinct year FROM functional_parquet.alltypes", 24, true, ImmutableSet.of(), Arrays.asList(0, 0, 0, 0), HdfsScanNode.class);
    verifyCardinality("SELECT distinct year FROM functional_parquet.alltypes", 24, true, ImmutableSet.of(PlannerTestOption.DISABLE_HDFS_NUM_ROWS_ESTIMATE), Arrays.asList(0, 0, 0, 0), HdfsScanNode.class);
}

