    verifyApproxMemoryEstimate("SELECT COUNT(*),MAX(B.BIGINT_COL) FROM " + "FUNCTIONAL.ALLTYPES A , FUNCTIONAL.ALLTYPESSMALL B, " + "FUNCTIONAL.NULLROWS C GROUP BY A.ID, B.TIMESTAMP_COL,C.BOOL_NULLS", 2190000 * (4 + 16 + 1 + 8 + 8 + 12), true, false, ImmutableSet.of(), pathToSecondAggregationNode, AggregationNode.class);
    // create a single node plan.
    verifyApproxMemoryEstimate("SELECT COUNT(*),MAX(B.BIGINT_COL) FROM " + "FUNCTIONAL.ALLTYPES A , FUNCTIONAL.ALLTYPESSMALL B, " + "FUNCTIONAL.NULLROWS C GROUP BY A.ID, B.TIMESTAMP_COL,C.BOOL_NULLS", 2190000 * (4 + 16 + 1 + 8 + 8 + 12), false, false, ImmutableSet.of(), pathToAggregationNode, AggregationNode.class);
    List<Integer> countFirstAggregationNode = Arrays.asList();
    List<Integer> countSecondAggregationNode = Arrays.asList();
    // Query has no Group by Clause
    verifyApproxMemoryEstimate("SELECT COUNT(*) FROM FUNCTIONAL.ALLTYPES A ", AggregationNode.MIN_PLAIN_AGG_MEM, true, false, ImmutableSet.of(), countFirstAggregationNode, AggregationNode.class);
    verifyApproxMemoryEstimate("SELECT COUNT(*) FROM FUNCTIONAL.ALLTYPES A ", AggregationNode.MIN_PLAIN_AGG_MEM, true, false, ImmutableSet.of(), countSecondAggregationNode, AggregationNode.class);
    // create a single node plan.
    verifyApproxMemoryEstimate("SELECT COUNT(*) FROM FUNCTIONAL.ALLTYPES A ", AggregationNode.MIN_PLAIN_AGG_MEM, false, false, ImmutableSet.of(), pathToAggregationNode, AggregationNode.class);
}

