    // FUNCTIONAL.ALLTYPES.ID's Ndv is 7300 and avgRowSize is 4
    // FUNCTIONAL.ALLTYPES.DATE_STRING_COL's Ndv is 736 and avgRowSize is 8
    // Cardinality estimate of subquery is 53290000
    // BitUtil.roundUpToPowerOf2((long) Math.ceil(3 * Cardinality / 2)) is 134217728
    // Size of Bucket is 12. Size of Duplicatenode is 16
    // Ndv estimate of subquery is 5372800
    verifyApproxMemoryEstimate("SELECT A.ID FROM (SELECT A1.ID,B1.DATE_STRING_COL " + "IDB FROM FUNCTIONAL.ALLTYPES A1 , FUNCTIONAL.ALLTYPES B1) A JOIN " + "(SELECT A1.ID,B1.DATE_STRING_COL IDB FROM FUNCTIONAL.ALLTYPES A1," + "FUNCTIONAL.ALLTYPES B1) B ON A.ID = B.ID AND A.IDB=B.IDB", 53290000L * (4L + 8L + 4L + 8L) + 134217728L * 12L + (53290000L - 5372800L) * 16L, true, true, ImmutableSet.of(), pathToJoinNode, HashJoinNode.class);
    // create a single node plan.
    verifyApproxMemoryEstimate("SELECT A.ID FROM (SELECT A1.ID,B1.DATE_STRING_COL " + "IDB FROM FUNCTIONAL.ALLTYPES A1 , FUNCTIONAL.ALLTYPES B1) A JOIN " + "(SELECT A1.ID,B1.DATE_STRING_COL IDB FROM FUNCTIONAL.ALLTYPES A1," + "FUNCTIONAL.ALLTYPES B1) B ON A.ID = B.ID AND A.IDB=B.IDB", 53290000L * (4L + 8L + 4L + 8L) + 134217728L * 12L + (53290000L - 5372800L) * 16L, false, false, ImmutableSet.of(), pathToJoinNodeSg, HashJoinNode.class);
}

