/**
 * IMPALA-9151: Tests that the planner selects the correct join strategy based on the
 * number of executors in the cluster.
 */
@Test
public void testChangeClusterSize() {
    final String query = "select * from alltypes a inner join alltypes b on a.id = b.id";
    final String broadcast_exchange = ":EXCHANGE [BROADCAST]";
    final String hash_exchange = ":EXCHANGE [HASH(b.id)]";
    // default value for the -num_expected_executors startup flag.
    final int default_num_expected_executors = 20;
    // By default no executors are registered and the planner falls back to the value of
    // -num_expected_executors, which is 20 by default.
    setNumExecutors(0, default_num_expected_executors);
    assertTrue(getExplainString(query).contains(hash_exchange));
    // Adding a single executor will make the planner switch to a broadcast join.
    setNumExecutors(1, default_num_expected_executors);
    assertTrue(getExplainString(query).contains(broadcast_exchange));
    // Adding two or more executors will make the planner switch to a partitioned hash
    // join.
    for (int n = 2; n < 5; ++n) {
        setNumExecutors(n, default_num_expected_executors);
        assertTrue(getExplainString(query).contains(hash_exchange));
    }
    // If the backend reports a single executor, the planner should fall back to a
    // broadcast join.
    setNumExecutors(1, default_num_expected_executors);
    assertTrue(getExplainString(query).contains(broadcast_exchange));
}

/**
 * IMPALA-6050: Tests that explains plans for queries that read data from multiple
 * filesystems (e.g. S3, ADLS, HDFS) accurately report the number of partitions and
 * file read from each filesystem.
 */
@Test
public void testScanNodeFsScheme() throws ImpalaException {
    List<HdfsPartition> partitions = new ArrayList<>();
    String dummyDbName = "dummy-db";
    String dummyTblName = "dummy-tbl";
    String dummyTblPath = "hdfs://localhost/" + dummyDbName + "." + dummyTblName;
    FeDb mockDb = mock(FeDb.class);
    when(mockDb.getName()).thenReturn(dummyDbName);
    FeFsTable mockFeFsTable = createMockFeFsTable(partitions, dummyTblName, mockDb);
    TupleDescriptor tupleDescriptor = createMockTupleDescriptor(mockFeFsTable);
    TableRef mockTableRef = mock(TableRef.class);
    when(mockTableRef.getTable()).thenReturn(mockFeFsTable);
    partitions.add(createMockHdfsPartition("abfs://dummy-fs@dummy-account.dfs.core" + ".windows.net/dummy-part-1", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("abfs://dummy-fs@dummy-account.dfs.core" + ".windows.net/dummy-part-2", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("abfss://dummy-fs@dummy-account.dfs.core" + ".windows.net/dummy-part-3", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("abfss://dummy-fs@dummy-account.dfs.core" + ".windows.net/dummy-part-4", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("adl://dummy-account.azuredatalakestore" + ".net/dummy-part-5", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("adl://dummy-account.azuredatalakestore" + ".net/dummy-part-6", FileSystemUtil.FsType.ADLS));
    partitions.add(createMockHdfsPartition("s3a://dummy-bucket/dummy-part-7", FileSystemUtil.FsType.S3));
    partitions.add(createMockHdfsPartition("s3a://dummy-bucket/dummy-part-8", FileSystemUtil.FsType.S3));
    partitions.add(createMockHdfsPartition(dummyTblPath + "/dummy-part-9", FileSystemUtil.FsType.HDFS));
    partitions.add(createMockHdfsPartition(dummyTblPath + "/dummy-part-10", FileSystemUtil.FsType.HDFS));
    HdfsScanNode hdfsScanNode = new HdfsScanNode(PlanNodeId.createGenerator().getNextId(), tupleDescriptor, new ArrayList<>(), partitions, mockTableRef, null, new ArrayList<>(), false);
    Analyzer mockAnalyer = createMockAnalyzer();
    hdfsScanNode.init(mockAnalyer);
    List<String> explainString = Lists.newArrayList(Splitter.on('\n').omitEmptyStrings().trimResults().split(hdfsScanNode.getNodeExplainString("", "", TExplainLevel.STANDARD)));
    Assert.assertEquals("Scan node explain string not of expected size", 4, explainString.size());
    Assert.assertTrue("Scan node explain string does not contain correct base table " + "scheme", explainString.get(0).contains("SCAN HDFS"));
    Assert.assertTrue("Scan node explain string does not correct ADLS metadata", explainString.get(1).contains("ADLS partitions=6/10 files=6 size=6B"));
    Assert.assertTrue("Scan node explain string does not correct HDFS metadata", explainString.get(2).contains("HDFS partitions=2/10 files=2 size=2B"));
    Assert.assertTrue("Scan node explain string does not correct S3 metadata", explainString.get(3).contains("S3 partitions=2/10 files=2 size=2B"));
}

