    Table propUnsetTbl = addTestTable("create table extrap_config.tbl_prop_unset (i int)");
    Table propFalseTbl = addTestTable("create table extrap_config.tbl_prop_false (i int) " + "tblproperties('impala.enable.stats.extrapolation'='false')");
    Table propTrueTbl = addTestTable("create table extrap_config.tbl_prop_true (i int) " + "tblproperties('impala.enable.stats.extrapolation'='true')");
    // Replace/restore the static backend config for this test.
    TBackendGflags gflags = BackendConfig.INSTANCE.getBackendCfg();
    boolean origEnableStatsExtrapolation = gflags.isEnable_stats_extrapolation();
    try {
        // Test --enable_stats_extrapolation=false
        gflags.setEnable_stats_extrapolation(false);
        // Table property unset --> Extrapolation disabled
        configTestExtrapolationDisabled(propUnsetTbl);
        // Table property false --> Extrapolation disabled
        configTestExtrapolationDisabled(propFalseTbl);
        // Table property true --> Extrapolation enabled
        configTestExtrapolationEnabled(propTrueTbl);
        // Test --enable_stats_extrapolation=true
        gflags.setEnable_stats_extrapolation(true);
        // Table property unset --> Extrapolation enabled
        configTestExtrapolationEnabled(propUnsetTbl);
        // Table property false --> Extrapolation disabled
        configTestExtrapolationDisabled(propFalseTbl);
        // Table property true --> Extrapolation enabled
        configTestExtrapolationEnabled(propTrueTbl);
    } finally {
        gflags.setEnable_stats_extrapolation(origEnableStatsExtrapolation);
    }
}

/**
 * Randomly picks 10 testcase files from TESTCASE_DATA_DIR and loads them into a
 * clean Catalog and makes sure that the query statement from the testcase can be
 * planned correctly without any errors.
 */
@Test
public void testTestCaseImport() throws Exception {
    FileStatus[] testCaseFiles = FileSystemUtil.getFileSystemForPath(TESTCASE_DATA_DIR).listStatus(TESTCASE_DATA_DIR);
    // Randomly pick testcases and try to replay them.
    Random rand = new Random();
    int maxIterations = 10;
    Preconditions.checkState(testCaseFiles.length > maxIterations);
    for (int i = 0; i < maxIterations; ++i) {
        FileStatus fs = testCaseFiles[rand.nextInt(testCaseFiles.length)];
        if (!fs.getPath().getName().contains(TESTCASE_FILE_PREFIX))
            continue;
        try (PlannerTestCaseLoader testCaseLoader = new PlannerTestCaseLoader()) {
            Catalog srcCatalog = testCaseLoader.getSrcCatalog();
            // Make sure the catalog is empty (just the default database).
            List<Db> dbs = srcCatalog.getDbs(PatternMatcher.MATCHER_MATCH_ALL);
            assert dbs.size() == 1 && dbs.get(0).getName().equals("default");
            // TODO: Include the source cluster plan in the testcase file and compare it
            // here with the plan computed from the local metadata.
            LOG.info(testCaseLoader.loadTestCase(fs.getPath().toString()));
            dbs = srcCatalog.getDbs(PatternMatcher.MATCHER_MATCH_ALL);
            // Atleast one new database should be loaded per testcase.
            assert dbs.size() > 1;
        }
    }
}

