    final String columnWithoutCommentName = "column_without_comment";
    final String tableWithCommentsStmt = String.format("create table %s.tbl_with_comments (%s int comment '%s', %s int) comment '%s'", dbName, columnWithCommentName, columnComment, columnWithoutCommentName, tableComment);
    Table tbl = addTestTable(tableWithCommentsStmt);
    assertNotNull(tbl);
    final String tableWithoutCommentsStmt = String.format("create table %s.tbl_without_comments (a int)", dbName);
    tbl = addTestTable(tableWithoutCommentsStmt);
