/**
 * Unit test for isPartitionColumn().
 */
@Test
public void testIsPartitionColumn() {
    {
        // Case 1
        // No partition fields: isPartitionColumn() should return false.
        int fieldId = 3;
        IcebergColumn column = new IcebergColumn("name", Type.BOOLEAN, "comment", 0, fieldId, 5, 0, true);
        List<IcebergPartitionField> fieldList = new ArrayList<>();
        IcebergPartitionSpec icebergPartitionSpec = new IcebergPartitionSpec(4, fieldList);
        assertFalse(isPartitionColumn(column, icebergPartitionSpec));
    }
    {
        // Case 2
        // A partition field source id matches a column field id: isPartitionColumn() should
        // return true.
        int id = 3;
        IcebergColumn column = new IcebergColumn("name", Type.BOOLEAN, "comment", 0, id, 105, 0, true);
        IcebergPartitionTransform icebergPartitionTransform = new IcebergPartitionTransform(TIcebergPartitionTransformType.IDENTITY);
        IcebergPartitionField field = new IcebergPartitionField(id, 106, "name", "name", icebergPartitionTransform);
        ImmutableList<IcebergPartitionField> fieldList = ImmutableList.of(field);
        IcebergPartitionSpec icebergPartitionSpec = new IcebergPartitionSpec(4, fieldList);
        assertTrue(isPartitionColumn(column, icebergPartitionSpec));
    }
    {
        // Case 3
        // Partition field source id does not match a column field id: isPartitionColumn()
        // should return false.
        IcebergColumn column = new IcebergColumn("name", Type.BOOLEAN, "comment", 0, 108, 105, 0, true);
        IcebergPartitionTransform icebergPartitionTransform = new IcebergPartitionTransform(TIcebergPartitionTransformType.IDENTITY);
        IcebergPartitionField field = new IcebergPartitionField(107, 106, "name", "name", icebergPartitionTransform);
        ImmutableList<IcebergPartitionField> fieldList = ImmutableList.of(field);
        IcebergPartitionSpec icebergPartitionSpec = new IcebergPartitionSpec(4, fieldList);
        assertFalse(isPartitionColumn(column, icebergPartitionSpec));
    }
}

@Test
public void testIntArrayList() {
    // Test add()
    IntArrayList arr = new IntArrayList();
    fillNaturalNumberSequence(arr, 10);
    assertNaturalNumberSequence(arr, 10);
    // Test removeLast()
    arr.removeLast(5);
    assertNaturalNumberSequence(arr, 5);
    fillNaturalNumberSequence(arr, 32);
    assertNaturalNumberSequence(arr, 32);
    try {
        arr.removeLast(33);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.removeLast(Integer.MAX_VALUE);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.removeLast(-1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    arr.removeLast(0);
    assertNaturalNumberSequence(arr, 32);
    // Test set()
    arr.set(0, -1);
    assert arr.get(0) == -1;
    arr.set(31, -1);
    assert arr.get(31) == -1;
    try {
        arr.set(-1, -1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.set(32, -1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    // Test clear()
    arr.clear();
    assertNaturalNumberSequence(arr, 0);
}

